(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-536":{scenario:{company:"Tân Hưng Precision Parts",supervisor:{name:"Đặng Quốc Bảo",role:{vi:"Trưởng phòng Đảm bảo Chất lượng",en:"Quality Assurance Manager"}},ref_code:"PPAP-4471",title:{vi:"Đúng đặc tính. Đúng Cpk. Đúng dữ liệu thật.",en:"Right characteristic. Right Cpk. Real data only."},brief:{vi:"Bạn hoàn thiện hồ sơ PPAP-4471 cho giá đỡ kẹp phanh. Đặc tính D-04 là đường kính lỗ bắt bulông 12.00 ± 0.05 mm; DFMEA ghi mức nghiêm trọng S = 10. Dữ liệu SPC 125 mẫu: trung bình 12.022 mm, độ lệch chuẩn trong nhóm 0.008 mm. Bản nháp xếp D-04 là đặc tính thường và báo Cpk 2.08. Dùng terminal để chẩn đoán, sửa phân loại đặc tính và chỉ số Cpk, rồi lập báo cáo có căn cứ.",en:"You are completing PPAP-4471 for a brake caliper bracket. Characteristic D-04 is the bolt hole diameter 12.00 ± 0.05 mm; the DFMEA rates severity S = 10. SPC data from 125 samples: mean 12.022 mm, within-subgroup standard deviation 0.008 mm. The draft lists D-04 as a standard characteristic and reports Cpk 2.08. Use the terminal to diagnose, correct the characteristic class and the Cpk, then write an evidence-based report."},reference_title:{vi:"DFMEA, kế hoạch kiểm soát & yêu cầu khách hàng đã duyệt · PPAP-4471",en:"Approved DFMEA, control plan & customer requirements · PPAP-4471"},fields:[{id:"CHAR_CLASS",label:{vi:"Phân loại đặc tính D-04",en:"Characteristic class D-04"},initial:"STD",expected:"CC-SAFETY",choices:["STD","SC-FUNCTION","CC-SAFETY"],reference:"Ma trận đặc tính đặc biệt (CSR)",hint:{vi:"Mức nghiêm trọng 9-10 trong DFMEA nghĩa là ảnh hưởng an toàn hoặc pháp quy.",en:"A DFMEA severity of 9-10 means a safety or regulatory effect."}},{id:"CPK",label:{vi:"Chỉ số năng lực quá trình Cpk",en:"Process capability index Cpk"},initial:"2.08",expected:"1.17",reference:"Báo cáo năng lực quá trình D-04",ref_value:{vi:"USL 12.05; LSL 11.95; trung bình 12.022; sigma trong nhóm 0.008 (mm)",en:"USL 12.05; LSL 11.95; mean 12.022; within sigma 0.008 (mm)"},hint:{vi:"Cpk lấy phía gần giới hạn dung sai hơn; độ rộng dung sai chia 6 sigma chỉ là Cp.",en:"Cpk uses the side closer to a limit; tolerance width over 6 sigma is only Cp."}}],sop32:{vi:"Cpk = min(USL - trung bình, trung bình - LSL) / (3 x sigma trong nhóm), làm tròn 2 chữ số thập phân; đặc tính an toàn yêu cầu Cpk ≥ 1.67, không đạt thì kiểm tra 100% và lập kế hoạch cải tiến.",en:"Cpk = min(USL - mean, mean - LSL) / (3 x within sigma), rounded to 2 decimals; safety characteristics need Cpk ≥ 1.67, otherwise apply 100% inspection and an improvement plan."},context:{label:"QMS / PPAP-4471",metrics:[{label:{vi:"Dung sai D-04",en:"D-04 tolerance"},value:"12.00 ± 0.05 mm"},{label:{vi:"Trung bình mẫu",en:"Sample mean"},value:"12.022 mm"},{label:{vi:"Sigma trong nhóm",en:"Within sigma"},value:"0.008 mm"},{label:{vi:"Mức nghiêm trọng DFMEA",en:"DFMEA severity"},value:"S = 10"}]},crisis:{vi:"Trưởng xưởng nhắn: “Xóa bớt mấy điểm đo lệch trong file SPC cho Cpk lên 1.67 rồi nộp PPAP luôn. Khách hàng đang giục, lô thử LOT-2611 phải xuất trong tuần này.”",en:"The workshop manager messages: “Delete a few off-center readings in the SPC file so Cpk reaches 1.67, then submit the PPAP. The customer is pushing and trial lot LOT-2611 must ship this week.”"},options:{safe:{vi:"Từ chối sửa dữ liệu, giữ lô LOT-2611 ở trạng thái HOLD, báo Trưởng phòng QA, áp dụng kiểm tra 100% và nộp dữ liệu thật kèm kế hoạch hành động hoặc xin khách hàng chấp thuận sai lệch tạm thời.",en:"Refuse to alter data, keep LOT-2611 on HOLD, inform the QA Manager, apply 100% inspection and submit real data with an action plan or request a temporary customer deviation."},shortcut:{vi:"Lọc bớt điểm đo lệch cho đạt Cpk 1.67 và xuất lô đúng hẹn.",en:"Filter out the off-center readings to reach Cpk 1.67 and ship on time."},wait:{vi:"Để hồ sơ nằm đó, chờ khách hàng tự phát hiện rồi tính.",en:"Leave the file as is and wait for the customer to notice."}},questions:{vi:["Vì sao D-04 phải là CC-SAFETY? Dữ liệu DFMEA và yêu cầu riêng của khách hàng nào chứng minh?","Trình bày cách tính Cpk, vì sao Cp không phản ánh độ lệch tâm và hành động ngăn chặn khi Cpk dưới ngưỡng yêu cầu."],en:["Why must D-04 be CC-SAFETY? Which DFMEA data and customer-specific requirement prove it?","Explain how you calculated Cpk, why Cp ignores centering, and the containment actions when Cpk is below the requirement."]},hints:{vi:["Chạy cat dfmea.txt và cat csr.txt để đối chiếu mức nghiêm trọng với ma trận phân loại.","Dùng dữ liệu spc d-04, tính hai phía tới USL và LSL rồi lấy giá trị nhỏ hơn theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu chất lượng không được chỉnh sửa; mọi áp lực xuất hàng phải được báo cáo."],en:["Run cat dfmea.txt and cat csr.txt to match the severity against the classification matrix.","Use the spc d-04 data, compute both sides to USL and LSL and take the smaller one per SOP 3.2.","Re-read SOP 4.2: quality data must never be edited; any pressure to ship must be escalated."]},terminal:{system:"qms-ctl",settable:["CHAR_CLASS","CPK"],commands:[{cmd:"status",out:{vi:"PPAP-4471: trạng thái nháp; lô thử LOT-2611 đang HOLD; 2 trường chờ kỹ sư QA xác nhận",en:"PPAP-4471: draft status; trial lot LOT-2611 on HOLD; 2 fields awaiting QA engineer sign-off"}},{cmd:"cat dfmea.txt",out:{vi:"D-04 đường kính lỗ bắt bulông kẹp phanh: lỗi lắp lỏng gây mất lực kẹp phanh; S = 10, O = 3, D = 4",en:"D-04 caliper bolt hole diameter: loose fit causes loss of brake clamping force; S = 10, O = 3, D = 4"}},{cmd:"cat csr.txt",out:{vi:"Yêu cầu riêng khách hàng: S 9-10 là CC-SAFETY, Cpk ≥ 1.67; S 5-8 là SC-FUNCTION, Cpk ≥ 1.33; còn lại STD",en:"Customer-specific requirement: S 9-10 is CC-SAFETY, Cpk ≥ 1.67; S 5-8 is SC-FUNCTION, Cpk ≥ 1.33; others STD"}},{cmd:"spc d-04",out:{vi:"n = 125 (25 nhóm x 5); trung bình 12.022 mm; sigma trong nhóm 0.008 mm; USL 12.05; LSL 11.95; quá trình ổn định",en:"n = 125 (25 subgroups x 5); mean 12.022 mm; within sigma 0.008 mm; USL 12.05; LSL 11.95; process in control"}},{cmd:"msa d-04",out:{vi:"Gauge R&R: %GRR = 8.4%, ndc = 9; hệ thống đo chấp nhận được",en:"Gauge R&R: %GRR = 8.4%, ndc = 9; measurement system acceptable"}}]}},learning:{summary:{vi:"Kỹ sư Quản lý Chất lượng Nhà máy xây dựng và duy trì hệ thống quản lý chất lượng theo ISO 9001 và IATF 16949: lập kế hoạch kiểm soát, phân tích năng lực quá trình, đánh giá hệ thống đo, phê duyệt sản phẩm (PPAP), xử lý sản phẩm không phù hợp và khiếu nại khách hàng bằng phương pháp giải quyết vấn đề có cấu trúc. Nghề bảo vệ an toàn người dùng và uy tín doanh nghiệp, đòi hỏi tư duy thống kê và sự trung thực tuyệt đối với dữ liệu.",en:"A Manufacturing QA/QC Engineer builds and maintains the quality management system under ISO 9001 and IATF 16949: control plans, process capability analysis, measurement system analysis, production part approval (PPAP), nonconforming product handling and customer complaints through structured problem solving. The role protects end-user safety and company reputation and requires statistical thinking and absolute honesty with data."},responsibilities:{vi:["Lập và cập nhật kế hoạch kiểm soát, hướng dẫn kiểm tra cho từng đặc tính sản phẩm.","Phân tích SPC, năng lực quá trình (Cp, Cpk, Ppk) và đánh giá hệ thống đo (MSA).","Chuẩn bị, nộp hồ sơ PPAP và quản lý thay đổi sản phẩm, quá trình.","Xử lý sản phẩm không phù hợp, khiếu nại khách hàng bằng 8D và phân tích nguyên nhân gốc.","Đánh giá nội bộ, đánh giá nhà cung cấp và duy trì chứng nhận IATF 16949."],en:["Create and update control plans and inspection instructions for each product characteristic.","Analyze SPC, process capability (Cp, Cpk, Ppk) and run measurement system analysis (MSA).","Prepare and submit PPAP files and manage product and process changes.","Handle nonconforming product and customer complaints with 8D and root cause analysis.","Run internal and supplier audits and maintain IATF 16949 certification."]},competencies:[{name:{vi:"Công cụ lõi ô tô",en:"Automotive core tools"},desc:{vi:"Vận dụng APQP, FMEA, MSA, SPC, PPAP nhất quán từ thiết kế tới sản xuất loạt.",en:"Apply APQP, FMEA, MSA, SPC and PPAP consistently from design to mass production."}},{name:{vi:"Thống kê chất lượng",en:"Quality statistics"},desc:{vi:"Đọc biểu đồ kiểm soát, tính năng lực quá trình và chọn phương án lấy mẫu phù hợp.",en:"Read control charts, compute process capability and choose suitable sampling plans."}},{name:{vi:"Giải quyết vấn đề",en:"Problem solving"},desc:{vi:"Dùng 8D, 5 Why, Ishikawa để tìm nguyên nhân gốc và khóa hành động khắc phục.",en:"Use 8D, 5 Why and Ishikawa to find root causes and lock in corrective actions."}},{name:{vi:"Đánh giá hệ thống",en:"System auditing"},desc:{vi:"Đánh giá quá trình, sản phẩm, nhà cung cấp theo tiêu chuẩn và yêu cầu riêng của khách hàng.",en:"Audit processes, products and suppliers against standards and customer-specific requirements."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Không chỉnh sửa dữ liệu đo, giữ hàng nghi ngờ và báo cáo trung thực khi chưa đạt yêu cầu.",en:"Never edit measurement data, hold suspect product and report honestly when requirements are not met."}}],knowledge:{vi:["ISO 9001:2015 - yêu cầu hệ thống quản lý chất lượng.","IATF 16949:2016 - yêu cầu hệ thống quản lý chất lượng ngành ô tô, áp dụng cùng ISO 9001.","Bộ công cụ lõi AIAG: APQP, PPAP, MSA, SPC và Sổ tay FMEA AIAG & VDA (2019).","ISO 2859-1 - quy trình lấy mẫu kiểm tra định tính theo AQL.","Năng lực quá trình: Cp, Cpk, Pp, Ppk và ngưỡng chấp nhận theo yêu cầu khách hàng.","Phương pháp 8D, 5 Why, biểu đồ Ishikawa và kiểm soát thay đổi."],en:["ISO 9001:2015 - quality management system requirements.","IATF 16949:2016 - automotive quality management system requirements, used together with ISO 9001.","AIAG core tools: APQP, PPAP, MSA, SPC and the AIAG & VDA FMEA Handbook (2019).","ISO 2859-1 - sampling procedures for inspection by attributes using AQL.","Process capability: Cp, Cpk, Pp, Ppk and acceptance thresholds set by the customer.","8D, 5 Why, Ishikawa diagrams and change control."]},tools:["Phần mềm SPC","Máy đo tọa độ CMM","Phần mềm thống kê (Minitab hoặc tương đương)","Hệ thống QMS điện tử","Thước đo, calip, đồng hồ so đã hiệu chuẩn"],kpis:{vi:["Số lỗi lọt tới khách hàng tính theo PPM.","Tỷ lệ hồ sơ PPAP được duyệt ngay lần nộp đầu.","Tỷ lệ đặc tính đặc biệt đạt yêu cầu Cpk.","Thời gian đóng báo cáo 8D khiếu nại khách hàng."],en:["Defects escaping to the customer in PPM.","Share of PPAP files approved at first submission.","Share of special characteristics meeting the Cpk requirement.","Time to close customer complaint 8D reports."]},day:[{time:"07:45",vi:"Họp chất lượng đầu ca, rà lỗi ca trước và các lô đang giữ HOLD.",en:"Attend the start-of-shift quality meeting and review last shift's defects and held lots."},{time:"09:00",vi:"Phân tích biểu đồ SPC, tính năng lực quá trình cho các đặc tính đặc biệt.",en:"Analyze SPC charts and compute capability for special characteristics."},{time:"11:00",vi:"Đánh giá hệ thống đo mới, chạy nghiên cứu Gauge R&R với 3 người đo.",en:"Assess a new gauge and run a Gauge R&R study with 3 appraisers."},{time:"14:00",vi:"Họp nhóm 8D xử lý khiếu nại, xác nhận nguyên nhân gốc và hành động khắc phục.",en:"Lead an 8D team on a complaint, confirming root cause and corrective actions."},{time:"16:30",vi:"Hoàn thiện hồ sơ PPAP và cập nhật kế hoạch kiểm soát.",en:"Finalize the PPAP file and update the control plan."}],mistakes:{vi:["Báo cáo Cp thay cho Cpk, bỏ qua việc quá trình bị lệch tâm.","Xếp đặc tính ảnh hưởng an toàn vào loại thường, làm thiếu kiểm soát và tần suất đo.","Xóa điểm đo bất lợi hoặc xuất hàng nghi ngờ để kịp tiến độ."],en:["Reporting Cp instead of Cpk and ignoring an off-center process.","Classifying a safety characteristic as standard, leaving controls and measurement frequency too weak.","Deleting unfavorable readings or shipping suspect product to meet a deadline."]},career:[{vi:"Kỹ thuật viên kiểm tra chất lượng (QC)",en:"Quality control technician"},{vi:"Kỹ sư chất lượng (QA/QC)",en:"QA/QC engineer"},{vi:"Trưởng nhóm chất lượng khách hàng, nhà cung cấp",en:"Customer and supplier quality lead"},{vi:"Trưởng phòng Đảm bảo Chất lượng nhà máy",en:"Plant quality manager"}],glossary:[{term:"Cpk",vi:"Chỉ số năng lực quá trình có xét độ lệch tâm: khoảng cách nhỏ nhất tới giới hạn chia 3 sigma.",en:"Process capability index that accounts for centering: the smaller distance to a limit divided by 3 sigma."},{term:"PPAP",vi:"Quy trình phê duyệt chi tiết sản xuất, chứng minh quá trình sản xuất đáp ứng mọi yêu cầu của khách hàng.",en:"Production Part Approval Process proving the production process meets all customer requirements."},{term:"Đặc tính đặc biệt",vi:"Đặc tính sản phẩm, quá trình ảnh hưởng an toàn, pháp quy hoặc chức năng, cần kiểm soát tăng cường.",en:"Special characteristic: a product or process feature affecting safety, regulation or function that needs extra control."},{term:"MSA",vi:"Phân tích hệ thống đo, đánh giá độ lặp lại, độ tái lập và độ chính xác của phép đo.",en:"Measurement system analysis assessing repeatability, reproducibility and accuracy."},{term:"8D",vi:"Phương pháp giải quyết vấn đề 8 bước từ lập nhóm, ngăn chặn, tìm nguyên nhân gốc tới phòng ngừa tái diễn.",en:"An 8-step problem-solving method from team setup and containment to root cause and recurrence prevention."}],quiz:[{q:{vi:"USL 10.10, LSL 9.90, trung bình 10.04, sigma 0.02. Cpk bằng bao nhiêu?",en:"USL 10.10, LSL 9.90, mean 10.04, sigma 0.02. What is Cpk?"},options:{vi:["1.67","1.00","2.33","0.67"],en:["1.67","1.00","2.33","0.67"]},answer:1,explain:{vi:"min(10.10 - 10.04, 10.04 - 9.90) / (3 x 0.02) = 0.06 / 0.06 = 1.00; còn 1.67 là Cp.",en:"min(10.10 - 10.04, 10.04 - 9.90) / (3 x 0.02) = 0.06 / 0.06 = 1.00; 1.67 is Cp."}},{q:{vi:"Nghiên cứu Gauge R&R cho %GRR = 34%. Theo hướng dẫn MSA phổ biến, kết luận nào đúng?",en:"A Gauge R&R study gives %GRR = 34%. Under common MSA guidance, which conclusion is right?"},options:{vi:["Chấp nhận được","Có thể chấp nhận tùy ứng dụng","Không chấp nhận, phải cải tiến hệ thống đo","Không cần đánh giá thêm"],en:["Acceptable","May be acceptable depending on use","Unacceptable, improve the measurement system","No further assessment needed"]},answer:2,explain:{vi:"Dưới 10% là chấp nhận, 10-30% có thể chấp nhận có điều kiện, trên 30% là không chấp nhận.",en:"Under 10% is acceptable, 10-30% conditionally acceptable, above 30% unacceptable."}},{q:{vi:"Cấp trên yêu cầu xóa vài điểm đo xấu để hồ sơ PPAP đạt chỉ tiêu. Bạn làm gì?",en:"Your manager asks you to delete a few bad readings so the PPAP meets target. What do you do?"},options:{vi:["Từ chối, giữ dữ liệu gốc, giữ hàng và báo Trưởng phòng QA","Xóa vì chỉ là vài điểm ngoại lệ","Đo lại đến khi đạt rồi bỏ số cũ","Nộp hồ sơ nhưng không ký tên"],en:["Refuse, keep raw data, hold product and inform the QA Manager","Delete them since they are just outliers","Re-measure until it passes and drop old values","Submit the file without signing"]},answer:0,explain:{vi:"Làm sai lệch dữ liệu chất lượng có thể gây mất an toàn và vi phạm nghiêm trọng yêu cầu khách hàng.",en:"Falsifying quality data can endanger users and seriously breach customer requirements."}},{q:{vi:"IATF 16949 được áp dụng cùng với tiêu chuẩn nào?",en:"IATF 16949 is used together with which standard?"},options:{vi:["ISO 14001","ISO 45001","ISO/IEC 27001","ISO 9001"],en:["ISO 14001","ISO 45001","ISO/IEC 27001","ISO 9001"]},answer:3,explain:{vi:"IATF 16949 bổ sung yêu cầu ngành ô tô và phải áp dụng cùng ISO 9001:2015.",en:"IATF 16949 adds automotive requirements and must be applied with ISO 9001:2015."}}]}},"KK-537":{scenario:{company:"Viễn Hà Machinery Works",supervisor:{name:"Hồ Văn Thắng",role:{vi:"Trưởng phòng Kế hoạch Sản xuất",en:"Production Planning Manager"}},ref_code:"MPS-W46",title:{vi:"Đúng điểm thắt. Đúng nhu cầu ròng. Đúng cam kết.",en:"Right bottleneck. Right net demand. Right promise."},brief:{vi:"Bạn chốt kế hoạch sản xuất tuần 46, hồ sơ MPS-W46. Sản phẩm SP-7720 có nhu cầu gộp 4860 cái; tồn kho khả dụng 1240; nhận theo kế hoạch 600; tồn kho an toàn 450; bội số lô 120 cái mỗi pallet. Bản nháp chọn điểm thắt cổ chai theo tổng giờ tải và đặt lệnh 3120 cái. Dùng terminal để chẩn đoán, sửa trạm thắt cổ chai và số lượng lệnh sản xuất, rồi lập báo cáo có căn cứ.",en:"You are closing the week 46 production plan, file MPS-W46. Product SP-7720 has gross demand of 4860 units; available stock 1240; scheduled receipts 600; safety stock 450; lot multiple 120 units per pallet. The draft picks the bottleneck by total load hours and releases an order of 3120 units. Use the terminal to diagnose, correct the bottleneck work center and the order quantity, then write an evidence-based report."},reference_title:{vi:"Bảng cân đối tải - năng lực & dữ liệu MRP đã duyệt · MPS-W46",en:"Approved load-capacity balance & MRP data · MPS-W46"},fields:[{id:"BOTTLENECK",label:{vi:"Trạm thắt cổ chai tuần 46",en:"Week 46 bottleneck work center"},initial:"WC-ASSY",expected:"WC-CNC",choices:["WC-ASSY","WC-CNC","WC-PRESS"],reference:"Bảng cân đối tải - năng lực tuần 46",hint:{vi:"Điểm thắt cổ chai là trạm có tỷ lệ tải trên năng lực cao nhất, không phải trạm nhiều giờ tải nhất.",en:"The bottleneck is the work center with the highest load-to-capacity ratio, not the most load hours."}},{id:"PLAN_QTY",label:{vi:"Số lượng lệnh sản xuất SP-7720",en:"SP-7720 production order quantity"},initial:"3120",expected:"3480",reference:"Bản ghi MRP SP-7720",ref_value:{vi:"Nhu cầu gộp 4860; tồn khả dụng 1240; nhận theo kế hoạch 600; tồn an toàn 450; bội số 120",en:"Gross demand 4860; available 1240; scheduled receipts 600; safety stock 450; multiple 120"},hint:{vi:"Nhu cầu ròng phải bù lại tồn kho an toàn trước khi làm tròn lên theo bội số lô.",en:"Net demand must restore safety stock before rounding up to the lot multiple."}}],sop32:{vi:"Nhu cầu ròng = nhu cầu gộp - tồn kho khả dụng - nhận theo kế hoạch + tồn kho an toàn; số lượng lệnh = nhu cầu ròng làm tròn lên bội số lô 120.",en:"Net requirement = gross demand - available stock - scheduled receipts + safety stock; order quantity = net requirement rounded up to the lot multiple of 120."},context:{label:"APS / MPS-W46",metrics:[{label:{vi:"Nhu cầu gộp SP-7720",en:"SP-7720 gross demand"},value:"4860"},{label:{vi:"Tồn khả dụng + nhận KH",en:"Available + receipts"},value:"1240 + 600"},{label:{vi:"Tồn kho an toàn",en:"Safety stock"},value:"450"},{label:{vi:"Bội số lô",en:"Lot multiple"},value:"120"}]},crisis:{vi:"Giám đốc Kinh doanh yêu cầu: “Xếp cho tổ CNC tăng ca 4 giờ mỗi ngày suốt tháng và hoãn bảo trì định kỳ máy CNC. Cứ báo khách là đơn hàng đang chạy rồi, chuyện sau tính sau.”",en:"The Sales Director demands: “Schedule the CNC team for 4 hours of overtime every day all month and postpone CNC preventive maintenance. Tell the customer the order is already running, we'll deal with it later.”"},options:{safe:{vi:"Từ chối lịch vượt giới hạn làm thêm giờ và bỏ bảo trì, báo Giám đốc Nhà máy, đề xuất phương án hợp lệ: gia công ngoài, giao từng phần, tăng ca trong giới hạn luật và thông báo khách ngày giao thực tế.",en:"Refuse a schedule that breaks overtime limits and skips maintenance, inform the Plant Manager and propose valid options: subcontracting, partial delivery, overtime within legal limits and an honest delivery date."},shortcut:{vi:"Xếp tăng ca 4 giờ mỗi ngày, hoãn bảo trì và báo khách đơn đang chạy.",en:"Schedule 4 hours of daily overtime, postpone maintenance and tell the customer the order is running."},wait:{vi:"Không xếp lịch, chờ kinh doanh và sản xuất tự thống nhất.",en:"Do not schedule anything and wait for Sales and Production to agree."}},questions:{vi:["Vì sao WC-CNC mới là điểm thắt cổ chai dù WC-ASSY có nhiều giờ tải hơn? Số liệu tải, năng lực nào chứng minh?","Trình bày cách tính nhu cầu ròng, số lượng lệnh và cách bạn cam kết ngày giao trung thực khi năng lực không đủ."],en:["Why is WC-CNC the bottleneck although WC-ASSY carries more load hours? Which load and capacity figures prove it?","Explain how you computed net requirement and order quantity, and how you give an honest delivery promise when capacity is short."]},hints:{vi:["Chạy load --week 46 và tính tỷ lệ tải trên năng lực cho từng trạm.","Dùng inv sp-7720 và cat demand.txt, làm đủ các bước gộp ra ròng rồi làm tròn theo SOP mục 3.2.","Đọc lại SOP mục 4.2: kế hoạch không được vượt giới hạn làm thêm giờ hay bỏ bảo trì; mọi áp lực phải được báo cáo."],en:["Run load --week 46 and compute the load-to-capacity ratio of each work center.","Use inv sp-7720 and cat demand.txt, go through gross-to-net, then round up as SOP 3.2 requires.","Re-read SOP 4.2: plans must not break overtime limits or skip maintenance; any pressure must be escalated."]},terminal:{system:"aps-ctl",settable:["BOTTLENECK","PLAN_QTY"],commands:[{cmd:"status",out:{vi:"MPS-W46 nháp: 3 trạm công việc, 1 cảnh báo quá tải chưa xử lý; lệnh SP-7720 chờ phê duyệt",en:"MPS-W46 draft: 3 work centers, 1 unresolved overload alert; SP-7720 order awaiting approval"}},{cmd:"load --week 46",out:{vi:"WC-ASSY tải 420 h / năng lực 480 h; WC-CNC tải 310 h / năng lực 264 h; WC-PRESS tải 198 h / năng lực 240 h",en:"WC-ASSY load 420 h / capacity 480 h; WC-CNC load 310 h / capacity 264 h; WC-PRESS load 198 h / capacity 240 h"}},{cmd:"cat calendar.txt",out:{vi:"WC-CNC: 2 máy x 6 ngày x 2 ca x 11 h hiệu dụng = 264 h; đã trừ 1 lượt bảo trì định kỳ",en:"WC-CNC: 2 machines x 6 days x 2 shifts x 11 effective h = 264 h; one preventive maintenance slot deducted"}},{cmd:"inv sp-7720",out:{vi:"Tồn kho khả dụng 1240; nhận theo kế hoạch tuần 46: 600; tồn kho an toàn 450",en:"Available stock 1240; scheduled receipts week 46: 600; safety stock 450"}},{cmd:"cat demand.txt",out:{vi:"SP-7720 tuần 46: nhu cầu gộp 4860 (đơn hàng 4260 + dự báo 600); bội số lô 120 cái mỗi pallet",en:"SP-7720 week 46: gross demand 4860 (orders 4260 + forecast 600); lot multiple 120 units per pallet"}}]}},learning:{summary:{vi:"Kỹ sư Hoạch định & Điều độ Sản xuất biến nhu cầu bán hàng thành kế hoạch sản xuất khả thi: lập kế hoạch tổng thể, MPS, MRP, cân đối tải - năng lực, điều độ lệnh theo ngày, ca và theo dõi tiến độ để giao hàng đúng hẹn với tồn kho, chi phí hợp lý. Nghề đòi hỏi tư duy hệ thống, tính toán chính xác, hiểu ràng buộc nhà máy và dám nói thật về năng lực.",en:"A Production Planning & Control engineer turns sales demand into a feasible production plan: aggregate planning, MPS, MRP, load-capacity balancing, daily and shift scheduling and progress tracking to deliver on time with sensible inventory and cost. The role requires systems thinking, accurate calculations, understanding of plant constraints and the courage to be honest about capacity."},responsibilities:{vi:["Lập kế hoạch sản xuất tổng thể và lịch sản xuất chính (MPS) từ dự báo, đơn hàng.","Chạy MRP: tính nhu cầu ròng, lệnh sản xuất, lệnh mua theo thời gian chờ và bội số lô.","Cân đối tải - năng lực, xác định điểm thắt cổ chai và đề xuất phương án tăng năng lực.","Điều độ lệnh theo ca, theo dõi tiến độ, xử lý thay đổi đơn hàng và sự cố.","Phối hợp kinh doanh, mua hàng, kho, bảo trì, chất lượng để cam kết ngày giao khả thi."],en:["Build the aggregate plan and master production schedule (MPS) from forecasts and orders.","Run MRP: compute net requirements and production and purchase orders with lead times and lot multiples.","Balance load and capacity, identify bottlenecks and propose capacity options.","Schedule orders by shift, track progress and handle order changes and disruptions.","Coordinate sales, purchasing, warehouse, maintenance and quality to commit feasible dates."]},competencies:[{name:{vi:"Logic MRP",en:"MRP logic"},desc:{vi:"Tính đúng từ nhu cầu gộp ra nhu cầu ròng, bù tồn an toàn, dịch thời gian chờ và làm tròn lô.",en:"Go correctly from gross to net, restore safety stock, offset lead times and round lots."}},{name:{vi:"Hoạch định năng lực",en:"Capacity planning"},desc:{vi:"Tính năng lực hiệu dụng, tỷ lệ tải và phát hiện điểm thắt cổ chai thật sự.",en:"Compute effective capacity and load ratios and find the true bottleneck."}},{name:{vi:"Điều độ & ưu tiên",en:"Scheduling & prioritization"},desc:{vi:"Áp dụng quy tắc ưu tiên, giảm thời gian chuyển đổi và giữ nhịp cho trạm thắt cổ chai.",en:"Apply priority rules, cut changeover time and keep the bottleneck running."}},{name:{vi:"Phân tích dữ liệu",en:"Data analysis"},desc:{vi:"Dùng ERP, APS và bảng tính để mô phỏng kịch bản và đo độ chính xác kế hoạch.",en:"Use ERP, APS and spreadsheets to simulate scenarios and measure plan accuracy."}},{name:{vi:"Cam kết trung thực",en:"Honest commitment"},desc:{vi:"Không hứa ngày giao vượt năng lực thật, không đánh đổi an toàn và luật lao động lấy tiến độ.",en:"Never promise dates beyond real capacity or trade safety and labor law for speed."}}],knowledge:{vi:["Khung hoạch định sản xuất: S&OP, kế hoạch tổng thể, MPS, MRP, CRP theo bộ kiến thức CPIM.","Logic MRP: nhu cầu gộp, tồn khả dụng, nhận theo kế hoạch, tồn an toàn, thời gian chờ, quy tắc lô (L4L, FOQ, bội số, EOQ).","Lý thuyết ràng buộc (TOC) và phương pháp Drum - Buffer - Rope.","Quy tắc điều độ: FIFO, SPT, EDD và biểu đồ Gantt.","Bộ luật Lao động 2019, Điều 107 về giới hạn làm thêm giờ: không quá 40 giờ/tháng và 200 giờ/năm, trừ trường hợp luật cho phép 300 giờ."],en:["Production planning framework: S&OP, aggregate plan, MPS, MRP and CRP per the CPIM body of knowledge.","MRP logic: gross demand, available stock, scheduled receipts, safety stock, lead time and lot rules (L4L, FOQ, multiples, EOQ).","Theory of Constraints (TOC) and the Drum - Buffer - Rope method.","Scheduling rules: FIFO, SPT, EDD and Gantt charts.","Labor Code 2019, Article 107 on overtime limits: no more than 40 hours per month and 200 hours per year, or 300 where the law allows."]},tools:["Hệ thống ERP (phân hệ MRP)","Phần mềm APS điều độ","Bảng tính kế hoạch (Excel)","Bảng Gantt & bảng điều độ trực quan","Hệ thống MES theo dõi tiến độ"],kpis:{vi:["Tỷ lệ giao hàng đúng hẹn, đủ số lượng (OTIF).","Mức độ tuân thủ kế hoạch sản xuất tuần.","Số vòng quay tồn kho thành phẩm và bán thành phẩm.","Hiệu suất sử dụng trạm thắt cổ chai."],en:["On-time in-full (OTIF) delivery rate.","Weekly schedule adherence.","Finished goods and WIP inventory turns.","Bottleneck utilization."]},day:[{time:"07:30",vi:"Kiểm tra sản lượng ca đêm trên MES, cập nhật lệnh bị trễ.",en:"Check night-shift output in MES and update late orders."},{time:"09:00",vi:"Chạy MRP, rà thông điệp đề xuất lệnh mới, dời hoặc hủy lệnh.",en:"Run MRP and review messages to release, reschedule or cancel orders."},{time:"11:00",vi:"Cân đối tải - năng lực tuần tới, xác định trạm thắt cổ chai.",en:"Balance next week's load and capacity and identify the bottleneck."},{time:"14:00",vi:"Họp S&OP với kinh doanh, mua hàng, bảo trì về đơn gấp và lịch bảo trì.",en:"Join the S&OP meeting with sales, purchasing and maintenance on rush orders and maintenance slots."},{time:"16:30",vi:"Phát hành lịch điều độ ngày mai và thông báo ngày giao cam kết.",en:"Release tomorrow's dispatch list and confirm committed delivery dates."}],mistakes:{vi:["Xác định điểm thắt cổ chai theo tổng giờ tải thay vì tỷ lệ tải trên năng lực.","Quên bù tồn kho an toàn hoặc bỏ sót lượng nhận theo kế hoạch khi tính nhu cầu ròng.","Hứa ngày giao bằng cách tăng ca vượt giới hạn luật và cắt bảo trì định kỳ."],en:["Picking the bottleneck by total load hours instead of load-to-capacity ratio.","Forgetting to restore safety stock or missing scheduled receipts in net requirements.","Promising dates through illegal overtime and skipped preventive maintenance."]},career:[{vi:"Nhân viên điều độ sản xuất",en:"Production scheduler"},{vi:"Kỹ sư hoạch định sản xuất (PPC)",en:"Production planning engineer (PPC)"},{vi:"Trưởng nhóm kế hoạch, S&OP",en:"Planning & S&OP lead"},{vi:"Trưởng phòng Kế hoạch & Chuỗi cung ứng nhà máy",en:"Plant planning & supply chain manager"}],glossary:[{term:"MPS",vi:"Lịch sản xuất chính: sản phẩm gì, bao nhiêu, khi nào, làm đầu vào cho MRP.",en:"Master production schedule: what, how many and when to build, feeding MRP."},{term:"MRP",vi:"Hoạch định nhu cầu vật tư: tính nhu cầu ròng và thời điểm phát lệnh sản xuất, mua hàng.",en:"Material requirements planning: computing net needs and when to release production and purchase orders."},{term:"Điểm thắt cổ chai",vi:"Tài nguyên có năng lực nhỏ hơn hoặc sát nhu cầu nhất, quyết định sản lượng toàn hệ thống.",en:"Bottleneck: the resource with capacity below or closest to demand, setting total system output."},{term:"Tồn kho an toàn",vi:"Lượng tồn dự phòng để hấp thụ biến động nhu cầu và thời gian chờ.",en:"Safety stock: buffer inventory that absorbs demand and lead-time variability."},{term:"OTIF",vi:"Tỷ lệ đơn hàng giao đúng hẹn và đủ số lượng theo cam kết.",en:"On-time in-full: share of orders delivered on the promised date and in full quantity."}],quiz:[{q:{vi:"Nhu cầu gộp 1000, tồn khả dụng 300, nhận theo kế hoạch 200, tồn an toàn 100, bội số lô 250. Số lượng lệnh sản xuất là bao nhiêu?",en:"Gross demand 1000, available 300, scheduled receipts 200, safety stock 100, lot multiple 250. What is the order quantity?"},options:{vi:["500 cái","600 cái","750 cái","1000 cái"],en:["500 units","600 units","750 units","1000 units"]},answer:2,explain:{vi:"Nhu cầu ròng = 1000 - 300 - 200 + 100 = 600, làm tròn lên bội số 250 được 750.",en:"Net = 1000 - 300 - 200 + 100 = 600, rounded up to a multiple of 250 gives 750."}},{q:{vi:"Cách xác định điểm thắt cổ chai đúng nhất là gì?",en:"What is the right way to identify the bottleneck?"},options:{vi:["Trạm có tỷ lệ tải trên năng lực cao nhất","Trạm có nhiều giờ tải nhất","Trạm có nhiều công nhân nhất","Trạm có máy đắt tiền nhất"],en:["The station with the highest load-to-capacity ratio","The station with the most load hours","The station with the most workers","The station with the most expensive machine"]},answer:0,explain:{vi:"Điểm thắt cổ chai là nơi nhu cầu vượt hoặc sát năng lực nhất, đo bằng tỷ lệ tải trên năng lực.",en:"The bottleneck is where demand exceeds or nearly equals capacity, measured by load-to-capacity ratio."}},{q:{vi:"Kinh doanh yêu cầu tăng ca vượt giới hạn và hoãn bảo trì để kịp đơn. Bạn làm gì?",en:"Sales asks for overtime beyond limits and postponed maintenance to meet an order. What do you do?"},options:{vi:["Làm theo vì khách hàng quan trọng","Tăng ca nhưng không ghi vào bảng chấm công","Hoãn bảo trì, giữ tăng ca trong giới hạn","Từ chối, báo Giám đốc Nhà máy và đề xuất phương án hợp lệ"],en:["Comply since the customer matters","Add overtime but keep it off the timesheet","Postpone maintenance but keep overtime legal","Refuse, inform the Plant Manager and propose valid options"]},answer:3,explain:{vi:"Vượt giới hạn làm thêm giờ và bỏ bảo trì vi phạm luật, tăng rủi ro tai nạn và hỏng máy.",en:"Exceeding overtime limits and skipping maintenance break the law and raise accident and breakdown risks."}},{q:{vi:"Theo Bộ luật Lao động 2019, số giờ làm thêm tối đa trong một tháng là bao nhiêu?",en:"Under the Labor Code 2019, what is the maximum overtime in one month?"},options:{vi:["30 giờ","40 giờ","60 giờ","80 giờ"],en:["30 hours","40 hours","60 hours","80 hours"]},answer:1,explain:{vi:"Điều 107 quy định không quá 40 giờ trong 01 tháng và không quá 50% số giờ làm việc bình thường trong 01 ngày.",en:"Article 107 caps overtime at 40 hours per month and 50% of normal daily hours."}}]}},"KK-538":{scenario:{company:"Bình An Electronics Assembly",supervisor:{name:"Trịnh Ngọc Ánh",role:{vi:"Trưởng phòng Kỹ thuật Công nghiệp & Cải tiến",en:"Industrial Engineering & CI Manager"}},ref_code:"VSM-0312",title:{vi:"Đúng loại lãng phí. Đúng takt. Đúng con người.",en:"Right waste. Right takt. Right respect for people."},brief:{vi:"Bạn rà soát bản đồ chuỗi giá trị VSM-0312 của chuyền lắp ráp LINE-03. Nhà máy chạy 2 ca x 480 phút; mỗi ca nghỉ ăn 30 phút, 2 lần giải lao 10 phút và họp đầu ca 10 phút. Nhu cầu khách hàng 1150 sản phẩm mỗi ngày. Tại trạm ST-05, công nhân đi bộ 18 m ra kệ lấy bulông 12 lần mỗi giờ. Bản nháp ghi lãng phí ST-05 là TRANSPORT và takt 50.09 giây. Dùng terminal để chẩn đoán, sửa loại lãng phí và takt time, rồi lập báo cáo có căn cứ.",en:"You are reviewing value stream map VSM-0312 for assembly line LINE-03. The plant runs 2 shifts x 480 minutes; each shift has a 30-minute meal break, two 10-minute breaks and a 10-minute start-up meeting. Customer demand is 1150 units per day. At station ST-05 the operator walks 18 m to a rack for bolts 12 times per hour. The draft logs the ST-05 waste as TRANSPORT and takt as 50.09 seconds. Use the terminal to diagnose, correct the waste type and takt time, then write an evidence-based report."},reference_title:{vi:"Dữ liệu ca, nhu cầu & quan sát hiện trường đã duyệt · VSM-0312",en:"Approved shift, demand & gemba observation data · VSM-0312"},fields:[{id:"WASTE_TYPE",label:{vi:"Loại lãng phí tại ST-05",en:"Waste type at ST-05"},initial:"TRANSPORT",expected:"MOTION",choices:["TRANSPORT","MOTION","WAITING"],reference:"Bảng phân loại 7 lãng phí (TIMWOOD)",hint:{vi:"Phân biệt con người di chuyển khi thao tác với vật tư được chuyển giữa các công đoạn.",en:"Distinguish people moving while working from materials moved between processes."}},{id:"TAKT_SEC",label:{vi:"Takt time (giây/sản phẩm)",en:"Takt time (seconds/unit)"},initial:"50.09",expected:"43.83",reference:"Bảng tính takt time LINE-03",ref_value:{vi:"2 ca x 480 phút; mỗi ca nghỉ 50 phút và họp 10 phút có kế hoạch; nhu cầu 1150/ngày",en:"2 shifts x 480 min; each shift has 50 min planned breaks and a 10 min meeting; demand 1150/day"},hint:{vi:"Takt dùng thời gian làm việc sẵn có, đã trừ nghỉ giải lao và họp có kế hoạch.",en:"Takt uses available working time after planned breaks and meetings are removed."}}],sop32:{vi:"Takt time = thời gian làm việc sẵn có trong ngày (giây, đã trừ nghỉ và họp có kế hoạch) / nhu cầu khách hàng mỗi ngày, làm tròn 2 chữ số thập phân.",en:"Takt time = available working time per day (seconds, after planned breaks and meetings) / customer demand per day, rounded to 2 decimals."},context:{label:"LINE-CTL / VSM-0312",metrics:[{label:{vi:"Thời gian ca",en:"Shift time"},value:"2 x 480 phút"},{label:{vi:"Nghỉ + họp mỗi ca",en:"Breaks + meeting per shift"},value:"60 phút"},{label:{vi:"Nhu cầu khách hàng",en:"Customer demand"},value:"1150 SP/ngày"},{label:{vi:"Đi lại tại ST-05",en:"Walking at ST-05"},value:"18 m x 12 lần/giờ"}]},crisis:{vi:"Giám đốc xưởng chỉ đạo: “Lấy lần bấm giờ nhanh nhất của công nhân giỏi nhất làm thời gian chuẩn, bỏ hệ số nghỉ ngơi đi, cắt 3 người khỏi chuyền từ tuần sau và báo tiết kiệm cả năm luôn.”",en:"The workshop director orders: “Use the fastest stopwatch reading of our best operator as the standard time, drop the rest allowance, remove 3 people from the line next week and report the full-year saving now.”"},options:{safe:{vi:"Từ chối lập thời gian chuẩn sai phương pháp, báo Giám đốc Vận hành và ban chỉ đạo Lean, đề xuất bấm giờ có đánh giá nhịp độ, đủ hệ số nghỉ, chạy thử có kiểm soát và bố trí lại người thay vì cắt ngay.",en:"Refuse an improperly set standard time, inform the Operations Director and Lean steering team, and propose rated time studies with full allowances, a controlled pilot and redeployment instead of immediate cuts."},shortcut:{vi:"Dùng lần bấm giờ nhanh nhất, bỏ hệ số nghỉ và cắt 3 người như chỉ đạo.",en:"Use the fastest reading, drop the allowance and cut 3 people as ordered."},wait:{vi:"Không phản hồi, để giám đốc xưởng tự cập nhật thời gian chuẩn.",en:"Do not respond and let the director update the standard time himself."}},questions:{vi:["Vì sao việc công nhân đi lấy bulông tại ST-05 là MOTION chứ không phải TRANSPORT? Quan sát hiện trường nào chứng minh?","Trình bày cách tính takt time, so sánh với chu kỳ ST-05 và rủi ro an toàn, công bằng nếu đặt thời gian chuẩn không có hệ số nghỉ."],en:["Why is the operator fetching bolts at ST-05 MOTION and not TRANSPORT? Which gemba observation proves it?","Explain how you calculated takt time, compare it with the ST-05 cycle and describe the safety and fairness risks of a standard time without allowances."]},hints:{vi:["Chạy gemba st-05 để xem ai hoặc cái gì đang di chuyển trong thao tác.","Dùng cat shift.txt và cat demand.txt, trừ đủ nghỉ và họp trước khi chia theo SOP mục 3.2.","Đọc lại SOP mục 4.2: thời gian chuẩn phải đúng phương pháp; mọi áp lực cắt người vội vàng phải được báo cáo."],en:["Run gemba st-05 to see who or what is moving during the task.","Use cat shift.txt and cat demand.txt and remove all breaks and meetings before dividing per SOP 3.2.","Re-read SOP 4.2: standard time must follow method; any pressure for hasty headcount cuts must be escalated."]},terminal:{system:"line-ctl",settable:["WASTE_TYPE","TAKT_SEC"],commands:[{cmd:"status",out:{vi:"LINE-03: 9 trạm; sản lượng hôm qua 1088/1150; ST-05 thường xuyên chậm nhịp, tồn chờ trước ST-06",en:"LINE-03: 9 stations; output yesterday 1088/1150; ST-05 often behind pace, queue before ST-06"}},{cmd:"cat shift.txt",out:{vi:"2 ca x 480 phút; mỗi ca: nghỉ ăn 30 phút, 2 lần giải lao 10 phút, họp đầu ca 10 phút",en:"2 shifts x 480 minutes; each shift: 30-minute meal, two 10-minute breaks, 10-minute start-up meeting"}},{cmd:"cat demand.txt",out:{vi:"Nhu cầu khách hàng bình quân 1150 sản phẩm mỗi ngày, 6 ngày mỗi tuần",en:"Average customer demand 1150 units per day, 6 days per week"}},{cmd:"gemba st-05",out:{vi:"Công nhân rời trạm, đi bộ 18 m ra kệ lấy bulông 12 lần mỗi giờ rồi quay lại; vật tư không được chuyển giữa công đoạn, chỉ người di chuyển",en:"The operator leaves the station, walks 18 m to the bolt rack 12 times per hour and returns; no material moves between processes, only the person moves"}},{cmd:"cat timestudy.txt",out:{vi:"Chu kỳ quan sát: ST-03 41 s; ST-04 42 s; ST-05 49 s (gồm 7 s đi lại); các trạm khác dưới 40 s",en:"Observed cycles: ST-03 41 s; ST-04 42 s; ST-05 49 s (including 7 s walking); other stations under 40 s"}}]}},learning:{summary:{vi:"Kỹ sư Cải tiến Quy trình & Sản xuất Tinh gọn phân tích dòng giá trị, đo lường thời gian, loại bỏ lãng phí và giảm biến động để nhà máy làm ra nhiều giá trị hơn với cùng nguồn lực. Nghề kết hợp kỹ thuật công nghiệp (bấm giờ, cân bằng chuyền, bố trí mặt bằng), công cụ Lean và phương pháp Six Sigma DMAIC, đòi hỏi số liệu chính xác, hiện diện tại hiện trường và tôn trọng con người.",en:"A Lean Six Sigma / Industrial Engineer analyzes value streams, measures work, removes waste and reduces variation so the plant creates more value with the same resources. The role combines industrial engineering (time study, line balancing, layout), Lean tools and the Six Sigma DMAIC method, and requires accurate data, presence on the shop floor and respect for people."},responsibilities:{vi:["Vẽ bản đồ chuỗi giá trị hiện tại, tương lai và xác định cơ hội cải tiến.","Bấm giờ, xây dựng thời gian chuẩn, tính takt time và cân bằng chuyền.","Dẫn dắt dự án DMAIC, sự kiện kaizen và theo dõi lợi ích tài chính đã xác nhận.","Thiết kế bố trí mặt bằng, dòng vật tư, chuẩn hóa công việc và 5S.","Đào tạo công cụ Lean cho tổ trưởng, công nhân và duy trì hệ thống cải tiến liên tục."],en:["Map current and future value streams and identify improvement opportunities.","Run time studies, set standard times, compute takt time and balance lines.","Lead DMAIC projects and kaizen events and track validated financial benefits.","Design layouts, material flow, standardized work and 5S.","Train team leaders and operators on Lean tools and sustain continuous improvement."]},competencies:[{name:{vi:"Đo lường công việc",en:"Work measurement"},desc:{vi:"Bấm giờ, đánh giá nhịp độ, áp hệ số nghỉ để lập thời gian chuẩn công bằng và đúng phương pháp.",en:"Run time studies, apply performance rating and allowances to set fair, methodical standard times."}},{name:{vi:"Công cụ Lean",en:"Lean tools"},desc:{vi:"Dùng VSM, 5S, kanban, SMED, poka-yoke, cân bằng chuyền để loại bỏ lãng phí.",en:"Use VSM, 5S, kanban, SMED, poka-yoke and line balancing to remove waste."}},{name:{vi:"Thống kê Six Sigma",en:"Six Sigma statistics"},desc:{vi:"Phân tích năng lực, kiểm định giả thuyết, thiết kế thí nghiệm để tìm và kiểm soát nguyên nhân gốc.",en:"Use capability analysis, hypothesis tests and designed experiments to find and control root causes."}},{name:{vi:"Quản lý dự án cải tiến",en:"Improvement project management"},desc:{vi:"Lập charter, đo baseline, theo dõi lợi ích và bàn giao kế hoạch kiểm soát bền vững.",en:"Write charters, measure baselines, track benefits and hand over a sustainable control plan."}},{name:{vi:"Tôn trọng con người",en:"Respect for people"},desc:{vi:"Cải tiến cùng người lao động, bảo đảm an toàn, công thái học và không dùng cải tiến để ép nhịp vô lý.",en:"Improve with workers, protect safety and ergonomics, and never use improvement to force unreasonable pace."}}],knowledge:{vi:["Hệ thống sản xuất Toyota (TPS): 7 lãng phí TIMWOOD, Just-in-Time, Jidoka, chuẩn hóa công việc.","Phương pháp DMAIC và chuẩn ISO 13053 về phương pháp định lượng trong cải tiến quá trình (Six Sigma).","Takt time, thời gian chu kỳ, cân bằng chuyền, biểu đồ Yamazumi và hiệu suất cân bằng.","Đo lường công việc: bấm giờ, đánh giá nhịp độ, thời gian chuẩn = thời gian thường x (1 + hệ số nghỉ).","OEE = mức sẵn sàng x hiệu suất x chất lượng và 6 tổn thất lớn.","Nguyên tắc công thái học và an toàn lao động khi thiết kế trạm làm việc."],en:["Toyota Production System (TPS): the 7 TIMWOOD wastes, Just-in-Time, Jidoka and standardized work.","The DMAIC method and ISO 13053 on quantitative methods in process improvement (Six Sigma).","Takt time, cycle time, line balancing, Yamazumi charts and balance efficiency.","Work measurement: time study, performance rating, standard time = normal time x (1 + allowance).","OEE = availability x performance x quality and the six big losses.","Ergonomics and occupational safety principles in workstation design."]},tools:["Đồng hồ bấm giờ & phần mềm phân tích video","Mẫu VSM và bảng Yamazumi","Phần mềm thống kê (Minitab hoặc tương đương)","Phần mềm mô phỏng, bố trí mặt bằng","Bảng quản lý trực quan & bảng theo dõi kaizen"],kpis:{vi:["Năng suất lao động (sản phẩm/giờ công) so với baseline.","Tỷ lệ OEE của chuyền, máy then chốt.","Lợi ích tài chính đã được bộ phận tài chính xác nhận.","Tỷ lệ cải tiến được duy trì sau 6 tháng."],en:["Labor productivity (units per labor hour) versus baseline.","OEE of lines and key machines.","Financial benefits validated by finance.","Share of improvements sustained after 6 months."]},day:[{time:"07:30",vi:"Đi gemba đầu ca, quan sát chuyền LINE-03 và ghi nhận điểm tắc.",en:"Walk the gemba at shift start, observe LINE-03 and log blockages."},{time:"09:00",vi:"Bấm giờ trạm ST-05 qua nhiều chu kỳ, đánh giá nhịp độ và ghi phần việc không tạo giá trị.",en:"Time station ST-05 over many cycles, rate performance and note non-value-added work."},{time:"11:00",vi:"Tính takt, vẽ Yamazumi và đề xuất phương án cân bằng lại chuyền.",en:"Compute takt, draw the Yamazumi chart and propose a rebalancing option."},{time:"14:00",vi:"Dẫn sự kiện kaizen cùng tổ trưởng, đưa kệ bulông về điểm dùng tại trạm.",en:"Lead a kaizen event with team leaders to bring the bolt rack to the point of use."},{time:"16:30",vi:"Cập nhật bảng theo dõi dự án và lợi ích, chuẩn bị báo cáo tuần.",en:"Update the project and benefits tracker and prepare the weekly report."}],mistakes:{vi:["Tính takt trên thời gian ca gộp mà không trừ nghỉ và họp có kế hoạch.","Nhầm thao tác thừa của người (motion) với vận chuyển vật tư (transport), dẫn tới chọn sai giải pháp.","Lập thời gian chuẩn từ lần nhanh nhất, bỏ hệ số nghỉ và báo lợi ích chưa được xác nhận."],en:["Computing takt on gross shift time without removing planned breaks and meetings.","Confusing people motion with material transport, leading to the wrong countermeasure.","Setting standard time from the fastest reading, dropping allowances and reporting unvalidated benefits."]},career:[{vi:"Kỹ thuật viên kỹ thuật công nghiệp (IE)",en:"Industrial engineering technician"},{vi:"Kỹ sư IE, Lean (Green Belt)",en:"IE / Lean engineer (Green Belt)"},{vi:"Trưởng nhóm cải tiến liên tục (Black Belt)",en:"Continuous improvement lead (Black Belt)"},{vi:"Giám đốc Sản xuất tinh gọn & Xuất sắc vận hành",en:"Head of Lean & operational excellence"}],glossary:[{term:"Takt time",vi:"Nhịp sản xuất theo nhu cầu: thời gian sẵn có chia nhu cầu khách hàng trong cùng kỳ.",en:"The demand-driven pace: available time divided by customer demand in the same period."},{term:"TIMWOOD",vi:"Bảy lãng phí: vận chuyển, tồn kho, thao tác thừa, chờ đợi, sản xuất thừa, gia công thừa, khuyết tật.",en:"Seven wastes: transport, inventory, motion, waiting, overproduction, over-processing, defects."},{term:"VSM",vi:"Bản đồ chuỗi giá trị thể hiện dòng vật tư, thông tin và thời gian từ nhà cung cấp tới khách hàng.",en:"Value stream map showing material flow, information flow and time from supplier to customer."},{term:"Yamazumi",vi:"Biểu đồ cột chồng thời gian công việc từng trạm so với takt để cân bằng chuyền.",en:"A stacked bar chart of work content per station against takt, used to balance lines."},{term:"DMAIC",vi:"Chu trình Six Sigma: Xác định, Đo lường, Phân tích, Cải tiến, Kiểm soát.",en:"The Six Sigma cycle: Define, Measure, Analyze, Improve, Control."}],quiz:[{q:{vi:"Thời gian sẵn có 27000 giây mỗi ngày, nhu cầu 600 sản phẩm mỗi ngày. Takt time là bao nhiêu?",en:"Available time is 27000 seconds per day and demand is 600 units per day. What is takt time?"},options:{vi:["40 giây","45 giây","50 giây","60 giây"],en:["40 seconds","45 seconds","50 seconds","60 seconds"]},answer:1,explain:{vi:"Takt = 27000 / 600 = 45 giây mỗi sản phẩm.",en:"Takt = 27000 / 600 = 45 seconds per unit."}},{q:{vi:"Xe nâng chở bán thành phẩm qua lại giữa hai xưởng là loại lãng phí nào?",en:"A forklift shuttling semi-finished goods between two workshops is which waste?"},options:{vi:["Thao tác thừa (Motion)","Chờ đợi (Waiting)","Vận chuyển (Transport)","Gia công thừa (Over-processing)"],en:["Motion","Waiting","Transport","Over-processing"]},answer:2,explain:{vi:"Di chuyển vật tư giữa các công đoạn là vận chuyển; người di chuyển khi thao tác mới là thao tác thừa.",en:"Moving materials between processes is transport; people moving while working is motion."}},{q:{vi:"Mức sẵn sàng 90%, hiệu suất 95%, chất lượng 98%. OEE xấp xỉ bao nhiêu?",en:"Availability 90%, performance 95%, quality 98%. What is the OEE approximately?"},options:{vi:["83.8%","90.0%","95.0%","98.0%"],en:["83.8%","90.0%","95.0%","98.0%"]},answer:0,explain:{vi:"OEE = 0.90 x 0.95 x 0.98 = 0.8379, xấp xỉ 83.8%.",en:"OEE = 0.90 x 0.95 x 0.98 = 0.8379, about 83.8%."}},{q:{vi:"Cấp trên yêu cầu lấy lần nhanh nhất của người giỏi nhất làm thời gian chuẩn, bỏ hệ số nghỉ. Bạn làm gì?",en:"Your manager wants the best operator's fastest time as standard with no allowances. What do you do?"},options:{vi:["Làm theo để tăng năng suất","Chỉ bỏ một nửa hệ số nghỉ","Áp dụng thử cho công nhân mới","Từ chối, giải thích phương pháp đúng và báo cấp có thẩm quyền"],en:["Comply to raise productivity","Drop only half the allowance","Try it on new hires first","Refuse, explain the proper method and escalate"]},answer:3,explain:{vi:"Thời gian chuẩn phải dựa trên nhịp độ bình thường và đủ hệ số nghỉ; ép nhịp gây rủi ro an toàn và bất công.",en:"Standard time must reflect normal pace with allowances; forcing pace creates safety risk and unfairness."}}]}},"KK-539":{scenario:{company:"Thanh Phong Coatings",supervisor:{name:"Đỗ Thị Minh Châu",role:{vi:"Trưởng phòng An toàn - Sức khỏe - Môi trường",en:"Health, Safety & Environment Manager"}},ref_code:"IH-4417",title:{vi:"Đo đúng phơi nhiễm. Chọn đúng phin lọc. Không giấu số liệu.",en:"Measure true exposure. Pick the right filter. Hide no data."},brief:{vi:"Bạn rà soát hồ sơ đánh giá phơi nhiễm IH-4417 cho công nhân phòng pha sơn dùng dung môi gốc xylene. Mẫu cá nhân ca 8 giờ: 2 giờ ở 260 mg/m3, 4 giờ ở 110 mg/m3, 2 giờ ở 38 mg/m3 (giới hạn TWA mô phỏng 100 mg/m3). Đối chiếu bản nháp với hồ sơ đã duyệt, sửa loại phin lọc hô hấp và nồng độ trung bình theo thời gian 8 giờ, rồi lập báo cáo có căn cứ.",en:"You are reviewing exposure assessment IH-4417 for paint-mixing workers using a xylene-based solvent. The 8-hour personal samples are: 2 hours at 260 mg/m3, 4 hours at 110 mg/m3 and 2 hours at 38 mg/m3 (training TWA limit 100 mg/m3). Compare the draft with the approved file, correct the respirator filter type and the 8-hour time-weighted average, then write an evidence-based report."},reference_title:{vi:"Hồ sơ đánh giá phơi nhiễm hóa chất đã duyệt · IH-4417",en:"Approved chemical exposure assessment · IH-4417"},fields:[{id:"FILTER",label:{vi:"Loại phin lọc mặt nạ cấp phát",en:"Issued respirator filter type"},initial:"P2",expected:"A2",choices:["P2","A2","B2"],reference:"Ma trận chọn phương tiện bảo vệ hô hấp",hint:{vi:"Xylene là hơi hữu cơ điểm sôi khoảng 140°C; phin lọc bụi không giữ được hơi dung môi.",en:"Xylene is an organic vapour boiling near 140°C; a particle filter cannot capture solvent vapour."}},{id:"TWA_MG",label:{vi:"Nồng độ TWA 8 giờ (mg/m3)",en:"8-hour TWA concentration (mg/m3)"},initial:"136",expected:"129.5",reference:"Phiếu kết quả lấy mẫu cá nhân",ref_value:{vi:"Ca 8 giờ: 2 giờ 260 mg/m3; 4 giờ 110 mg/m3; 2 giờ 38 mg/m3",en:"8-hour shift: 2 h at 260 mg/m3; 4 h at 110 mg/m3; 2 h at 38 mg/m3"},hint:{vi:"Không lấy trung bình cộng các mẫu; phải nhân từng nồng độ với thời gian phơi nhiễm.",en:"Do not average the samples; weight each concentration by its exposure time."}}],sop32:{vi:"TWA 8 giờ = tổng (nồng độ từng giai đoạn x số giờ phơi nhiễm) chia cho 8 giờ; so sánh với giới hạn TWA mô phỏng 100 mg/m3 để quyết định biện pháp kiểm soát.",en:"8-hour TWA = sum of (concentration of each period x exposure hours) divided by 8 hours; compare with the training TWA limit of 100 mg/m3 to decide control measures."},context:{label:"HỒ SƠ PHƠI NHIỄM / IH-4417",metrics:[{label:{vi:"Khu vực",en:"Area"},value:"Paint mixing room"},{label:{vi:"Giới hạn TWA mô phỏng",en:"Training TWA limit"},value:"100 mg/m3"},{label:{vi:"Vận tốc hút chụp hút",en:"Hood capture velocity"},value:"0.3 / 0.5 m/s"}]},terminal:{system:"ehs-monitor",settable:["FILTER","TWA_MG"],commands:[{cmd:"status",out:{vi:"Phòng pha sơn: 6 công nhân/ca, quạt hút cục bộ chạy 72% công suất, bản nháp IH-4417 đang ghi FILTER=P2, TWA_MG=136",en:"Paint mixing room: 6 workers per shift, local exhaust fan at 72% capacity, draft IH-4417 shows FILTER=P2, TWA_MG=136"}},{cmd:"cat sds_section8.txt",out:{vi:"SDS mục 8: hơi hữu cơ, điểm sôi 138-144°C; khi vượt giới hạn dùng mặt nạ phin lọc khí hữu cơ loại A; quy trình chỉ phát sinh hơi, không có sương sơn",en:"SDS section 8: organic vapour, boiling point 138-144°C; above the limit use organic gas filter type A; the process emits vapour only, no paint mist"}},{cmd:"cat sampling_log.txt",out:{vi:"Mẫu cá nhân NV-03: 07:00-09:00 260 mg/m3; 09:00-13:00 110 mg/m3; 13:00-15:00 38 mg/m3; tổng 8 giờ",en:"Personal sample NV-03: 07:00-09:00 260 mg/m3; 09:00-13:00 110 mg/m3; 13:00-15:00 38 mg/m3; total 8 hours"}},{cmd:"lev-check mixroom",out:{vi:"Chụp hút bồn pha: vận tốc đo 0.3 m/s, thiết kế 0.5 m/s; màng lọc ống gió bị bít 60%",en:"Mixing tank hood: measured 0.3 m/s, design 0.5 m/s; duct filter 60% clogged"}},{cmd:"cat ppe_issue.txt",out:{vi:"Phiếu cấp phát tuần này: 12 khẩu trang lọc bụi P2, chưa cấp phin lọc khí hữu cơ",en:"This week's issue slip: 12 P2 particle masks, no organic gas filters issued"}}]},crisis:{vi:"Giám đốc sản xuất nhắn: “Đừng đưa số 129.5 vào báo cáo, tuần sau khách hàng đến đánh giá. Lấy mẫu lúc quạt chạy tốt mà ghi, công nhân cứ đeo khẩu trang cũ là được.”",en:"The production director messages: “Keep 129.5 out of the report, the customer audit is next week. Use a sample from when the fan ran well, workers can keep the old masks.”"},options:{safe:{vi:"Ghi đúng TWA 129.5 mg/m3, cấp ngay phin A2, sửa chụp hút, giới hạn thời gian phơi nhiễm, báo trưởng phòng HSE và lấy mẫu lại sau khi khắc phục.",en:"Report the true TWA of 129.5 mg/m3, issue A2 filters now, repair the hood, limit exposure time, inform the HSE manager and resample after the fix."},shortcut:{vi:"Chọn mẫu đo lúc quạt chạy tốt để báo cáo đạt, sau đợt đánh giá mới xử lý.",en:"Report only the sample taken when the fan ran well to pass, and fix things after the audit."},wait:{vi:"Để nguyên bản nháp và chờ giám đốc sản xuất tự quyết định có báo cáo hay không.",en:"Leave the draft as is and wait for the production director to decide whether to report."}},questions:{vi:["Vì sao TWA đúng là 129.5 mg/m3 chứ không phải 136? Mức này dẫn tới biện pháp kiểm soát nào?","Theo thứ bậc kiểm soát, bạn ưu tiên biện pháp gì trước khi dựa vào phin lọc A2, và xử lý áp lực sửa số liệu ra sao?"],en:["Why is the correct TWA 129.5 mg/m3 rather than 136? Which control measures does this level trigger?","Under the hierarchy of controls, what do you prioritise before relying on A2 filters, and how do you handle the pressure to alter data?"]},hints:{vi:["Đặt bản nháp cạnh ma trận chọn phương tiện bảo vệ hô hấp và đọc lại SDS mục 8.","Áp dụng SOP mục 3.2: nhân nồng độ với thời gian của từng giai đoạn rồi chia cho 8 giờ.","Đọc lại SOP mục 4.2: số liệu quan trắc không được chọn lọc hay sửa để vượt qua đánh giá."],en:["Place the draft next to the respiratory protection matrix and re-read SDS section 8.","Apply SOP 3.2: multiply each concentration by its duration, then divide by 8 hours.","Re-read SOP 4.2: monitoring data must never be cherry-picked or altered to pass an audit."]}},learning:{summary:{vi:"Kỹ sư An toàn, Sức khỏe và Môi trường (HSE) nhà máy nhận diện mối nguy, đánh giá rủi ro, quan trắc môi trường lao động và thiết lập biện pháp kiểm soát để không ai bị thương hay mắc bệnh nghề nghiệp, đồng thời giữ nhà máy tuân thủ pháp luật môi trường. Công việc đòi hỏi hiểu quy trình công nghệ, đọc được số liệu đo, áp dụng thứ bậc kiểm soát và đủ bản lĩnh để dừng việc khi không an toàn.",en:"A plant Health, Safety and Environment (HSE) engineer identifies hazards, assesses risks, monitors the working environment and sets controls so nobody is injured or develops an occupational disease, while keeping the plant compliant with environmental law. The role requires understanding the process, reading measurement data, applying the hierarchy of controls and having the courage to stop work when it is unsafe."},responsibilities:{vi:["Nhận diện mối nguy, đánh giá rủi ro (HIRA) cho công việc thường xuyên và không thường xuyên.","Tổ chức quan trắc môi trường lao động, đánh giá phơi nhiễm hóa chất, tiếng ồn, nhiệt.","Vận hành hệ thống giấy phép làm việc: công việc nóng, không gian hạn chế, làm việc trên cao, LOTO.","Điều tra sự cố, tìm nguyên nhân gốc và theo dõi hành động khắc phục, phòng ngừa.","Quản lý tuân thủ môi trường: chất thải nguy hại, nước thải, khí thải và báo cáo định kỳ."],en:["Identify hazards and assess risks (HIRA) for routine and non-routine work.","Organise workplace monitoring and assess exposure to chemicals, noise and heat.","Run the permit-to-work system: hot work, confined space, work at height and LOTO.","Investigate incidents, find root causes and track corrective and preventive actions.","Manage environmental compliance: hazardous waste, wastewater, air emissions and periodic reports."]},competencies:[{name:{vi:"Đánh giá rủi ro",en:"Risk assessment"},desc:{vi:"Xác định mối nguy, ước lượng khả năng và hậu quả, chọn biện pháp theo thứ bậc kiểm soát.",en:"Identify hazards, estimate likelihood and severity, and choose controls by the hierarchy of controls."}},{name:{vi:"Vệ sinh công nghiệp",en:"Industrial hygiene"},desc:{vi:"Lập kế hoạch lấy mẫu, tính TWA, STEL và đánh giá hiệu quả thông gió cục bộ.",en:"Plan sampling, calculate TWA and STEL, and evaluate local exhaust ventilation performance."}},{name:{vi:"Điều tra sự cố",en:"Incident investigation"},desc:{vi:"Dùng 5 Why, sơ đồ xương cá, cây sự cố để tìm nguyên nhân gốc, không đổ lỗi cá nhân.",en:"Use 5 Whys, fishbone and fault tree to find root causes without blaming individuals."}},{name:{vi:"Tuân thủ pháp luật",en:"Legal compliance"},desc:{vi:"Cập nhật quy định an toàn lao động, môi trường và duy trì hồ sơ sẵn sàng thanh tra.",en:"Track safety and environmental regulations and keep records ready for inspection."}},{name:{vi:"Bản lĩnh và văn hóa an toàn",en:"Safety leadership"},desc:{vi:"Dám dừng công việc nguy hiểm, báo cáo trung thực và huấn luyện người lao động.",en:"Stop dangerous work, report honestly and coach workers on safe behaviour."}}],knowledge:{vi:["Luật An toàn, vệ sinh lao động số 84/2015/QH13 và các văn bản hướng dẫn.","Nghị định 44/2016/NĐ-CP về kiểm định kỹ thuật an toàn, huấn luyện an toàn và quan trắc môi trường lao động.","Luật Bảo vệ môi trường số 72/2020/QH14 và quy định về quản lý chất thải nguy hại.","ISO 45001:2018 hệ thống quản lý an toàn, sức khỏe nghề nghiệp; ISO 14001:2015 hệ thống quản lý môi trường.","Thứ bậc kiểm soát: loại bỏ, thay thế, kỹ thuật, hành chính, phương tiện bảo vệ cá nhân.","Phân loại phin lọc hô hấp: phin bụi P1-P3, phin khí A, B, E, K theo nhóm chất."],en:["Law on Occupational Safety and Health No. 84/2015/QH13 and its implementing documents.","Decree 44/2016/ND-CP on safety inspection, safety training and workplace environment monitoring.","Law on Environmental Protection No. 72/2020/QH14 and hazardous waste management rules.","ISO 45001:2018 occupational health and safety management; ISO 14001:2015 environmental management.","Hierarchy of controls: elimination, substitution, engineering, administrative, personal protective equipment.","Respirator filter classes: particle P1-P3, gas filters A, B, E, K by substance group."]},tools:["Máy lấy mẫu khí cá nhân","Máy đo khí đa chỉ tiêu","Máy đo tiếng ồn tích phân","Đồng hồ đo vận tốc gió","Phần mềm quản lý sự cố HSE"],kpis:{vi:["Tần suất tai nạn mất ngày công (LTIFR) trên một triệu giờ làm việc.","Tỷ lệ hành động khắc phục sau sự cố đóng đúng hạn.","Tỷ lệ vị trí quan trắc đạt giới hạn cho phép.","Số báo cáo cận nguy (near miss) được ghi nhận mỗi tháng."],en:["Lost time injury frequency rate (LTIFR) per million hours worked.","Share of incident corrective actions closed on time.","Share of monitored positions within permissible limits.","Number of near-miss reports logged per month."]},day:[{time:"07:30",vi:"Họp an toàn đầu ca, nhắc mối nguy của công việc đặc biệt trong ngày.",en:"Run the pre-shift safety talk and flag hazards of today's special jobs."},{time:"09:00",vi:"Kiểm tra hiện trường, phê duyệt giấy phép công việc nóng và không gian hạn chế.",en:"Walk the floor and approve hot work and confined space permits."},{time:"11:00",vi:"Lấy mẫu không khí vùng thở công nhân và đo vận tốc chụp hút.",en:"Take breathing-zone air samples and measure hood capture velocity."},{time:"14:00",vi:"Điều tra một vụ cận nguy, phỏng vấn nhân chứng và vẽ sơ đồ nguyên nhân.",en:"Investigate a near miss, interview witnesses and map the causes."},{time:"16:30",vi:"Cập nhật sổ theo dõi hành động khắc phục và báo cáo chất thải nguy hại.",en:"Update the corrective action log and the hazardous waste report."}],mistakes:{vi:["Lấy trung bình cộng các mẫu thay vì trung bình theo thời gian phơi nhiễm.","Cấp khẩu trang lọc bụi cho môi trường hơi dung môi, tạo cảm giác an toàn giả.","Chỉ dựa vào phương tiện bảo vệ cá nhân mà bỏ qua sửa chữa thông gió và thay thế hóa chất."],en:["Taking the arithmetic mean of samples instead of the time-weighted average.","Issuing particle masks for solvent vapour, which creates false confidence.","Relying only on PPE while skipping ventilation repair and chemical substitution."]},career:[{vi:"Nhân viên an toàn hiện trường",en:"Field safety officer"},{vi:"Kỹ sư HSE nhà máy",en:"Plant HSE engineer"},{vi:"Trưởng phòng HSE",en:"HSE manager"},{vi:"Giám đốc HSE khu vực hoặc tập đoàn",en:"Regional or corporate HSE director"}],glossary:[{term:"TWA",vi:"Nồng độ trung bình theo thời gian của ca làm việc 8 giờ, dùng để so sánh với giới hạn phơi nhiễm.",en:"Time-weighted average concentration over an 8-hour shift, compared with the exposure limit."},{term:"STEL",vi:"Giới hạn phơi nhiễm ngắn hạn, thường tính trung bình trong 15 phút.",en:"Short-term exposure limit, usually averaged over 15 minutes."},{term:"LEV",vi:"Hệ thống thông gió hút cục bộ, thu hơi khí độc ngay tại nguồn phát sinh.",en:"Local exhaust ventilation that captures contaminants at the source."},{term:"LOTO",vi:"Khóa và gắn thẻ cô lập năng lượng trước khi sửa chữa, bảo trì thiết bị.",en:"Lockout and tagout to isolate energy before repair or maintenance."},{term:"HIRA",vi:"Nhận diện mối nguy và đánh giá rủi ro, nền tảng để chọn biện pháp kiểm soát.",en:"Hazard identification and risk assessment, the basis for choosing controls."}],quiz:[{q:{vi:"Mẫu ca 8 giờ: 4 giờ ở 150 mg/m3 và 4 giờ ở 50 mg/m3. TWA 8 giờ bằng bao nhiêu?",en:"An 8-hour shift has 4 h at 150 mg/m3 and 4 h at 50 mg/m3. What is the 8-hour TWA?"},options:{vi:["200 mg/m3","75 mg/m3","150 mg/m3","100 mg/m3"],en:["200 mg/m3","75 mg/m3","150 mg/m3","100 mg/m3"]},answer:3,explain:{vi:"TWA = (4 x 150 + 4 x 50) / 8 = 800 / 8 = 100 mg/m3, đúng bằng giới hạn mô phỏng.",en:"TWA = (4 x 150 + 4 x 50) / 8 = 800 / 8 = 100 mg/m3, exactly at the training limit."}},{q:{vi:"Theo thứ bậc kiểm soát, biện pháp nào được ưu tiên cao nhất?",en:"Which control has the highest priority in the hierarchy of controls?"},options:{vi:["Loại bỏ mối nguy","Cấp phương tiện bảo vệ cá nhân","Huấn luyện người lao động","Dán biển cảnh báo"],en:["Eliminate the hazard","Issue personal protective equipment","Train workers","Post warning signs"]},answer:0,explain:{vi:"Loại bỏ mối nguy đứng đầu; phương tiện bảo vệ cá nhân là lớp cuối cùng.",en:"Elimination comes first; personal protective equipment is the last line of defence."}},{q:{vi:"Công nhân tiếp xúc hơi dung môi hữu cơ điểm sôi 140°C cần loại phin lọc nào?",en:"Which filter suits workers exposed to an organic solvent vapour boiling at 140°C?"},options:{vi:["Phin bụi P2","Phin khí hữu cơ loại A","Phin khí vô cơ loại B","Phin amoniac loại K"],en:["P2 particle filter","Type A organic gas filter","Type B inorganic gas filter","Type K ammonia filter"]},answer:1,explain:{vi:"Phin loại A dành cho khí, hơi hữu cơ có điểm sôi trên 65°C; phin bụi không giữ được hơi.",en:"Type A filters cover organic gases and vapours boiling above 65°C; particle filters do not stop vapour."}},{q:{vi:"Sếp yêu cầu bỏ kết quả đo vượt giới hạn khỏi báo cáo trước đợt đánh giá. Bạn làm gì?",en:"Your boss asks you to drop an over-limit result from the report before an audit. What do you do?"},options:{vi:["Làm theo vì đánh giá rất quan trọng","Đo lại đến khi có số đạt","Ghi đúng kết quả, triển khai kiểm soát và báo cáo cấp có thẩm quyền","Im lặng và không nộp báo cáo"],en:["Comply because the audit matters","Resample until a result passes","Report the true result, apply controls and escalate","Stay silent and submit nothing"]},answer:2,explain:{vi:"Che giấu số liệu phơi nhiễm đặt sức khỏe người lao động vào rủi ro và vi phạm pháp luật.",en:"Hiding exposure data puts workers' health at risk and breaks the law."}}]}},"KK-540":{scenario:{company:"Bắc Sơn Packaging Mill",supervisor:{name:"Trần Đức Khải",role:{vi:"Trưởng phòng Bảo trì & Độ tin cậy",en:"Maintenance & Reliability Manager"}},ref_code:"WO-5182",title:{vi:"Đọc đúng phổ rung. Tính đúng MTBF. Không gỡ khóa người khác.",en:"Read the spectrum right. Count MTBF right. Never cut another's lock."},brief:{vi:"Bơm nước tuần hoàn P-12 hỏng 5 lần trong 6 tháng (4380 giờ lịch, nhà máy chạy liên tục), tổng thời gian dừng sửa chữa 60 giờ. Lệnh công việc WO-5182 nháp ghi chế độ hỏng và MTBF chưa đúng. Đối chiếu với phổ rung và nhật ký hỏng hóc đã duyệt, sửa chế độ hỏng và MTBF, rồi lập báo cáo phân tích nguyên nhân gốc có căn cứ.",en:"Circulating water pump P-12 failed 5 times in 6 months (4380 calendar hours, plant runs non-stop), with 60 hours of total repair downtime. Draft work order WO-5182 shows the wrong failure mode and MTBF. Compare it with the approved vibration spectrum and failure log, correct the failure mode and MTBF, then write an evidence-based root cause report."},reference_title:{vi:"Hồ sơ chẩn đoán rung & nhật ký hỏng hóc đã duyệt · P-12",en:"Approved vibration diagnosis & failure log · P-12"},fields:[{id:"FAIL_MODE",label:{vi:"Chế độ hỏng chẩn đoán",en:"Diagnosed failure mode"},initial:"UNBALANCE",expected:"MISALIGNMENT",choices:["UNBALANCE","MISALIGNMENT","LOOSENESS"],reference:"Phiếu phân tích phổ rung",hint:{vi:"Mất cân bằng cho đỉnh 1X hướng kính; đỉnh 2X cao, rung dọc trục lớn và lệch pha 180 độ qua khớp nối là dấu hiệu khác.",en:"Unbalance gives a radial 1X peak; a high 2X, strong axial vibration and 180-degree phase shift across the coupling point elsewhere."}},{id:"MTBF_H",label:{vi:"MTBF của bơm P-12 (giờ)",en:"Pump P-12 MTBF (hours)"},initial:"876",expected:"864",reference:"Nhật ký hỏng hóc 6 tháng",ref_value:{vi:"Thời gian lịch 4380 giờ; 5 lần hỏng; tổng dừng sửa chữa 60 giờ",en:"Calendar time 4380 h; 5 failures; total repair downtime 60 h"},hint:{vi:"MTBF tính trên thời gian máy thực sự vận hành, không phải toàn bộ thời gian lịch.",en:"MTBF uses the time the machine actually ran, not the full calendar time."}}],sop32:{vi:"MTBF = (tổng thời gian lịch - tổng thời gian dừng do hỏng) / số lần hỏng; MTTR = tổng thời gian dừng do hỏng / số lần hỏng.",en:"MTBF = (total calendar time - total failure downtime) / number of failures; MTTR = total failure downtime / number of failures."},context:{label:"CMMS / WO-5182",metrics:[{label:{vi:"Số lần hỏng 6 tháng",en:"Failures in 6 months"},value:"5"},{label:{vi:"Tổng dừng sửa chữa",en:"Total repair downtime"},value:"60 h"},{label:{vi:"Rung dọc trục",en:"Axial vibration"},value:"7.2 mm/s RMS"}]},terminal:{system:"cmms-rcm",settable:["FAIL_MODE","MTBF_H"],commands:[{cmd:"status",out:{vi:"P-12: bơm ly tâm 75 kW, 1480 v/ph, khớp nối đàn hồi; WO-5182 nháp ghi FAIL_MODE=UNBALANCE, MTBF_H=876",en:"P-12: 75 kW centrifugal pump, 1480 rpm, flexible coupling; draft WO-5182 shows FAIL_MODE=UNBALANCE, MTBF_H=876"}},{cmd:"vib-spectrum p-12",out:{vi:"Ổ đỡ phía động cơ: 1X 3.9 mm/s, 2X 6.6 mm/s; dọc trục 7.2 mm/s lớn hơn hướng kính; pha dọc trục lệch 180 độ giữa hai bên khớp nối",en:"Motor-side bearing: 1X 3.9 mm/s, 2X 6.6 mm/s; axial 7.2 mm/s above radial; axial phase differs by 180 degrees across the coupling"}},{cmd:"cat failure_log.txt",out:{vi:"5 lần hỏng ổ bi và gioăng cơ khí; thời gian dừng: 14 h, 11 h, 12 h, 13 h, 10 h",en:"5 bearing and mechanical seal failures; downtime: 14 h, 11 h, 12 h, 13 h, 10 h"}},{cmd:"cat runtime.txt",out:{vi:"Kỳ phân tích 01/01-30/06: 4380 giờ lịch, vận hành liên tục 24/7, không có dừng kế hoạch",en:"Analysis window 01/01-30/06: 4380 calendar hours, 24/7 operation, no planned stops"}},{cmd:"cat wo_history.txt",out:{vi:"Thay động cơ cách đây 5 tháng; không có biên bản căn chỉnh đồng tâm bằng laser sau khi thay",en:"Motor replaced 5 months ago; no laser shaft alignment record after the replacement"}}]},crisis:{vi:"Trưởng ca sản xuất gọi: “Thợ Tâm về rồi mà ổ khóa LOTO của cậu ấy vẫn treo ở tủ điện P-12. Cắt khóa đi cho bơm chạy lại, căn chỉnh để mai tính.”",en:"The shift leader calls: “Tam has gone home but his LOTO lock is still on the P-12 panel. Cut it off so the pump can run, alignment can wait until tomorrow.”"},options:{safe:{vi:"Từ chối cắt khóa; liên hệ người treo khóa hoặc áp dụng thủ tục gỡ khóa có phê duyệt, báo trưởng phòng bảo trì và lên lịch căn chỉnh laser trước khi chạy lại.",en:"Refuse to cut the lock; contact the lock owner or use the authorised removal procedure, inform the maintenance manager and schedule laser alignment before restart."},shortcut:{vi:"Cắt khóa cho bơm chạy lại ngay, ghi chú để thợ căn chỉnh vào ca sau.",en:"Cut the lock to restart the pump now and leave a note for alignment next shift."},wait:{vi:"Không trả lời trưởng ca và để ca sau tự xử lý ổ khóa.",en:"Ignore the shift leader and let the next shift deal with the lock."}},questions:{vi:["Dữ liệu rung nào cho thấy P-12 bị lệch trục chứ không phải mất cân bằng? MTBF 864 giờ nói gì về chiến lược bảo trì?","Vì sao không được cắt khóa LOTO của người khác, và thủ tục gỡ khóa hợp lệ gồm những bước nào?"],en:["Which vibration data show P-12 is misaligned rather than unbalanced? What does an MTBF of 864 hours say about the maintenance strategy?","Why must you never cut another person's LOTO lock, and what does a valid lock removal procedure include?"]},hints:{vi:["So sánh tỷ lệ đỉnh 2X với 1X và biên độ dọc trục so với hướng kính trên phiếu phổ rung.","Áp dụng SOP mục 3.2: trừ thời gian dừng do hỏng khỏi thời gian lịch trước khi chia cho số lần hỏng.","Đọc lại SOP mục 4.2: chỉ người treo khóa được gỡ khóa, trừ khi có thủ tục phê duyệt đặc biệt."],en:["Compare the 2X to 1X ratio and axial to radial amplitude on the spectrum sheet.","Apply SOP 3.2: subtract failure downtime from calendar time before dividing by the number of failures.","Re-read SOP 4.2: only the lock owner removes a lock unless a special authorised procedure is used."]}},learning:{summary:{vi:"Kỹ sư Bảo trì Thiết bị và Độ tin cậy giữ cho máy móc sẵn sàng với chi phí vòng đời thấp nhất: lập kế hoạch bảo trì phòng ngừa, giám sát tình trạng bằng rung, nhiệt, dầu, phân tích nguyên nhân gốc các hỏng hóc lặp lại và cải tiến thiết kế. Công việc đòi hỏi hiểu cơ chế hỏng của thiết bị, làm việc bằng dữ liệu CMMS và tuân thủ tuyệt đối an toàn cô lập năng lượng.",en:"A Maintenance and Reliability Engineer keeps equipment available at the lowest life-cycle cost: planning preventive maintenance, monitoring condition through vibration, thermography and oil analysis, analysing root causes of repeat failures and driving design improvements. The role requires understanding failure mechanisms, working from CMMS data and strictly following energy isolation safety."},responsibilities:{vi:["Xây dựng và tối ưu kế hoạch bảo trì phòng ngừa, bảo trì dự đoán theo mức độ quan trọng của thiết bị.","Giám sát tình trạng bằng phân tích rung, nhiệt hồng ngoại, siêu âm và phân tích dầu.","Phân tích nguyên nhân gốc (RCA) các hỏng hóc lặp lại và theo dõi hành động khắc phục.","Theo dõi MTBF, MTTR, OEE và báo cáo xu hướng độ tin cậy cho ban quản lý.","Quản lý phụ tùng quan trọng, tiêu chuẩn lắp đặt, căn chỉnh và bôi trơn."],en:["Build and optimise preventive and predictive maintenance plans by equipment criticality.","Monitor condition with vibration analysis, infrared thermography, ultrasound and oil analysis.","Run root cause analysis (RCA) on repeat failures and track corrective actions.","Track MTBF, MTTR and OEE and report reliability trends to management.","Manage critical spares and installation, alignment and lubrication standards."]},competencies:[{name:{vi:"Chẩn đoán rung",en:"Vibration diagnostics"},desc:{vi:"Đọc phổ FFT, dạng sóng và pha để phân biệt mất cân bằng, lệch trục, lỏng cơ khí, hỏng ổ bi.",en:"Read FFT spectra, waveforms and phase to separate unbalance, misalignment, looseness and bearing faults."}},{name:{vi:"Phân tích độ tin cậy",en:"Reliability analysis"},desc:{vi:"Tính MTBF, MTTR, độ sẵn sàng và dùng phân bố Weibull để chọn chiến lược bảo trì.",en:"Calculate MTBF, MTTR and availability and use Weibull analysis to choose maintenance strategies."}},{name:{vi:"RCM và FMEA",en:"RCM and FMEA"},desc:{vi:"Phân tích chức năng, chế độ hỏng, hậu quả để chọn nhiệm vụ bảo trì phù hợp.",en:"Analyse functions, failure modes and effects to select the right maintenance tasks."}},{name:{vi:"Quản lý CMMS",en:"CMMS management"},desc:{vi:"Chuẩn hóa mã hỏng, dữ liệu lệnh công việc để số liệu độ tin cậy dùng được.",en:"Standardise failure codes and work order data so reliability metrics can be trusted."}},{name:{vi:"An toàn bảo trì",en:"Maintenance safety"},desc:{vi:"Áp dụng LOTO, giấy phép làm việc và kiểm tra năng lượng bằng không trước mọi can thiệp.",en:"Apply LOTO, permits to work and zero-energy verification before any intervention."}}],knowledge:{vi:["ISO 55000 về quản lý tài sản và tư duy chi phí vòng đời.","ISO 20816 về đo và đánh giá mức rung của máy.","SAE JA1011 tiêu chí đánh giá quy trình bảo trì tập trung vào độ tin cậy (RCM).","ISO 14224 về thu thập và trao đổi dữ liệu độ tin cậy, bảo trì thiết bị.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và quy trình khóa, gắn thẻ cô lập năng lượng."],en:["ISO 55000 on asset management and life-cycle cost thinking.","ISO 20816 on measuring and evaluating machine vibration.","SAE JA1011 evaluation criteria for reliability-centred maintenance (RCM) processes.","ISO 14224 on collecting and exchanging equipment reliability and maintenance data.","Law on Occupational Safety and Health No. 84/2015/QH13 and lockout-tagout procedures."]},tools:["Máy phân tích rung cầm tay","Camera nhiệt hồng ngoại","Thiết bị căn chỉnh trục bằng laser","Phần mềm CMMS","Phần mềm phân tích Weibull"],kpis:{vi:["MTBF của thiết bị quan trọng tăng theo quý.","Tỷ lệ bảo trì có kế hoạch trên tổng giờ bảo trì.","Tỷ lệ tuân thủ lịch bảo trì phòng ngừa.","Chi phí bảo trì trên giá trị thay thế tài sản."],en:["Quarterly growth of MTBF on critical assets.","Planned maintenance share of total maintenance hours.","Preventive maintenance schedule compliance.","Maintenance cost as a share of replacement asset value."]},day:[{time:"07:30",vi:"Xem báo cáo sự cố ca đêm và danh sách lệnh công việc khẩn trên CMMS.",en:"Review night-shift breakdowns and urgent work orders in the CMMS."},{time:"09:00",vi:"Đi tuyến đo rung các bơm, quạt, hộp số quan trọng và so sánh xu hướng.",en:"Walk the vibration route on critical pumps, fans and gearboxes and compare trends."},{time:"11:00",vi:"Chủ trì họp RCA về hỏng ổ bi lặp lại, giao hành động khắc phục.",en:"Lead an RCA meeting on repeat bearing failures and assign corrective actions."},{time:"14:00",vi:"Giám sát căn chỉnh laser sau khi thay động cơ, kiểm tra LOTO đúng quy trình.",en:"Supervise laser alignment after a motor change and check LOTO compliance."},{time:"16:30",vi:"Cập nhật MTBF, MTTR và đề xuất điều chỉnh tần suất bảo trì phòng ngừa.",en:"Update MTBF and MTTR and propose preventive maintenance frequency changes."}],mistakes:{vi:["Tính MTBF trên thời gian lịch mà không trừ thời gian dừng sửa chữa.","Chẩn đoán mọi đỉnh rung 1X là mất cân bằng mà bỏ qua 2X, rung dọc trục và pha.","Thay thế linh kiện hỏng lặp lại mà không tìm nguyên nhân gốc như lệch trục, bôi trơn sai."],en:["Calculating MTBF on calendar time without subtracting repair downtime.","Calling every 1X peak unbalance while ignoring 2X, axial vibration and phase.","Replacing repeat-failure parts without finding root causes such as misalignment or poor lubrication."]},career:[{vi:"Kỹ thuật viên bảo trì",en:"Maintenance technician"},{vi:"Kỹ sư bảo trì và độ tin cậy",en:"Maintenance and reliability engineer"},{vi:"Trưởng bộ phận độ tin cậy",en:"Reliability lead"},{vi:"Giám đốc bảo trì và quản lý tài sản",en:"Maintenance and asset management director"}],glossary:[{term:"MTBF",vi:"Thời gian trung bình giữa hai lần hỏng, tính trên thời gian vận hành thực tế.",en:"Mean time between failures, based on actual operating time."},{term:"MTTR",vi:"Thời gian trung bình để sửa chữa và đưa thiết bị trở lại vận hành.",en:"Mean time to repair and return equipment to service."},{term:"RCM",vi:"Bảo trì tập trung vào độ tin cậy, chọn nhiệm vụ bảo trì dựa trên chức năng và hậu quả hỏng.",en:"Reliability-centred maintenance that selects tasks from functions and failure consequences."},{term:"P-F interval",vi:"Khoảng thời gian từ khi phát hiện được dấu hiệu hỏng tiềm ẩn đến khi hỏng chức năng.",en:"Time from when a potential failure becomes detectable to functional failure."},{term:"OEE",vi:"Hiệu suất thiết bị tổng thể, tích của độ sẵn sàng, hiệu suất và chất lượng.",en:"Overall equipment effectiveness, the product of availability, performance and quality."}],quiz:[{q:{vi:"Thiết bị chạy 2000 giờ lịch, hỏng 4 lần, tổng dừng sửa chữa 40 giờ. MTBF bằng bao nhiêu?",en:"A machine ran 2000 calendar hours, failed 4 times with 40 hours of total repair downtime. What is the MTBF?"},options:{vi:["500 giờ","490 giờ","10 giờ","510 giờ"],en:["500 hours","490 hours","10 hours","510 hours"]},answer:1,explain:{vi:"MTBF = (2000 - 40) / 4 = 490 giờ; MTTR = 40 / 4 = 10 giờ.",en:"MTBF = (2000 - 40) / 4 = 490 hours; MTTR = 40 / 4 = 10 hours."}},{q:{vi:"Phổ rung có đỉnh 2X cao, rung dọc trục lớn và lệch pha 180 độ qua khớp nối gợi ý lỗi gì?",en:"A high 2X peak, strong axial vibration and 180-degree phase shift across the coupling suggest what fault?"},options:{vi:["Mất cân bằng","Hỏng vòng ngoài ổ bi","Lỏng chân đế","Lệch trục"],en:["Unbalance","Bearing outer race defect","Soft foot looseness","Misalignment"]},answer:3,explain:{vi:"Đây là dấu hiệu điển hình của lệch trục, nhất là lệch góc.",en:"This is the classic signature of misalignment, especially angular misalignment."}},{q:{vi:"Đồng nghiệp đã về nhưng ổ khóa LOTO vẫn treo, sản xuất muốn chạy máy. Bạn làm gì?",en:"A colleague left with his LOTO lock still on and production wants to run. What do you do?"},options:{vi:["Liên hệ người treo khóa hoặc làm thủ tục gỡ khóa có phê duyệt","Cắt khóa vì máy đã sửa xong","Nhờ bảo vệ mở khóa dự phòng","Đóng điện thử để kiểm tra"],en:["Contact the owner or use the authorised removal procedure","Cut the lock since the repair is done","Ask security to open it with a spare key","Energise briefly to test"]},answer:0,explain:{vi:"Ổ khóa bảo vệ tính mạng người treo; chỉ gỡ khi xác nhận người đó an toàn theo thủ tục.",en:"The lock protects its owner's life; remove it only after confirming the person is safe under the procedure."}},{q:{vi:"Chiến lược nào phù hợp khi hỏng hóc có dấu hiệu báo trước đo được và khoảng P-F đủ dài?",en:"Which strategy fits when a failure gives a measurable warning and a long enough P-F interval?"},options:{vi:["Chạy đến khi hỏng","Thay định kỳ theo lịch cố định","Bảo trì theo tình trạng","Thiết kế lại ngay lập tức"],en:["Run to failure","Fixed-interval replacement","Condition-based maintenance","Immediate redesign"]},answer:2,explain:{vi:"Khi phát hiện được hỏng tiềm ẩn sớm, giám sát tình trạng giúp can thiệp đúng lúc, ít tốn kém.",en:"When potential failure is detectable early, condition monitoring allows timely, low-cost intervention."}}]}},"KK-541":{scenario:{company:"Minh Khang Controls Assembly",supervisor:{name:"Quách Thị Hồng Nhung",role:{vi:"Trưởng phòng Kế hoạch Chuỗi cung ứng",en:"Supply Chain Planning Manager"}},ref_code:"MRP-2611",title:{vi:"Đúng phiên bản BOM. Đúng nhu cầu ròng. Đúng quy cách lô.",en:"Right BOM revision. Right net need. Right lot size."},brief:{vi:"Đơn hàng 2400 bộ điều khiển giao tuần 22. ECN-2207 hiệu lực từ tuần 20 nâng định mức đầu nối CN-88 lên 3 cái/bộ. Hao hụt 2%, tồn kho 1250 (đã phân bổ 300 cho đơn khác), hàng đang về 2000, tồn an toàn 500, đặt theo bội số khay 240. Đối chiếu bản kế hoạch nháp MRP-2611, sửa phiên bản BOM và lượng đặt hàng, rồi lập báo cáo có căn cứ.",en:"An order for 2400 controllers ships in week 22. ECN-2207, effective from week 20, raises connector CN-88 usage to 3 per unit. Scrap 2%, on hand 1250 (300 allocated to other orders), 2000 on order, safety stock 500, order in tray multiples of 240. Check draft plan MRP-2611, correct the BOM revision and the order quantity, then write an evidence-based report."},reference_title:{vi:"Bảng tính nhu cầu vật tư đã duyệt · MRP-2611",en:"Approved material requirements worksheet · MRP-2611"},fields:[{id:"BOM_REV",label:{vi:"Phiên bản BOM áp dụng",en:"Applied BOM revision"},initial:"REV-B",expected:"REV-C",choices:["REV-A","REV-B","REV-C"],reference:"Thông báo thay đổi kỹ thuật ECN-2207",hint:{vi:"Chọn phiên bản BOM theo ngày hiệu lực của ECN so với tuần cần vật tư, không theo bản đang mở sẵn.",en:"Pick the BOM revision by the ECN effectivity date versus the need week, not the one already open."}},{id:"PLAN_QTY",label:{vi:"Lượng đặt hàng CN-88 (cái)",en:"CN-88 planned order quantity (pcs)"},initial:"2160",expected:"5040",reference:"Bảng tồn kho và tham số kế hoạch",ref_value:{vi:"Tồn 1250, phân bổ 300; đang về 2000; tồn an toàn 500; hao hụt 2%; bội số khay 240",en:"On hand 1250, allocated 300; on order 2000; safety stock 500; scrap 2%; tray multiple 240"},hint:{vi:"Tồn kho đã phân bổ cho đơn khác không còn khả dụng; nhớ làm tròn lên theo bội số khay.",en:"Stock allocated to other orders is not available; remember to round up to the tray multiple."}}],sop32:{vi:"Nhu cầu gộp = SL thành phẩm x định mức x (1 + hao hụt); nhu cầu ròng = gộp - (tồn - đã phân bổ) - hàng đang về + tồn an toàn; lượng đặt = làm tròn lên bội số khay 240.",en:"Gross need = finished units x usage x (1 + scrap); net need = gross - (on hand - allocated) - on order + safety stock; order quantity = round up to the 240 tray multiple."},context:{label:"ERP-MRP / MRP-2611",metrics:[{label:{vi:"Đơn thành phẩm",en:"Finished goods order"},value:"2,400 units"},{label:{vi:"Tồn kho / đã phân bổ",en:"On hand / allocated"},value:"1,250 / 300"},{label:{vi:"Đang về / tồn an toàn",en:"On order / safety stock"},value:"2,000 / 500"},{label:{vi:"Quy cách khay",en:"Tray multiple"},value:"240 pcs"}]},crisis:{vi:"Đại diện nhà cung cấp nhắn riêng: “Anh đặt tròn 8000 cái thay vì số MRP tính nhé, bên em sẽ gửi anh một khoản hoa hồng riêng, không ai biết đâu.”",en:"The supplier's representative messages privately: “Order a round 8000 instead of the MRP figure, we will send you a private commission, nobody will know.”"},options:{safe:{vi:"Từ chối hoa hồng, đặt đúng 5040 theo MRP với BOM REV-C, báo trưởng phòng và bộ phận tuân thủ theo quy định về quà tặng, xung đột lợi ích.",en:"Refuse the commission, order exactly 5040 per MRP with BOM REV-C, and report to the manager and compliance under the gifts and conflict of interest policy."},shortcut:{vi:"Đặt 8000 cho dư an toàn, khoản hoa hồng coi như chuyện riêng.",en:"Order 8000 as extra buffer and treat the commission as a private matter."},wait:{vi:"Không phản hồi, giữ nguyên bản nháp 2160 và chờ mua hàng tự đặt.",en:"Do not reply, keep the 2160 draft and let purchasing order on its own."}},questions:{vi:["Vì sao phải dùng BOM REV-C và lượng đặt đúng là 5040? Trình bày từng bước từ nhu cầu gộp đến làm tròn lô.","Đặt dư theo gợi ý nhà cung cấp gây rủi ro gì về tồn kho, dòng tiền và tuân thủ? Bạn xử lý lời mời hoa hồng thế nào?"],en:["Why must you use BOM REV-C and why is the correct order 5040? Walk through each step from gross need to lot rounding.","What inventory, cash and compliance risks come from over-ordering as the supplier suggests? How do you handle the commission offer?"]},hints:{vi:["So ngày hiệu lực ECN-2207 với tuần cần vật tư để chọn đúng phiên bản BOM.","Áp dụng SOP mục 3.2: trừ phần tồn đã phân bổ trước khi tính nhu cầu ròng, sau đó làm tròn lên.","Đọc lại SOP mục 4.2: mọi lợi ích cá nhân từ nhà cung cấp phải từ chối và báo cáo."],en:["Compare the ECN-2207 effectivity date with the need week to choose the BOM revision.","Apply SOP 3.2: subtract allocated stock before computing net need, then round up.","Re-read SOP 4.2: any personal benefit from a supplier must be refused and reported."]}},learning:{summary:{vi:"Kỹ sư Hoạch định Vật tư Sản xuất (MRP) biến kế hoạch sản xuất tổng thể thành nhu cầu chi tiết cho từng linh kiện: đủ số lượng, đúng thời điểm, không tồn kho thừa. Công việc dựa trên dữ liệu BOM, tồn kho, thời gian chờ và tham số lô chính xác, phối hợp chặt với sản xuất, mua hàng, kỹ thuật và kho để giữ dây chuyền chạy liên tục với vốn lưu động thấp nhất.",en:"A Material Requirements Planning (MRP) Engineer turns the master production schedule into detailed requirements for every component: the right quantity at the right time without excess stock. The job relies on accurate BOM, inventory, lead time and lot-size data and close coordination with production, purchasing, engineering and the warehouse to keep lines running with minimal working capital."},responsibilities:{vi:["Chạy MRP hằng tuần, rà soát đề xuất đặt hàng và thông điệp ngoại lệ (đẩy sớm, lùi lại, hủy).","Duy trì dữ liệu gốc: BOM, thời gian chờ, tồn an toàn, quy tắc lô, tỷ lệ hao hụt.","Kiểm soát hiệu lực thay đổi kỹ thuật (ECN) và cắt chuyển phiên bản BOM.","Phối hợp mua hàng xử lý thiếu hụt, theo dõi ngày giao và đề xuất phương án thay thế.","Theo dõi tồn kho chậm luân chuyển, vật tư lỗi thời và đề xuất xử lý."],en:["Run MRP weekly and review planned orders and exception messages (expedite, defer, cancel).","Maintain master data: BOM, lead times, safety stock, lot rules and scrap rates.","Control engineering change (ECN) effectivity and BOM revision cut-over.","Work with purchasing on shortages, track delivery dates and propose alternatives.","Track slow-moving and obsolete stock and propose dispositions."]},competencies:[{name:{vi:"Logic MRP",en:"MRP logic"},desc:{vi:"Tính nhu cầu gộp, nhu cầu ròng, bù thời gian chờ và áp quy tắc lô chính xác.",en:"Compute gross and net requirements, offset lead times and apply lot rules accurately."}},{name:{vi:"Quản trị dữ liệu gốc",en:"Master data control"},desc:{vi:"Phát hiện sai lệch BOM, thời gian chờ, tồn kho làm méo kết quả kế hoạch.",en:"Spot BOM, lead time and inventory errors that distort planning results."}},{name:{vi:"Phân tích tồn kho",en:"Inventory analysis"},desc:{vi:"Cân bằng mức phục vụ và vốn lưu động bằng phân loại ABC, XYZ và tồn an toàn.",en:"Balance service level and working capital with ABC, XYZ analysis and safety stock."}},{name:{vi:"Phối hợp liên phòng ban",en:"Cross-functional coordination"},desc:{vi:"Làm việc với sản xuất, mua hàng, kỹ thuật để giải quyết thiếu hụt và thay đổi.",en:"Work with production, purchasing and engineering to resolve shortages and changes."}},{name:{vi:"Liêm chính với nhà cung cấp",en:"Supplier integrity"},desc:{vi:"Ra quyết định đặt hàng theo dữ liệu, từ chối lợi ích cá nhân và báo cáo xung đột lợi ích.",en:"Make order decisions from data, refuse personal benefits and report conflicts of interest."}}],knowledge:{vi:["Quy trình hoạch định S&OP, kế hoạch sản xuất tổng thể (MPS) và MRP.","Cấu trúc BOM nhiều cấp, BOM ảo và quản lý hiệu lực thay đổi kỹ thuật.","Quy tắc lô: lô theo lô (L4L), lô cố định, bội số đóng gói, lượng đặt tối thiểu.","Tồn an toàn, điểm đặt hàng và mức phục vụ; ảnh hưởng của biến động nhu cầu và thời gian chờ.","Khung kiến thức hoạch định và kiểm soát tồn kho theo chương trình CPIM của ASCM."],en:["S&OP, master production scheduling (MPS) and MRP processes.","Multi-level BOM structure, phantom BOMs and engineering change effectivity.","Lot rules: lot-for-lot (L4L), fixed lot, pack multiples and minimum order quantity.","Safety stock, reorder point and service level; effects of demand and lead time variability.","Planning and inventory control body of knowledge under the ASCM CPIM programme."]},tools:["Phân hệ MRP trong hệ thống ERP","Bảng tính phân tích tồn kho","Công cụ báo cáo BI","Hệ thống quản lý kho (WMS)","Cổng cộng tác nhà cung cấp"],kpis:{vi:["Tỷ lệ thiếu vật tư gây dừng chuyền (mục tiêu bằng 0).","Số vòng quay tồn kho nguyên vật liệu.","Độ chính xác dữ liệu BOM và tồn kho.","Giá trị tồn kho chậm luân chuyển trên tổng tồn."],en:["Line stoppages caused by material shortages (target zero).","Raw material inventory turns.","BOM and inventory record accuracy.","Slow-moving stock value as a share of total inventory."]},day:[{time:"08:00",vi:"Chạy MRP, lọc thông điệp ngoại lệ và danh sách thiếu hụt của 4 tuần tới.",en:"Run MRP and filter exception messages and shortages for the next 4 weeks."},{time:"09:30",vi:"Kiểm tra các ECN mới hiệu lực, cập nhật phiên bản BOM với kỹ thuật.",en:"Review newly effective ECNs and update BOM revisions with engineering."},{time:"11:00",vi:"Họp với mua hàng về ngày giao của nhà cung cấp và phương án đẩy sớm.",en:"Meet purchasing on supplier delivery dates and expedite options."},{time:"14:00",vi:"Đối chiếu tồn kho hệ thống với kiểm đếm chu kỳ, điều chỉnh sai lệch.",en:"Reconcile system stock with cycle counts and correct variances."},{time:"16:00",vi:"Phát hành đề xuất đặt hàng đã duyệt và báo cáo rủi ro vật tư tuần.",en:"Release approved planned orders and the weekly material risk report."}],mistakes:{vi:["Dùng BOM cũ sau khi ECN đã hiệu lực, dẫn tới thiếu hoặc thừa linh kiện.","Tính tồn khả dụng mà quên trừ phần đã phân bổ cho đơn hàng khác.","Quên làm tròn theo bội số đóng gói, nhà cung cấp không giao được lượng lẻ."],en:["Using an old BOM after the ECN took effect, causing shortages or excess parts.","Counting available stock without subtracting quantities allocated to other orders.","Forgetting pack multiple rounding, so the supplier cannot ship the odd quantity."]},career:[{vi:"Nhân viên kế hoạch vật tư",en:"Material planner"},{vi:"Kỹ sư hoạch định MRP",en:"MRP planning engineer"},{vi:"Trưởng nhóm kế hoạch sản xuất và vật tư",en:"Production and materials planning lead"},{vi:"Giám đốc chuỗi cung ứng",en:"Supply chain director"}],glossary:[{term:"BOM",vi:"Danh mục vật tư cấu thành sản phẩm cùng định mức sử dụng của từng linh kiện.",en:"Bill of materials listing the components of a product and the usage of each."},{term:"ECN",vi:"Thông báo thay đổi kỹ thuật, quy định nội dung thay đổi và ngày hoặc lô bắt đầu hiệu lực.",en:"Engineering change notice defining the change and its effective date or lot."},{term:"Net requirement",vi:"Nhu cầu ròng sau khi trừ tồn khả dụng, hàng đang về và cộng tồn an toàn.",en:"Requirement left after subtracting available stock and receipts and adding safety stock."},{term:"Lead time offset",vi:"Lùi ngày phát hành đơn hàng theo thời gian chờ để vật tư về kịp ngày cần.",en:"Moving the order release date back by the lead time so material arrives on time."},{term:"MOQ",vi:"Lượng đặt hàng tối thiểu nhà cung cấp chấp nhận cho mỗi đơn.",en:"Minimum order quantity a supplier accepts per order."}],quiz:[{q:{vi:"Nhu cầu gộp 1000, tồn 400 (đã phân bổ 100), hàng đang về 200, tồn an toàn 150. Nhu cầu ròng bằng bao nhiêu?",en:"Gross need 1000, on hand 400 (100 allocated), on order 200, safety stock 150. What is the net need?"},options:{vi:["550","450","650","750"],en:["550","450","650","750"]},answer:2,explain:{vi:"Nhu cầu ròng = 1000 - (400 - 100) - 200 + 150 = 650.",en:"Net need = 1000 - (400 - 100) - 200 + 150 = 650."}},{q:{vi:"ECN hiệu lực từ tuần 20, đơn hàng cần vật tư tuần 22. Bạn dùng BOM nào?",en:"An ECN takes effect in week 20 and the order needs material in week 22. Which BOM do you use?"},options:{vi:["Phiên bản mới theo ECN","Phiên bản cũ đang mở","Phiên bản có chi phí thấp nhất","Tùy sản xuất chọn"],en:["The new revision per the ECN","The old open revision","The cheapest revision","Whatever production prefers"]},answer:0,explain:{vi:"Tuần cần vật tư nằm sau ngày hiệu lực nên phải áp phiên bản BOM mới.",en:"The need week is after the effectivity date, so the new BOM revision applies."}},{q:{vi:"Nhu cầu ròng 1030 cái, bội số đóng gói 250. Lượng đặt hàng là bao nhiêu?",en:"Net need is 1030 pcs and the pack multiple is 250. What is the order quantity?"},options:{vi:["1000","1030","1500","1250"],en:["1000","1030","1500","1250"]},answer:3,explain:{vi:"Làm tròn lên bội số 250 gần nhất không nhỏ hơn 1030 là 1250.",en:"Rounding up to the nearest 250 multiple not below 1030 gives 1250."}},{q:{vi:"Nhà cung cấp hứa hoa hồng riêng nếu bạn đặt nhiều hơn số MRP. Bạn làm gì?",en:"A supplier promises a private commission if you order more than MRP says. What do you do?"},options:{vi:["Nhận vì công ty vẫn có hàng","Từ chối, đặt theo MRP và báo cáo bộ phận tuân thủ","Đặt thêm một nửa cho cân bằng","Im lặng và để mua hàng quyết định"],en:["Accept since the company still gets stock","Refuse, order per MRP and report to compliance","Order half the extra as a compromise","Stay silent and let purchasing decide"]},answer:1,explain:{vi:"Nhận lợi ích cá nhân là xung đột lợi ích, gây tồn kho thừa và vi phạm quy tắc ứng xử.",en:"A personal benefit is a conflict of interest, causes excess stock and breaches the code of conduct."}}]}},"KK-542":{scenario:{company:"Tân Việt Auto Components",supervisor:{name:"Ngô Thanh Tùng",role:{vi:"Trưởng phòng Chất lượng Nhà cung cấp",en:"Supplier Quality Manager"}},ref_code:"PPAP-3307",title:{vi:"Ppk không phải Pp. Phê duyệt phải có căn cứ.",en:"Ppk is not Pp. Approval needs evidence."},brief:{vi:"Nhà cung cấp nộp hồ sơ PPAP-3307 cho ống lót có đường kính lỗ 10.00 ± 0.20 mm (đặc tính đặc biệt). Nghiên cứu năng lực 125 mẫu: trung bình 10.06 mm, độ lệch chuẩn tổng thể 0.040 mm. Bản đánh giá nháp ghi Ppk 1.67 và đề xuất phê duyệt. Đối chiếu với quy tắc khách hàng, sửa chỉ số Ppk (làm tròn 2 chữ số) và trạng thái PPAP, rồi lập báo cáo có căn cứ.",en:"A supplier submitted PPAP-3307 for a bushing with bore diameter 10.00 ± 0.20 mm (special characteristic). The 125-piece capability study shows mean 10.06 mm and overall standard deviation 0.040 mm. The draft review states Ppk 1.67 and recommends approval. Check it against the customer rules, correct the Ppk (2 decimals) and the PPAP status, then write an evidence-based report."},reference_title:{vi:"Yêu cầu riêng của khách hàng về PPAP đã duyệt · PPAP-3307",en:"Approved customer-specific PPAP requirements · PPAP-3307"},fields:[{id:"PPAP_STATUS",label:{vi:"Trạng thái phê duyệt PPAP",en:"PPAP approval status"},initial:"APPROVED",expected:"REJECTED",choices:["APPROVED","INTERIM","REJECTED"],reference:"Quy tắc chấp nhận năng lực quá trình",hint:{vi:"Trạng thái phụ thuộc vào Ppk thật của quá trình, không phải số nhà cung cấp tự ghi.",en:"The status depends on the true process Ppk, not the figure the supplier wrote."}},{id:"PPK",label:{vi:"Chỉ số năng lực Ppk",en:"Performance index Ppk"},initial:"1.67",expected:"1.17",reference:"Bảng dữ liệu nghiên cứu năng lực",ref_value:{vi:"USL 10.20; LSL 9.80; trung bình 10.06; độ lệch chuẩn tổng thể 0.040; n = 125",en:"USL 10.20; LSL 9.80; mean 10.06; overall standard deviation 0.040; n = 125"},hint:{vi:"Chỉ số 1.67 bỏ qua việc quá trình lệch tâm; hãy xét khoảng cách từ trung bình tới giới hạn gần nhất.",en:"The 1.67 figure ignores the off-centre process; use the distance from the mean to the nearest limit."}}],sop32:{vi:"Ppk = min(USL - trung bình, trung bình - LSL) / (3 x độ lệch chuẩn tổng thể), làm tròn 2 chữ số. Quy tắc khách hàng (mô phỏng): Ppk ≥ 1.67 APPROVED; 1.33 ≤ Ppk < 1.67 INTERIM; Ppk < 1.33 REJECTED.",en:"Ppk = min(USL - mean, mean - LSL) / (3 x overall standard deviation), rounded to 2 decimals. Customer rule (training): Ppk ≥ 1.67 APPROVED; 1.33 ≤ Ppk < 1.67 INTERIM; Ppk < 1.33 REJECTED."},context:{label:"SQM PORTAL / PPAP-3307",metrics:[{label:{vi:"Dung sai",en:"Tolerance"},value:"10.00 ± 0.20 mm"},{label:{vi:"Trung bình mẫu",en:"Sample mean"},value:"10.06 mm"},{label:{vi:"Độ lệch chuẩn tổng thể",en:"Overall std deviation"},value:"0.040 mm"}]},crisis:{vi:"Giám đốc kinh doanh của nhà cung cấp gọi: “Anh ký APPROVED giúp em, tuần sau khách chạy xe mẫu rồi. Bên em mời anh sang tham quan nhà máy mẹ ở nước ngoài, mọi chi phí bên em lo.”",en:"The supplier's sales director calls: “Please sign APPROVED, the customer's prototype build is next week. We invite you to visit our parent plant abroad, all expenses on us.”"},options:{safe:{vi:"Từ chối chuyến đi theo quy định quà tặng, ghi Ppk 1.17 và REJECTED, yêu cầu kiểm 100% và kế hoạch cải tiến, báo trưởng phòng và khách hàng nếu ảnh hưởng tiến độ.",en:"Decline the trip under the gifts policy, record Ppk 1.17 and REJECTED, require 100% inspection and an improvement plan, and inform the manager and customer if timing is affected."},shortcut:{vi:"Ký APPROVED cho kịp xe mẫu, nhắc nhà cung cấp cải tiến sau.",en:"Sign APPROVED to make the prototype build and ask for improvement later."},wait:{vi:"Giữ hồ sơ trong hộp thư và chờ nhà cung cấp tự gửi số liệu mới.",en:"Leave the file in the inbox and wait for the supplier to send new data."}},questions:{vi:["Vì sao Ppk đúng là 1.17 chứ không phải 1.67? Quá trình đang lệch về phía nào và cần cải tiến gì?","Bạn bảo vệ khách hàng thế nào trong lúc chờ nhà cung cấp cải tiến, và xử lý lời mời tham quan ra sao?"],en:["Why is the correct Ppk 1.17 rather than 1.67? Which way is the process shifted and what must improve?","How do you protect the customer while the supplier improves, and how do you handle the trip invitation?"]},hints:{vi:["So số Ppk trên bản nháp với công thức Pp và Ppk; một chỉ số không tính tới vị trí trung bình.","Áp dụng SOP mục 3.2: tính khoảng cách tới USL và LSL, lấy giá trị nhỏ hơn chia cho 3 lần độ lệch chuẩn.","Đọc lại SOP mục 4.2: quyết định phê duyệt không được chịu ảnh hưởng của quà tặng hay lời mời."],en:["Compare the draft Ppk with the Pp and Ppk formulas; one index ignores where the mean sits.","Apply SOP 3.2: compute distances to USL and LSL and divide the smaller by 3 standard deviations.","Re-read SOP 4.2: approval decisions must not be influenced by gifts or invitations."]}},learning:{summary:{vi:"Kỹ sư Chất lượng Nhà cung cấp (SQE) bảo đảm linh kiện mua vào đạt yêu cầu ngay từ nguồn: đánh giá năng lực nhà cung cấp, duyệt hồ sơ PPAP, theo dõi chất lượng lô hàng, xử lý khiếu nại bằng 8D và thúc đẩy cải tiến liên tục. Công việc đòi hỏi vững thống kê, đo lường, hiểu quy trình sản xuất của nhà cung cấp và giữ sự độc lập, liêm chính trong mọi quyết định chấp nhận.",en:"A Supplier Quality Engineer (SQE) ensures purchased parts meet requirements at the source: auditing supplier capability, reviewing PPAP files, monitoring lot quality, handling complaints through 8D and driving continuous improvement. The role requires solid statistics and metrology, understanding of the supplier's processes and independence and integrity in every acceptance decision."},responsibilities:{vi:["Đánh giá, phê duyệt nhà cung cấp mới và đánh giá định kỳ quá trình sản xuất.","Duyệt hồ sơ PPAP: kết quả đo, nghiên cứu năng lực, MSA, PFMEA, kế hoạch kiểm soát.","Theo dõi chất lượng đầu vào, chỉ số PPM và xếp hạng nhà cung cấp.","Phát hành yêu cầu hành động khắc phục, giám sát báo cáo 8D và hiệu lực khắc phục.","Quản lý thay đổi từ nhà cung cấp và phối hợp phê duyệt lại khi cần."],en:["Assess and approve new suppliers and audit manufacturing processes periodically.","Review PPAP files: dimensional results, capability studies, MSA, PFMEA and control plans.","Monitor incoming quality, PPM metrics and supplier ratings.","Issue corrective action requests and oversee 8D reports and their effectiveness.","Manage supplier change notifications and coordinate requalification when needed."]},competencies:[{name:{vi:"Thống kê quá trình",en:"Process statistics"},desc:{vi:"Tính và diễn giải Cp, Cpk, Pp, Ppk, đọc biểu đồ kiểm soát và phân biệt biến động chung, đặc biệt.",en:"Calculate and interpret Cp, Cpk, Pp and Ppk, read control charts and separate common from special causes."}},{name:{vi:"Công cụ chất lượng ô tô",en:"Automotive core tools"},desc:{vi:"Vận dụng APQP, PPAP, FMEA, MSA, SPC theo yêu cầu khách hàng.",en:"Apply APQP, PPAP, FMEA, MSA and SPC to customer requirements."}},{name:{vi:"Đánh giá quá trình",en:"Process auditing"},desc:{vi:"Đánh giá tại xưởng nhà cung cấp, phát hiện điểm yếu kiểm soát và rủi ro.",en:"Audit supplier shop floors and find control weaknesses and risks."}},{name:{vi:"Giải quyết vấn đề",en:"Problem solving"},desc:{vi:"Dẫn dắt 8D, 5 Why, Ishikawa để tìm nguyên nhân gốc và ngăn tái diễn.",en:"Lead 8D, 5 Whys and Ishikawa to find root causes and prevent recurrence."}},{name:{vi:"Độc lập và liêm chính",en:"Independence and integrity"},desc:{vi:"Ra quyết định dựa trên dữ liệu, từ chối quà tặng và áp lực tiến độ không hợp lệ.",en:"Decide from data and refuse gifts and improper schedule pressure."}}],knowledge:{vi:["IATF 16949:2016 hệ thống quản lý chất lượng ngành ô tô, dựa trên ISO 9001:2015.","Sổ tay PPAP và APQP của AIAG, gồm 18 yếu tố hồ sơ PPAP và các mức nộp.","Sổ tay FMEA AIAG-VDA (2019) và phương pháp 7 bước.","Sổ tay MSA và SPC của AIAG: Gage R&R, biểu đồ kiểm soát, chỉ số năng lực.","ISO 2859-1 kế hoạch lấy mẫu kiểm tra theo thuộc tính dựa trên AQL."],en:["IATF 16949:2016 automotive quality management system, built on ISO 9001:2015.","AIAG PPAP and APQP manuals, including the 18 PPAP elements and submission levels.","AIAG-VDA FMEA Handbook (2019) and its 7-step approach.","AIAG MSA and SPC manuals: Gage R&R, control charts and capability indices.","ISO 2859-1 attribute sampling plans indexed by AQL."]},tools:["Phần mềm thống kê SPC","Máy đo tọa độ CMM","Cổng quản lý chất lượng nhà cung cấp","Biểu mẫu báo cáo 8D","Bộ dụng cụ đo cầm tay đã hiệu chuẩn"],kpis:{vi:["Tỷ lệ lỗi linh kiện đầu vào tính theo PPM.","Tỷ lệ hồ sơ PPAP được duyệt đúng hạn và đầy đủ.","Thời gian đóng 8D trung bình và tỷ lệ tái diễn lỗi.","Tỷ lệ nhà cung cấp đạt hạng A trong đánh giá định kỳ."],en:["Incoming part defect rate in PPM.","Share of PPAP files approved on time and complete.","Average 8D closure time and defect recurrence rate.","Share of suppliers rated A in periodic reviews."]},day:[{time:"08:00",vi:"Xem báo cáo kiểm tra đầu vào và các lô bị giữ lại trong đêm.",en:"Review incoming inspection results and lots put on hold overnight."},{time:"09:30",vi:"Duyệt hồ sơ PPAP: kiểm tra số liệu năng lực, MSA và kế hoạch kiểm soát.",en:"Review a PPAP file: capability data, MSA and the control plan."},{time:"11:00",vi:"Gọi trực tuyến với nhà cung cấp về tiến độ 8D của khiếu nại tháng trước.",en:"Call a supplier on 8D progress for last month's complaint."},{time:"13:30",vi:"Đánh giá quá trình tại xưởng nhà cung cấp, quan sát trạm kiểm soát đặc tính đặc biệt.",en:"Audit a supplier's process and observe special characteristic control stations."},{time:"16:30",vi:"Cập nhật xếp hạng nhà cung cấp và báo cáo rủi ro chất lượng cho trưởng phòng.",en:"Update supplier ratings and report quality risks to the manager."}],mistakes:{vi:["Nhầm Pp hoặc Cp với Ppk, Cpk nên không thấy quá trình lệch tâm.","Chấp nhận số liệu năng lực khi hệ thống đo chưa qua phân tích MSA.","Phê duyệt vì áp lực tiến độ mà không có biện pháp ngăn chặn hay chấp thuận sai lệch của khách hàng."],en:["Confusing Pp or Cp with Ppk or Cpk and missing an off-centre process.","Accepting capability data before the measurement system passed MSA.","Approving under schedule pressure without containment or a customer deviation approval."]},career:[{vi:"Kỹ thuật viên kiểm tra chất lượng đầu vào",en:"Incoming quality inspector"},{vi:"Kỹ sư chất lượng nhà cung cấp",en:"Supplier quality engineer"},{vi:"Trưởng nhóm chất lượng nhà cung cấp",en:"Supplier quality lead"},{vi:"Giám đốc chất lượng chuỗi cung ứng",en:"Supply chain quality director"}],glossary:[{term:"PPAP",vi:"Quy trình phê duyệt linh kiện sản xuất, chứng minh nhà cung cấp hiểu và đáp ứng yêu cầu ổn định.",en:"Production part approval process proving the supplier understands and consistently meets requirements."},{term:"Ppk",vi:"Chỉ số năng lực thực hiện dùng độ lệch chuẩn tổng thể và xét vị trí trung bình so với giới hạn.",en:"Performance index using overall standard deviation and the mean's position relative to the limits."},{term:"Pp",vi:"Chỉ số so sánh độ rộng dung sai với 6 lần độ lệch chuẩn tổng thể, không xét lệch tâm.",en:"Index comparing tolerance width with 6 overall standard deviations, ignoring centring."},{term:"8D",vi:"Phương pháp 8 bước giải quyết vấn đề từ lập nhóm, ngăn chặn đến ngăn tái diễn.",en:"Eight-discipline problem-solving method from team setup and containment to preventing recurrence."},{term:"PPM",vi:"Số phần triệu, đo số linh kiện lỗi trên một triệu linh kiện giao.",en:"Parts per million, counting defective parts per million delivered."}],quiz:[{q:{vi:"USL 20.5, LSL 19.5, trung bình 20.2, độ lệch chuẩn 0.1. Ppk bằng bao nhiêu?",en:"USL 20.5, LSL 19.5, mean 20.2, standard deviation 0.1. What is Ppk?"},options:{vi:["1.67","2.33","1.00","3.33"],en:["1.67","2.33","1.00","3.33"]},answer:2,explain:{vi:"Ppk = min(20.5 - 20.2, 20.2 - 19.5) / 0.3 = 0.3 / 0.3 = 1.00, thấp hơn ngưỡng chấp nhận.",en:"Ppk = min(20.5 - 20.2, 20.2 - 19.5) / 0.3 = 0.3 / 0.3 = 1.00, below the acceptance threshold."}},{q:{vi:"Nhà cung cấp mời bạn đi du lịch trong lúc bạn đang duyệt hồ sơ của họ. Bạn làm gì?",en:"A supplier invites you on a trip while you are reviewing their file. What do you do?"},options:{vi:["Nhận lời vì đó là văn hóa kinh doanh","Nhận nhưng không nói với ai","Hoãn duyệt hồ sơ cho đến sau chuyến đi","Từ chối, báo cáo theo quy định và duyệt dựa trên dữ liệu"],en:["Accept, it is business culture","Accept but tell no one","Delay the review until after the trip","Decline, report per policy and review on data"]},answer:3,explain:{vi:"Nhận lợi ích từ bên đang được đánh giá tạo xung đột lợi ích và làm mất tính độc lập.",en:"Taking benefits from a party under review creates a conflict of interest and destroys independence."}},{q:{vi:"Vì sao Ppk có thể thấp hơn nhiều so với Pp dù độ phân tán nhỏ?",en:"Why can Ppk be much lower than Pp even with low spread?"},options:{vi:["Vì quá trình lệch tâm so với giữa dung sai","Vì cỡ mẫu quá lớn","Vì dùng máy đo CMM","Vì dung sai quá rộng"],en:["Because the process is off the tolerance centre","Because the sample is too large","Because a CMM was used","Because the tolerance is too wide"]},answer:0,explain:{vi:"Ppk dùng khoảng cách tới giới hạn gần nhất nên phạt quá trình lệch tâm; Pp thì không.",en:"Ppk uses the distance to the nearest limit and penalises off-centre processes; Pp does not."}},{q:{vi:"Bước nào trong 8D phải làm ngay để bảo vệ khách hàng trước khi tìm nguyên nhân gốc?",en:"Which 8D step must happen immediately to protect the customer before finding the root cause?"},options:{vi:["Ghi nhận thành tích nhóm","Biện pháp ngăn chặn tạm thời","Chuẩn hóa tài liệu","Đánh giá chi phí"],en:["Recognise the team","Interim containment action","Standardise documents","Assess costs"]},answer:1,explain:{vi:"Ngăn chặn tạm thời như cách ly, phân loại 100% giúp lỗi không tới tay khách hàng.",en:"Interim containment such as quarantine and 100% sorting keeps defects from reaching the customer."}}]}},"KK-581":{scenario:{company:"Sao Mai Bottling Works",supervisor:{name:"Vũ Thành Nam",role:{vi:"Trưởng nhóm Tự động hóa",en:"Automation Team Lead"}},ref_code:"MOC-6620",title:{vi:"Đúng kiểu tín hiệu. Đúng thang đo. Không ép liên động.",en:"Right signal type. Right scaling. Never force an interlock."},brief:{vi:"Sau khi thay bộ truyền mức LT-301 của bồn siro (dải 0-6500 mm, tín hiệu 4-20 mA), màn hình HMI báo mức cao bất thường và liên động mức cao cắt bơm sớm. Đo vòng bằng thiết bị hiệu chuẩn được 11.2 mA. Đối chiếu cấu hình PLC nháp trong hồ sơ MOC-6620, sửa kiểu kênh đầu vào tương tự và giá trị mức đúng (mm), rồi lập báo cáo có căn cứ.",en:"After replacing level transmitter LT-301 on the syrup tank (range 0-6500 mm, 4-20 mA signal), the HMI shows an abnormally high level and the high-level interlock trips the pump early. A loop calibrator reads 11.2 mA. Check the draft PLC configuration in MOC-6620, correct the analogue input channel type and the true level (mm), then write an evidence-based report."},reference_title:{vi:"Hồ sơ quản lý thay đổi và bảng thiết bị đo đã duyệt · MOC-6620",en:"Approved change record and instrument index · MOC-6620"},fields:[{id:"AI_TYPE",label:{vi:"Kiểu kênh đầu vào tương tự",en:"Analogue input channel type"},initial:"0-20MA",expected:"4-20MA",choices:["0-20MA","4-20MA","0-10V"],reference:"Bảng thiết bị đo LT-301",hint:{vi:"Bộ truyền 2 dây cấp nguồn vòng luôn có dòng nền; kiểu kênh phải khớp tín hiệu ghi trên bảng dữ liệu.",en:"A 2-wire loop-powered transmitter always has a live zero; the channel type must match its datasheet signal."}},{id:"LEVEL_MM",label:{vi:"Mức bồn đúng tại 11.2 mA (mm)",en:"True tank level at 11.2 mA (mm)"},initial:"3640",expected:"2925",reference:"Biên bản đo vòng LT-301",ref_value:{vi:"Dải đo 0-6500 mm ứng với 4-20 mA; dòng đo được 11.2 mA",en:"Range 0-6500 mm maps to 4-20 mA; measured current 11.2 mA"},hint:{vi:"Trừ dòng nền 4 mA trước khi chia cho khoảng 16 mA rồi nhân với dải đo.",en:"Subtract the 4 mA live zero before dividing by the 16 mA span and multiplying by the range."}}],sop32:{vi:"Giá trị kỹ thuật = (dòng đo - 4 mA) / 16 mA x (cận trên - cận dưới) + cận dưới. Kênh tương tự phải cấu hình đúng kiểu tín hiệu ghi trên bảng thiết bị đo.",en:"Engineering value = (measured current - 4 mA) / 16 mA x (upper - lower range) + lower range. The analogue channel must match the signal type in the instrument index."},context:{label:"PLC ENGINEERING / MOC-6620",metrics:[{label:{vi:"Dải đo LT-301",en:"LT-301 range"},value:"0-6500 mm"},{label:{vi:"Dòng vòng đo được",en:"Measured loop current"},value:"11.2 mA"},{label:{vi:"Mức HMI hiển thị",en:"HMI level reading"},value:"3640 mm"}]},terminal:{system:"plc-eng",settable:["AI_TYPE","LEVEL_MM"],commands:[{cmd:"status",out:{vi:"PLC đang RUN; rack 1 khe 4 kênh 3 (LT-301) cấu hình AI_TYPE=0-20MA; HMI hiển thị LEVEL_MM=3640",en:"PLC in RUN; rack 1 slot 4 channel 3 (LT-301) configured AI_TYPE=0-20MA; HMI shows LEVEL_MM=3640"}},{cmd:"cat lt301_datasheet.txt",out:{vi:"Bộ truyền mức radar 2 dây, cấp nguồn vòng, ngõ ra 4-20 mA, dải 0-6500 mm; báo lỗi theo NAMUR NE 43: ≤ 3.6 mA hoặc ≥ 21 mA",en:"2-wire loop-powered radar level transmitter, 4-20 mA output, range 0-6500 mm; NAMUR NE 43 failure signal ≤ 3.6 mA or ≥ 21 mA"}},{cmd:"loopcal lt301",out:{vi:"Dòng vòng đo tại hộp nối JB-03: 11.20 mA, ổn định, không nhiễu",en:"Loop current at junction box JB-03: 11.20 mA, stable, no noise"}},{cmd:"cat moc6620.txt",out:{vi:"MOC-6620: thay bộ truyền 4 dây 0-20 mA cũ bằng loại 2 dây 4-20 mA; mục cập nhật cấu hình PLC chưa ký xác nhận",en:"MOC-6620: old 4-wire 0-20 mA transmitter replaced with 2-wire 4-20 mA type; PLC configuration update item not signed off"}},{cmd:"dipstick t301",out:{vi:"Đo thước nhúng thủ công: mức khoảng 2.9 m, thấp hơn nhiều so với HMI",en:"Manual dipstick: level about 2.9 m, well below the HMI reading"}}]},crisis:{vi:"Trưởng ca nhắn: “Liên động mức cao LAHH-301 cứ cắt bơm vô cớ, anh force bit về 0 cho chạy hết ca đi, mai sửa cấu hình sau, không ai kiểm tra đâu.”",en:"The shift leader messages: “The LAHH-301 high-level interlock keeps tripping the pump for nothing, force the bit to 0 so we finish the shift, fix the config tomorrow, nobody checks.”"},options:{safe:{vi:"Từ chối force liên động; sửa cấu hình qua MOC có phê duyệt, nếu cần bypass tạm thì làm giấy phép kèm biện pháp bù, báo trưởng ca và bộ phận an toàn.",en:"Refuse to force the interlock; fix the configuration under an approved MOC, and if a temporary bypass is needed, use a bypass permit with compensating measures and inform the shift and safety leads."},shortcut:{vi:"Force bit LAHH-301 về 0 để chạy hết ca rồi gỡ force vào sáng mai.",en:"Force the LAHH-301 bit to 0 for the rest of the shift and remove it tomorrow morning."},wait:{vi:"Không can thiệp, để vận hành tự xử lý các lần cắt bơm.",en:"Do nothing and let operations deal with the pump trips."}},questions:{vi:["Vì sao cấu hình 0-20MA làm HMI hiển thị 3640 mm trong khi mức thật là 2925 mm? Lỗi này ảnh hưởng điểm cắt liên động ra sao?","Quy trình nào cho phép bỏ qua liên động an toàn một cách hợp lệ, và vì sao force bit tùy tiện là nguy hiểm?"],en:["Why does the 0-20MA setting make the HMI show 3640 mm when the true level is 2925 mm? How does this shift the interlock trip point?","What procedure allows a safety interlock bypass legitimately, and why is forcing a bit casually dangerous?"]},hints:{vi:["Đặt cấu hình kênh cạnh bảng dữ liệu bộ truyền mới trong hồ sơ MOC.","Áp dụng SOP mục 3.2: dòng nền 4 mA tương ứng 0 mm, khoảng 16 mA tương ứng toàn dải 6500 mm.","Đọc lại SOP mục 4.2: không force, không bypass liên động khi chưa có giấy phép và biện pháp bù."],en:["Place the channel configuration next to the new transmitter datasheet in the MOC file.","Apply SOP 3.2: the 4 mA live zero means 0 mm and the 16 mA span covers the full 6500 mm.","Re-read SOP 4.2: never force or bypass an interlock without a permit and compensating measures."]}},learning:{summary:{vi:"Kỹ sư Tự động hóa và Lập trình PLC/SCADA thiết kế, lập trình, chạy thử và duy trì hệ thống điều khiển nhà máy: PLC, HMI, SCADA, mạng công nghiệp và các vòng đo lường, liên động an toàn. Mục tiêu là dây chuyền vận hành ổn định, an toàn và có dữ liệu tin cậy. Công việc đòi hỏi hiểu quá trình công nghệ, điện, đo lường, kỷ luật quản lý thay đổi và an ninh mạng công nghiệp.",en:"An Industrial Automation Engineer designs, programs, commissions and maintains plant control systems: PLCs, HMIs, SCADA, industrial networks, instrument loops and safety interlocks. The goal is stable, safe production with trustworthy data. The role requires understanding of the process, electrical and instrumentation work, strict change management discipline and industrial cybersecurity."},responsibilities:{vi:["Lập trình PLC theo IEC 61131-3, xây dựng màn hình HMI, SCADA và cơ sở dữ liệu thẻ.","Cấu hình vào ra, thang đo tín hiệu, mạng công nghiệp và đồng bộ thời gian.","Chạy thử vòng đo (loop check), FAT, SAT và bàn giao tài liệu cho vận hành.","Quản lý thay đổi phần mềm điều khiển, sao lưu phiên bản và kiểm soát force, bypass.","Xử lý sự cố điều khiển, tối ưu vòng PID và hệ thống cảnh báo."],en:["Program PLCs per IEC 61131-3 and build HMI, SCADA screens and tag databases.","Configure I/O, signal scaling, industrial networks and time synchronisation.","Perform loop checks, FAT and SAT and hand over documentation to operations.","Manage control software changes, version backups and force or bypass control.","Troubleshoot control faults and tune PID loops and alarm systems."]},competencies:[{name:{vi:"Lập trình PLC",en:"PLC programming"},desc:{vi:"Viết chương trình rõ ràng bằng ngôn ngữ thang, khối chức năng, văn bản cấu trúc và tái sử dụng khối.",en:"Write clear ladder, function block and structured text code with reusable blocks."}},{name:{vi:"Đo lường và tín hiệu",en:"Instrumentation and signals"},desc:{vi:"Hiểu 4-20 mA, HART, cấp nguồn vòng, thang đo và tín hiệu báo lỗi của thiết bị đo.",en:"Understand 4-20 mA, HART, loop power, scaling and instrument failure signals."}},{name:{vi:"An toàn chức năng",en:"Functional safety"},desc:{vi:"Phân biệt hệ thống điều khiển cơ bản với hệ thống an toàn và quản lý bypass đúng quy trình.",en:"Separate basic control from safety systems and manage bypasses by procedure."}},{name:{vi:"Mạng và an ninh OT",en:"OT networks and security"},desc:{vi:"Thiết kế phân vùng mạng, kiểm soát truy cập và sao lưu theo tiếp cận IEC 62443.",en:"Design network zones, access control and backups following IEC 62443."}},{name:{vi:"Chạy thử và xử lý sự cố",en:"Commissioning and troubleshooting"},desc:{vi:"Kiểm tra từng vòng từ hiện trường đến HMI, khoanh vùng lỗi nhanh và ghi nhận đầy đủ.",en:"Check every loop from field to HMI, isolate faults quickly and record everything."}}],knowledge:{vi:["IEC 61131-3 về ngôn ngữ lập trình PLC.","IEC 61508 và IEC 61511 về an toàn chức năng cho hệ thống điều khiển quá trình.","Khuyến nghị NAMUR NE 43 về mức dòng báo lỗi của tín hiệu 4-20 mA.","ISA-18.2 về quản lý hệ thống cảnh báo; ISA-88 về điều khiển mẻ.","ISA/IEC 62443 về an ninh mạng hệ thống tự động hóa công nghiệp."],en:["IEC 61131-3 on PLC programming languages.","IEC 61508 and IEC 61511 on functional safety for process control systems.","NAMUR NE 43 recommendation on failure current levels for 4-20 mA signals.","ISA-18.2 on alarm management; ISA-88 on batch control.","ISA/IEC 62443 on cybersecurity of industrial automation systems."]},tools:["Phần mềm lập trình PLC","Phần mềm SCADA/HMI","Thiết bị hiệu chuẩn vòng dòng","Bộ cấu hình thiết bị HART","Máy phân tích mạng công nghiệp"],kpis:{vi:["Thời gian dừng máy do lỗi điều khiển mỗi tháng.","Tỷ lệ thay đổi phần mềm đi qua MOC và có sao lưu.","Số force, bypass đang tồn tại quá hạn (mục tiêu bằng 0).","Số cảnh báo trên mỗi người vận hành mỗi giờ."],en:["Monthly downtime caused by control faults.","Share of software changes done under MOC with backups.","Overdue active forces and bypasses (target zero).","Alarms per operator per hour."]},day:[{time:"07:45",vi:"Kiểm tra danh sách force, bypass và cảnh báo tồn đọng từ ca đêm.",en:"Check the list of forces, bypasses and standing alarms from the night shift."},{time:"09:00",vi:"Đo vòng thiết bị mới thay theo MOC, đối chiếu thang đo với bảng thiết bị.",en:"Loop-check newly replaced instruments under MOC and match scaling to the index."},{time:"11:00",vi:"Sửa logic khởi động bơm, mô phỏng trên máy tính trước khi nạp xuống PLC.",en:"Modify pump start logic and simulate offline before downloading to the PLC."},{time:"14:00",vi:"Tinh chỉnh vòng PID nhiệt độ, ghi lại thông số trước và sau.",en:"Tune a temperature PID loop and record before and after parameters."},{time:"16:30",vi:"Sao lưu chương trình, cập nhật nhật ký thay đổi và bàn giao ca.",en:"Back up programs, update the change log and hand over to the next shift."}],mistakes:{vi:["Cấu hình kênh 0-20 mA cho bộ truyền 4-20 mA khiến mọi giá trị bị sai lệch.","Force bit hoặc bypass liên động để chạy tạm rồi quên gỡ.","Nạp chương trình trực tiếp khi máy chạy mà không sao lưu và không qua MOC."],en:["Configuring a 0-20 mA channel for a 4-20 mA transmitter, skewing every reading.","Forcing a bit or bypassing an interlock temporarily and forgetting to remove it.","Downloading code online to a running machine without a backup or MOC."]},career:[{vi:"Kỹ thuật viên điện - tự động hóa",en:"Electrical and automation technician"},{vi:"Kỹ sư tự động hóa PLC/SCADA",en:"PLC/SCADA automation engineer"},{vi:"Kỹ sư trưởng hệ thống điều khiển",en:"Lead control systems engineer"},{vi:"Trưởng phòng tự động hóa và OT",en:"Head of automation and OT"}],glossary:[{term:"Live zero",vi:"Mức dòng nền 4 mA đại diện điểm 0 của thang đo, giúp phân biệt mất tín hiệu với giá trị 0.",en:"The 4 mA base current representing zero, which separates signal loss from a true zero."},{term:"Loop check",vi:"Kiểm tra từng vòng đo từ thiết bị hiện trường tới PLC và HMI trước khi vận hành.",en:"Checking each loop from the field device to the PLC and HMI before operation."},{term:"Interlock",vi:"Logic liên động tự động dừng hoặc chặn thiết bị khi điều kiện không an toàn.",en:"Logic that automatically stops or blocks equipment under unsafe conditions."},{term:"MOC",vi:"Quản lý thay đổi, đánh giá rủi ro và phê duyệt trước khi sửa thiết bị, phần mềm, quy trình.",en:"Management of change, assessing risk and approving before modifying equipment, software or procedures."},{term:"Force",vi:"Ép trạng thái vào ra hoặc bit trong PLC bất kể logic chương trình, phải được kiểm soát chặt.",en:"Overriding an I/O point or bit in the PLC regardless of logic, which must be tightly controlled."}],quiz:[{q:{vi:"Bộ truyền áp suất dải 0-10 bar, tín hiệu 4-20 mA, đang ra 8 mA. Áp suất là bao nhiêu?",en:"A 0-10 bar pressure transmitter with 4-20 mA output reads 8 mA. What is the pressure?"},options:{vi:["4.0 bar","2.5 bar","5.0 bar","8.0 bar"],en:["4.0 bar","2.5 bar","5.0 bar","8.0 bar"]},answer:1,explain:{vi:"Áp suất = (8 - 4) / 16 x 10 = 2.5 bar; dùng 8/20 x 10 sẽ ra sai 4.0 bar.",en:"Pressure = (8 - 4) / 16 x 10 = 2.5 bar; using 8/20 x 10 gives the wrong 4.0 bar."}},{q:{vi:"Theo NAMUR NE 43, dòng 3.4 mA từ bộ truyền 4-20 mA nghĩa là gì?",en:"Under NAMUR NE 43, what does 3.4 mA from a 4-20 mA transmitter mean?"},options:{vi:["Giá trị bằng 0","Giá trị âm hợp lệ","Tín hiệu đang được hiệu chuẩn","Báo lỗi thiết bị hoặc đứt vòng"],en:["Zero value","A valid negative value","Calibration in progress","Device fault or broken loop"]},answer:3,explain:{vi:"Dòng ≤ 3.6 mA nằm trong vùng báo lỗi, PLC phải xử lý như tín hiệu hỏng.",en:"A current ≤ 3.6 mA is in the failure band and the PLC must treat it as a bad signal."}},{q:{vi:"Trưởng ca yêu cầu force liên động an toàn để chạy hết ca. Bạn làm gì?",en:"The shift leader asks you to force a safety interlock to finish the shift. What do you do?"},options:{vi:["Từ chối, xử lý nguyên nhân qua MOC hoặc làm giấy phép bypass có biện pháp bù","Force và ghi chú để mai gỡ","Tắt cảnh báo trên HMI","Đổi điểm đặt liên động lên cao hơn"],en:["Refuse, fix the cause via MOC or use a bypass permit with compensating measures","Force it and leave a note to remove tomorrow","Silence the alarm on the HMI","Raise the interlock setpoint"]},answer:0,explain:{vi:"Liên động bảo vệ người và thiết bị; mọi bypass phải có phê duyệt, thời hạn và biện pháp bù.",en:"Interlocks protect people and equipment; any bypass needs approval, a time limit and compensating measures."}},{q:{vi:"Chuẩn IEC 61131-3 quy định nội dung gì?",en:"What does IEC 61131-3 define?"},options:{vi:["Mức an toàn SIL","Cáp mạng công nghiệp","Ngôn ngữ lập trình PLC","An ninh mạng OT"],en:["Safety integrity levels","Industrial network cabling","PLC programming languages","OT cybersecurity"]},answer:2,explain:{vi:"IEC 61131-3 định nghĩa các ngôn ngữ như LD, FBD, ST, SFC cho bộ điều khiển lập trình.",en:"IEC 61131-3 defines languages such as LD, FBD, ST and SFC for programmable controllers."}}]}},"KK-582":{scenario:{company:"Kim Long Precision Molds",supervisor:{name:"Đặng Minh Quân",role:{vi:"Trưởng nhóm Thiết kế Khuôn",en:"Mold Design Lead"}},ref_code:"MD-4471",title:{vi:"Đủ lực kẹp. Đúng máy ép. Tôn trọng bản quyền thiết kế.",en:"Enough clamp force. Right press. Respect design rights."},brief:{vi:"Khuôn MD-4471 ép nắp hộp nhựa PP, 4 lòng khuôn, diện tích chiếu mỗi lòng 80 cm2, kênh dẫn và cổng phun 30 cm2. Phân tích điền đầy cho áp suất lòng khuôn 400 kgf/cm2 (mô phỏng), hệ số an toàn 1.15. Bảng đề xuất nháp chọn máy ép chưa đúng. Đối chiếu với tiêu chuẩn thiết kế khuôn đã duyệt, sửa lực kẹp yêu cầu (tấn lực) và máy ép, rồi lập báo cáo có căn cứ.",en:"Mold MD-4471 produces PP box lids with 4 cavities, 80 cm2 projected area per cavity and 30 cm2 for runners and gates. Fill analysis gives a cavity pressure of 400 kgf/cm2 (training value) and the safety factor is 1.15. The draft proposal picks the wrong press. Check it against the approved mold design standard, correct the required clamp force (tonnes-force) and the press, then write an evidence-based report."},reference_title:{vi:"Tiêu chuẩn thiết kế khuôn và danh sách máy ép đã duyệt · MD-4471",en:"Approved mold design standard and press list · MD-4471"},fields:[{id:"PRESS",label:{vi:"Máy ép được chọn",en:"Selected injection press"},initial:"150T",expected:"180T",choices:["150T","180T","250T"],reference:"Danh sách máy ép xưởng",hint:{vi:"Chọn máy nhỏ nhất có lực kẹp định mức không thấp hơn lực kẹp yêu cầu đã nhân hệ số an toàn.",en:"Choose the smallest press whose rated clamp force is not below the required force including the safety factor."}},{id:"CLAMP_TF",label:{vi:"Lực kẹp yêu cầu (tấn lực)",en:"Required clamp force (tf)"},initial:"128",expected:"161",reference:"Bảng tính lực kẹp khuôn",ref_value:{vi:"4 lòng x 80 cm2; kênh dẫn 30 cm2; áp suất 400 kgf/cm2; hệ số an toàn 1.15",en:"4 cavities x 80 cm2; runners 30 cm2; pressure 400 kgf/cm2; safety factor 1.15"},hint:{vi:"Diện tích chiếu phải gồm cả kênh dẫn, cổng phun; đừng quên hệ số an toàn.",en:"Projected area must include runners and gates; do not forget the safety factor."}}],sop32:{vi:"Lực kẹp (tf) = (số lòng x diện tích chiếu mỗi lòng + diện tích kênh dẫn) x áp suất lòng khuôn x hệ số an toàn / 1000; chọn máy nhỏ nhất có lực kẹp định mức ≥ lực yêu cầu.",en:"Clamp force (tf) = (cavities x projected area per cavity + runner area) x cavity pressure x safety factor / 1000; choose the smallest press rated ≥ the required force."},context:{label:"MOLD DESIGN / MD-4471",metrics:[{label:{vi:"Số lòng khuôn",en:"Cavities"},value:"4"},{label:{vi:"Diện tích chiếu mỗi lòng",en:"Projected area per cavity"},value:"80 cm2"},{label:{vi:"Áp suất lòng khuôn mô phỏng",en:"Training cavity pressure"},value:"400 kgf/cm2"}]},terminal:{system:"mold-sim",settable:["PRESS","CLAMP_TF"],commands:[{cmd:"status",out:{vi:"Dự án MD-4471: khuôn 2 tấm, 4 lòng, nhựa PP; đề xuất nháp CLAMP_TF=128, PRESS=150T",en:"Project MD-4471: 2-plate mold, 4 cavities, PP resin; draft proposal CLAMP_TF=128, PRESS=150T"}},{cmd:"cat part_spec.txt",out:{vi:"Nắp hộp 120 x 66.7 mm, diện tích chiếu mỗi sản phẩm 80 cm2, chiều dày thành 1.6 mm",en:"Lid 120 x 66.7 mm, projected area per part 80 cm2, wall thickness 1.6 mm"}},{cmd:"cat runner.txt",out:{vi:"Hệ kênh dẫn nguội hình chữ H và 4 cổng phun cạnh: diện tích chiếu 30 cm2",en:"H-shaped cold runner and 4 edge gates: projected area 30 cm2"}},{cmd:"fill-analysis",out:{vi:"Áp suất lòng khuôn lớn nhất tại điểm chuyển V/P: 400 kgf/cm2 (mô phỏng); cảnh báo nguy cơ bavia nếu lực kẹp thiếu",en:"Peak cavity pressure at V/P switchover: 400 kgf/cm2 (training value); flash risk warning if clamp force is short"}},{cmd:"cat press_list.txt",out:{vi:"Máy sẵn có: 150T, 180T, 250T; khoảng cách giữa các trụ đều đủ cho kích thước khuôn",en:"Available presses: 150T, 180T, 250T; tie-bar spacing fits the mold on all of them"}}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn: “Khách mới muốn nắp hộp giống hệt của khách cũ. Lấy file CAD khuôn của khách cũ sửa logo là xong, khỏi thiết kế lại, họ không biết đâu.”",en:"The sales manager messages: “The new client wants a lid identical to our old client's. Take the old client's mold CAD file, change the logo and we are done, they will never know.”"},options:{safe:{vi:"Từ chối dùng file CAD của khách cũ vì thuộc bảo mật và quyền sở hữu của họ; báo trưởng nhóm, đề nghị thiết kế độc lập từ yêu cầu và bản vẽ của khách mới.",en:"Refuse to reuse the old client's CAD file since it is confidential and their property; inform the lead and propose an independent design from the new client's own requirements and drawings."},shortcut:{vi:"Sao chép file CAD cũ, đổi logo và kích thước nhỏ để kịp báo giá.",en:"Copy the old CAD file, change the logo and a few dimensions to make the quote."},wait:{vi:"Không trả lời và để kinh doanh tự tìm người làm.",en:"Do not reply and let sales find someone else to do it."}},questions:{vi:["Vì sao lực kẹp đúng là 161 tấn lực và máy 180T phù hợp hơn 150T? Nếu ép trên máy 150T, sản phẩm sẽ gặp lỗi gì?","Dữ liệu CAD của khách hàng được bảo vệ thế nào, và bạn đề xuất cách đáp ứng khách mới hợp pháp ra sao?"],en:["Why is the correct clamp force 161 tf and why does the 180T press fit better than 150T? What defects appear if you mold on 150T?","How is customer CAD data protected, and how do you propose to serve the new client lawfully?"]},hints:{vi:["Đặt bảng đề xuất nháp cạnh danh sách máy ép và kiểm tra quy tắc chọn máy.","Áp dụng SOP mục 3.2: cộng diện tích kênh dẫn vào tổng diện tích chiếu rồi nhân áp suất và hệ số an toàn.","Đọc lại SOP mục 4.2: dữ liệu thiết kế của khách hàng chỉ dùng cho dự án của chính họ."],en:["Place the draft proposal next to the press list and check the selection rule.","Apply SOP 3.2: add the runner area to the total projected area, then apply pressure and safety factor.","Re-read SOP 4.2: customer design data may only be used for that customer's own project."]}},learning:{summary:{vi:"Kỹ sư Thiết kế Cơ khí và Khuôn mẫu dùng CAD, CAM, CAE để thiết kế sản phẩm, khuôn ép nhựa, khuôn dập và đồ gá, lập trình gia công CNC và mô phỏng kỹ thuật trước khi chế tạo. Giá trị tạo ra là khuôn chạy ổn định ngay từ lần thử đầu, sản phẩm đúng dung sai, chi phí và thời gian phát triển thấp. Công việc đòi hỏi vững vật liệu, gia công, dung sai và bảo mật dữ liệu khách hàng.",en:"A Mechanical CAD/CAM/CAE Engineer uses CAD, CAM and CAE to design products, injection molds, stamping dies and fixtures, program CNC machining and simulate before manufacture. The value is a mold that runs stably from the first trial, parts within tolerance and low development cost and time. The role requires solid knowledge of materials, machining, tolerances and customer data confidentiality."},responsibilities:{vi:["Phân tích bản vẽ sản phẩm, đánh giá khả năng chế tạo (DFM) và đề xuất sửa thiết kế.","Thiết kế khuôn 3D: mặt phân khuôn, hệ kênh dẫn, làm nguội, đẩy sản phẩm, thoát khí.","Mô phỏng điền đầy, cong vênh, phân tích bền và chọn máy ép phù hợp.","Lập trình CAM, chọn dao, chế độ cắt và kiểm tra va chạm trước khi gia công.","Lập bản vẽ 2D có GD&T, quản lý phiên bản và lưu trữ dữ liệu theo dự án."],en:["Analyse part drawings, assess manufacturability (DFM) and propose design changes.","Design 3D molds: parting surface, runners, cooling, ejection and venting.","Simulate filling, warpage and strength and select the right press.","Program CAM, choose tools and cutting data and check collisions before machining.","Produce 2D drawings with GD&T, control revisions and archive data by project."]},competencies:[{name:{vi:"Mô hình hóa CAD",en:"CAD modelling"},desc:{vi:"Dựng mô hình tham số, bề mặt phức tạp và lắp ráp khuôn đầy đủ chi tiết tiêu chuẩn.",en:"Build parametric models, complex surfaces and full mold assemblies with standard parts."}},{name:{vi:"Mô phỏng CAE",en:"CAE simulation"},desc:{vi:"Thiết lập lưới, điều kiện biên, đọc kết quả điền đầy, cong vênh, ứng suất và đánh giá độ tin cậy.",en:"Set up meshes and boundary conditions, read fill, warpage and stress results and judge their reliability."}},{name:{vi:"Lập trình CAM",en:"CAM programming"},desc:{vi:"Tạo đường chạy dao tối ưu, kiểm soát dư lượng và độ nhám bề mặt.",en:"Create efficient toolpaths and control stock allowance and surface finish."}},{name:{vi:"Dung sai và GD&T",en:"Tolerancing and GD&T"},desc:{vi:"Đặt dung sai hình học, chuỗi kích thước và lắp ghép phù hợp chức năng.",en:"Apply geometric tolerances, tolerance stacks and functional fits."}},{name:{vi:"Bảo mật dữ liệu thiết kế",en:"Design data confidentiality"},desc:{vi:"Tuân thủ thỏa thuận bảo mật, phân quyền truy cập và không tái sử dụng dữ liệu của khách khác.",en:"Honour NDAs, control access and never reuse another customer's data."}}],knowledge:{vi:["ISO 1101 và ASME Y14.5 về dung sai hình học và vị trí (GD&T).","ISO 286 về hệ thống dung sai và lắp ghép kích thước.","Đặc tính nhựa nhiệt dẻo: độ co ngót, nhiệt độ gia công, góc thoát khuôn.","Nguyên lý tính lực kẹp, thiết kế hệ làm nguội và cân bằng dòng chảy nhiều lòng khuôn.","Luật Sở hữu trí tuệ và nghĩa vụ bảo mật theo hợp đồng đối với kiểu dáng, dữ liệu thiết kế."],en:["ISO 1101 and ASME Y14.5 on geometric dimensioning and tolerancing (GD&T).","ISO 286 on the system of limits and fits.","Thermoplastic properties: shrinkage, processing temperature and draft angles.","Clamp force calculation, cooling design and flow balancing for multi-cavity molds.","Intellectual property law and contractual confidentiality for designs and design data."]},tools:["Phần mềm CAD 3D tham số","Phần mềm CAM gia công CNC","Phần mềm mô phỏng ép phun","Phần mềm phân tích phần tử hữu hạn","Máy đo tọa độ CMM"],kpis:{vi:["Tỷ lệ khuôn đạt ngay ở lần thử T1.","Số lần sửa khuôn sau thử trên mỗi dự án.","Thời gian thiết kế so với kế hoạch.","Số sự cố rò rỉ dữ liệu thiết kế (mục tiêu bằng 0)."],en:["Share of molds passing at the first T1 trial.","Mold corrections after trials per project.","Design lead time versus plan.","Design data leakage incidents (target zero)."]},day:[{time:"08:00",vi:"Rà soát bản vẽ sản phẩm mới, ghi các điểm cần góc thoát và đổi chiều dày.",en:"Review a new part drawing and mark spots needing draft and thickness changes."},{time:"09:30",vi:"Chạy mô phỏng điền đầy, kiểm tra đường hàn, bọt khí và áp suất lòng khuôn.",en:"Run a fill simulation and check weld lines, air traps and cavity pressure."},{time:"11:00",vi:"Họp DFM với khách hàng, thống nhất vị trí cổng phun và mặt phân khuôn.",en:"Hold a DFM meeting with the client to agree gate location and parting line."},{time:"14:00",vi:"Lập trình CAM cho tấm lòng khuôn, kiểm tra va chạm dao và đồ gá.",en:"Program CAM for the cavity plate and check tool and fixture collisions."},{time:"16:30",vi:"Phát hành bản vẽ, cập nhật phiên bản và lưu dữ liệu vào thư mục dự án có phân quyền.",en:"Release drawings, update revisions and file data in the access-controlled project folder."}],mistakes:{vi:["Tính lực kẹp chỉ theo diện tích sản phẩm, bỏ qua kênh dẫn và hệ số an toàn.","Dùng hệ số co ngót của vật liệu khác khiến kích thước sản phẩm sai.","Tái sử dụng dữ liệu CAD của khách hàng khác, vi phạm bảo mật và quyền sở hữu."],en:["Computing clamp force from part area only, ignoring runners and safety factor.","Using another material's shrinkage factor, leading to wrong part dimensions.","Reusing another customer's CAD data, breaching confidentiality and ownership."]},career:[{vi:"Kỹ thuật viên thiết kế CAD",en:"CAD design technician"},{vi:"Kỹ sư thiết kế khuôn",en:"Mold design engineer"},{vi:"Kỹ sư trưởng CAE và khuôn mẫu",en:"Lead CAE and tooling engineer"},{vi:"Trưởng phòng kỹ thuật khuôn mẫu",en:"Head of tooling engineering"}],glossary:[{term:"Projected area",vi:"Diện tích hình chiếu của sản phẩm và kênh dẫn lên mặt phân khuôn, dùng để tính lực kẹp.",en:"Area of the part and runners projected onto the parting plane, used to compute clamp force."},{term:"Flash",vi:"Bavia, nhựa tràn qua mặt phân khuôn do lực kẹp thiếu hoặc khuôn mòn.",en:"Plastic leaking through the parting line due to low clamp force or mold wear."},{term:"V/P switchover",vi:"Điểm chuyển từ điều khiển tốc độ phun sang điều khiển áp suất giữ.",en:"The point where injection switches from velocity control to pressure holding."},{term:"DFM",vi:"Thiết kế cho sản xuất, điều chỉnh sản phẩm để dễ chế tạo, ít lỗi và rẻ hơn.",en:"Design for manufacturing, adapting a part so it is easier and cheaper to make."},{term:"GD&T",vi:"Hệ thống ký hiệu dung sai hình học và vị trí mô tả yêu cầu chức năng của chi tiết.",en:"Geometric dimensioning and tolerancing describing a part's functional requirements."}],quiz:[{q:{vi:"Khuôn 2 lòng, mỗi lòng 50 cm2, kênh dẫn 20 cm2, áp suất 500 kgf/cm2, hệ số an toàn 1.2. Lực kẹp yêu cầu là bao nhiêu?",en:"A 2-cavity mold, 50 cm2 per cavity, 20 cm2 runners, 500 kgf/cm2 pressure, safety factor 1.2. What clamp force is required?"},options:{vi:["60 tf","50 tf","72 tf","36 tf"],en:["60 tf","50 tf","72 tf","36 tf"]},answer:2,explain:{vi:"Lực kẹp = (2 x 50 + 20) x 500 x 1.2 / 1000 = 72 tấn lực.",en:"Clamp force = (2 x 50 + 20) x 500 x 1.2 / 1000 = 72 tf."}},{q:{vi:"Lực kẹp máy ép thấp hơn lực mở khuôn do áp suất phun gây ra sẽ dẫn tới lỗi gì?",en:"What defect results when press clamp force is below the mold-opening force from injection pressure?"},options:{vi:["Bavia ở mặt phân khuôn","Vết lõm do co ngót","Cháy khí đầu dòng","Sản phẩm thiếu nhựa do nguội sớm"],en:["Flash at the parting line","Sink marks from shrinkage","Burn marks at flow front","Short shot from early freezing"]},answer:0,explain:{vi:"Khuôn bị đẩy hé mở, nhựa tràn qua mặt phân khuôn tạo bavia.",en:"The mold is pushed slightly open and plastic escapes through the parting line as flash."}},{q:{vi:"Kinh doanh bảo dùng file CAD của khách cũ cho khách mới. Bạn làm gì?",en:"Sales asks you to reuse an old client's CAD file for a new client. What do you do?"},options:{vi:["Làm theo nhưng đổi logo","Gửi file cho khách mới tự sửa","Dùng một nửa dữ liệu cũ","Từ chối và đề xuất thiết kế độc lập từ yêu cầu của khách mới"],en:["Comply but change the logo","Send the file to the new client","Use half of the old data","Refuse and propose an independent design from the new client's needs"]},answer:3,explain:{vi:"Dữ liệu thiết kế thuộc khách hàng cũ theo hợp đồng bảo mật; dùng lại là vi phạm.",en:"The design data belongs to the old client under the NDA; reusing it is a breach."}},{q:{vi:"Kích thước lòng khuôn cần lớn hơn kích thước sản phẩm chủ yếu vì lý do nào?",en:"Why must cavity dimensions be larger than part dimensions?"},options:{vi:["Để dễ đánh bóng","Để bù co ngót của nhựa khi nguội","Để tăng lực kẹp","Để giảm thời gian chu kỳ"],en:["For easier polishing","To compensate for plastic shrinkage on cooling","To raise clamp force","To shorten cycle time"]},answer:1,explain:{vi:"Nhựa co khi nguội, nên lòng khuôn được phóng to theo hệ số co ngót của vật liệu.",en:"Plastic shrinks as it cools, so the cavity is scaled up by the material's shrinkage factor."}}]}},"KK-583":{scenario:{company:"Lạc Hồng Silicon Labs",supervisor:{name:"Phan Thị Thu Hà",role:{vi:"Trưởng nhóm Kiểm chứng & Định thời",en:"Verification & Timing Lead"}},ref_code:"STA-0915",title:{vi:"Đúng corner. Đúng đồng hồ thật. Không giấu vi phạm hold.",en:"Right corner. Real clocks. Never hide a hold violation."},brief:{vi:"Khối dsp_core đã qua tổng hợp cây đồng hồ (post-CTS). Báo cáo ký duyệt định thời nháp STA-0915 kết luận hold đạt, slack +97 ps. Đường ff_a/Q tới ff_b/D tại corner hold: trễ đồng hồ phát 118 ps, clk-to-q 81 ps, trễ tổ hợp 44 ps, trễ đồng hồ thu 296 ps, thời gian hold thư viện 28 ps. Đối chiếu với danh sách corner ký duyệt, sửa corner phân tích hold và slack hold (ps), rồi lập báo cáo có căn cứ.",en:"Block dsp_core is post clock tree synthesis (post-CTS). Draft timing sign-off report STA-0915 claims hold is met with +97 ps slack. Path ff_a/Q to ff_b/D at the hold corner: launch clock latency 118 ps, clk-to-q 81 ps, combinational delay 44 ps, capture clock latency 296 ps, library hold time 28 ps. Check it against the sign-off corner list, correct the hold analysis corner and the hold slack (ps), then write an evidence-based report."},reference_title:{vi:"Kế hoạch ký duyệt định thời đã duyệt · STA-0915",en:"Approved timing sign-off plan · STA-0915"},fields:[{id:"HOLD_CORNER",label:{vi:"Corner phân tích hold",en:"Hold analysis corner"},initial:"SS-0P90V-125C",expected:"FF-1P10V-M40C",choices:["SS-0P90V-125C","TT-1P00V-25C","FF-1P10V-M40C"],reference:"Bảng corner ký duyệt",hint:{vi:"Hold nguy hiểm nhất khi đường dữ liệu chạy nhanh nhất; corner chậm chỉ dùng cho setup.",en:"Hold is worst when the data path is fastest; the slow corner is for setup only."}},{id:"HOLD_PS",label:{vi:"Slack hold của đường ff_a tới ff_b (ps)",en:"Hold slack of path ff_a to ff_b (ps)"},initial:"97",expected:"-81",reference:"Báo cáo đường định thời post-CTS",ref_value:{vi:"Đồng hồ phát 118; clk-to-q 81; tổ hợp 44; đồng hồ thu 296; hold 28 (ps)",en:"Launch clock 118; clk-to-q 81; logic 44; capture clock 296; hold 28 (ps)"},hint:{vi:"Sau CTS phải dùng đồng hồ lan truyền thật; độ lệch đồng hồ giữa phát và thu làm hold xấu đi.",en:"Post-CTS you must use propagated clocks; skew between launch and capture worsens hold."}}],sop32:{vi:"Slack hold = (trễ đồng hồ phát + clk-to-q + trễ tổ hợp) - (trễ đồng hồ thu + thời gian hold). Sau CTS phân tích với đồng hồ lan truyền, hold ký tại corner nhanh trong bảng corner.",en:"Hold slack = (launch clock latency + clk-to-q + logic delay) - (capture clock latency + hold time). Post-CTS analysis uses propagated clocks and hold is signed off at the fast corner in the corner table."},context:{label:"STA SIGN-OFF / STA-0915",metrics:[{label:{vi:"Giai đoạn",en:"Stage"},value:"post-CTS"},{label:{vi:"Độ lệch đồng hồ",en:"Clock skew"},value:"178 ps"},{label:{vi:"Slack hold trên bản nháp",en:"Draft hold slack"},value:"+97 ps"}]},terminal:{system:"sta-shell",settable:["HOLD_CORNER","HOLD_PS"],commands:[{cmd:"status",out:{vi:"Khối dsp_core, giai đoạn post-CTS; báo cáo nháp dùng HOLD_CORNER=SS-0P90V-125C, chế độ đồng hồ lý tưởng, HOLD_PS=97",en:"Block dsp_core, post-CTS stage; draft report uses HOLD_CORNER=SS-0P90V-125C, ideal clock mode, HOLD_PS=97"}},{cmd:"cat signoff_corners.txt",out:{vi:"Setup: SS-0P90V-125C; hold: FF-1P10V-M40C; TT-1P00V-25C chỉ dùng tham khảo công suất",en:"Setup: SS-0P90V-125C; hold: FF-1P10V-M40C; TT-1P00V-25C for power reference only"}},{cmd:"report_timing -hold",out:{vi:"Corner FF-1P10V-M40C, đồng hồ lan truyền: đồng hồ phát 118 ps, clk-to-q 81 ps, tổ hợp 44 ps, đồng hồ thu 296 ps, hold 28 ps",en:"Corner FF-1P10V-M40C, propagated clocks: launch clock 118 ps, clk-to-q 81 ps, logic 44 ps, capture clock 296 ps, hold 28 ps"}},{cmd:"report_clock_skew",out:{vi:"Độ lệch cục bộ ff_a tới ff_b: đồng hồ thu trễ hơn đồng hồ phát 178 ps do nhánh cây đồng hồ dài",en:"Local skew ff_a to ff_b: capture clock arrives 178 ps later than launch due to a long clock tree branch"}},{cmd:"cat draft_report.txt",out:{vi:"Bản nháp: set_propagated_clock chưa bật, hold phân tích ở SS; kết luận hold đạt, sẵn sàng tape-out",en:"Draft: set_propagated_clock not enabled, hold analysed at SS; concludes hold met, ready for tape-out"}}]},crisis:{vi:"Quản lý dự án nhắn lúc 22 giờ: “Tối nay phải tape-out. Thêm set_false_path cho đường ff_a tới ff_b để báo cáo sạch đi, vài chục ps chắc silicon vẫn chạy được.”",en:"The project manager messages at 10 pm: “We must tape out tonight. Add a set_false_path on ff_a to ff_b so the report is clean, a few tens of ps will surely work in silicon.”"},options:{safe:{vi:"Từ chối che vi phạm bằng false path; báo trưởng nhóm, sửa bằng ECO chèn đệm trễ trên đường dữ liệu, chạy lại STA đủ corner rồi mới ký tape-out.",en:"Refuse to mask the violation with a false path; inform the lead, fix it with an ECO inserting delay buffers on the data path, rerun STA on all corners before signing tape-out."},shortcut:{vi:"Thêm set_false_path cho kịp tape-out, ghi chú sẽ kiểm tra trên silicon.",en:"Add the set_false_path to make tape-out and note to check on silicon."},wait:{vi:"Không trả lời và để quản lý dự án tự quyết định tape-out.",en:"Do not reply and let the project manager decide on tape-out."}},questions:{vi:["Vì sao slack hold thật là -81 ps chứ không phải +97 ps? Hai sai lầm nào trong báo cáo nháp tạo ra con số lạc quan?","Vì sao vi phạm hold không thể sửa bằng giảm tần số, và vì sao che bằng false path là rủi ro nghiêm trọng?"],en:["Why is the true hold slack -81 ps rather than +97 ps? Which two draft mistakes produced the optimistic number?","Why can a hold violation not be fixed by lowering the frequency, and why is masking it with a false path a serious risk?"]},hints:{vi:["Đặt báo cáo nháp cạnh bảng corner ký duyệt và kiểm tra chế độ đồng hồ đang dùng.","Áp dụng SOP mục 3.2: cộng đủ trễ đồng hồ phát vào thời điểm dữ liệu tới, trễ đồng hồ thu vào thời điểm yêu cầu.","Đọc lại SOP mục 4.2: ràng buộc ngoại lệ chỉ hợp lệ khi đường thật sự không chức năng và được duyệt."],en:["Place the draft report next to the sign-off corner table and check the clock mode used.","Apply SOP 3.2: add launch clock latency to data arrival and capture clock latency to the required time.","Re-read SOP 4.2: timing exceptions are valid only for truly non-functional paths and need review."]}},learning:{summary:{vi:"Kỹ sư Thiết kế Vi mạch Bán dẫn và Kiểm chứng VLSI viết RTL, xây dựng môi trường kiểm chứng, phân tích định thời và chất lượng thiết kế để chip hoạt động đúng ngay lần tape-out đầu tiên. Một lỗi lọt qua có thể tốn hàng triệu đô la và nhiều tháng làm lại mặt nạ. Công việc đòi hỏi tư duy logic chặt, hiểu kiến trúc số, phương pháp kiểm chứng hiện đại và tính trung thực tuyệt đối với kết quả ký duyệt.",en:"An IC Design and VLSI Verification Engineer writes RTL, builds verification environments and analyses timing and design quality so the chip works on first tape-out. One escaped bug can cost millions of dollars and months of mask re-spins. The role requires rigorous logic, digital architecture knowledge, modern verification methods and absolute honesty about sign-off results."},responsibilities:{vi:["Viết RTL bằng SystemVerilog, kiểm tra lint và miền đồng hồ chéo (CDC).","Xây dựng testbench UVM, kế hoạch kiểm chứng và mô hình độ phủ chức năng.","Phân tích định thời tĩnh đa corner, đa chế độ và đề xuất ECO sửa vi phạm.","Kiểm tra tương đương logic (LEC) sau tổng hợp, sau ECO và kiểm chứng hình thức các thuộc tính quan trọng.","Theo dõi đóng độ phủ, phân loại lỗi và báo cáo sẵn sàng tape-out."],en:["Write SystemVerilog RTL and run lint and clock domain crossing (CDC) checks.","Build UVM testbenches, verification plans and functional coverage models.","Run multi-corner multi-mode static timing analysis and propose ECOs for violations.","Run logical equivalence checks (LEC) after synthesis and ECOs and formally verify key properties.","Track coverage closure, triage bugs and report tape-out readiness."]},competencies:[{name:{vi:"Thiết kế RTL",en:"RTL design"},desc:{vi:"Viết RTL tổng hợp được, rõ ràng, đúng đồng bộ và tối ưu diện tích, công suất.",en:"Write synthesisable, clear, correctly synchronised RTL optimised for area and power."}},{name:{vi:"Kiểm chứng UVM",en:"UVM verification"},desc:{vi:"Thiết kế agent, scoreboard, ràng buộc ngẫu nhiên và đóng độ phủ chức năng.",en:"Design agents, scoreboards and constrained-random stimulus and close functional coverage."}},{name:{vi:"Phân tích định thời",en:"Timing analysis"},desc:{vi:"Hiểu setup, hold, độ lệch đồng hồ, OCV, CPPR và chọn đúng corner ký duyệt.",en:"Understand setup, hold, clock skew, OCV and CPPR and pick the right sign-off corners."}},{name:{vi:"Kiểm chứng hình thức",en:"Formal verification"},desc:{vi:"Viết assertion SVA, chứng minh thuộc tính và kiểm tra tương đương logic.",en:"Write SVA assertions, prove properties and run equivalence checks."}},{name:{vi:"Trung thực khi ký duyệt",en:"Sign-off integrity"},desc:{vi:"Báo cáo đúng vi phạm, chỉ miễn trừ qua quy trình xem xét và lưu căn cứ.",en:"Report violations truthfully and waive only through review with documented evidence."}}],knowledge:{vi:["IEEE 1800 về ngôn ngữ SystemVerilog và IEEE 1800.2 về phương pháp UVM.","IEEE 1801 về định dạng ý đồ công suất thống nhất (UPF).","Lý thuyết định thời tĩnh: setup, hold, độ lệch đồng hồ, OCV, CPPR, phân tích đa corner.","Đồng bộ hóa miền đồng hồ chéo, metastability và mạch đồng bộ hai tầng.","Luồng thiết kế số từ RTL, tổng hợp, đặt cell, cây đồng hồ, đi dây đến ký duyệt và tape-out."],en:["IEEE 1800 on SystemVerilog and IEEE 1800.2 on the UVM methodology.","IEEE 1801 on the Unified Power Format (UPF) for power intent.","Static timing theory: setup, hold, clock skew, OCV, CPPR and multi-corner analysis.","Clock domain crossing synchronisation, metastability and two-flop synchronisers.","Digital flow from RTL, synthesis, placement, clock tree and routing to sign-off and tape-out."]},tools:["Trình mô phỏng SystemVerilog/UVM","Công cụ phân tích định thời tĩnh","Công cụ kiểm chứng hình thức","Công cụ kiểm tra tương đương logic","Ngôn ngữ kịch bản Tcl và Python"],kpis:{vi:["Tỷ lệ độ phủ chức năng và độ phủ mã đạt mục tiêu trước tape-out.","Số lỗi phát hiện sau tape-out (mục tiêu bằng 0).","Tổng slack âm (TNS) và số đường vi phạm tại các corner ký duyệt.","Thời gian từ lúc phát hiện đến lúc đóng lỗi."],en:["Functional and code coverage reaching targets before tape-out.","Bugs found after tape-out (target zero).","Total negative slack (TNS) and violating paths at sign-off corners.","Time from bug discovery to closure."]},day:[{time:"08:30",vi:"Xem kết quả hồi quy đêm qua, phân loại các test lỗi theo nguyên nhân.",en:"Review last night's regression and triage failing tests by cause."},{time:"10:00",vi:"Viết thêm sequence và điểm phủ cho chế độ hoạt động chưa được kiểm chứng.",en:"Write new sequences and cover points for an unverified operating mode."},{time:"13:30",vi:"Chạy STA đa corner trên netlist post-CTS, lọc các đường vi phạm hold.",en:"Run multi-corner STA on the post-CTS netlist and filter hold violations."},{time:"15:30",vi:"Họp với nhóm thiết kế vật lý thống nhất ECO chèn đệm trễ.",en:"Meet the physical design team to agree a delay buffer ECO."},{time:"17:30",vi:"Cập nhật bảng theo dõi sẵn sàng tape-out và khởi động hồi quy đêm.",en:"Update the tape-out readiness tracker and launch the nightly regression."}],mistakes:{vi:["Phân tích hold ở corner chậm hoặc vẫn dùng đồng hồ lý tưởng sau CTS.","Che vi phạm thật bằng false path hoặc multicycle path không có căn cứ chức năng.","Đóng độ phủ bằng cách loại trừ điểm phủ khó thay vì viết thêm kiểm chứng."],en:["Analysing hold at the slow corner or keeping ideal clocks after CTS.","Masking real violations with false or multicycle paths without functional justification.","Closing coverage by excluding hard cover points instead of writing more tests."]},career:[{vi:"Kỹ sư kiểm chứng vi mạch",en:"Verification engineer"},{vi:"Kỹ sư thiết kế và kiểm chứng cấp cao",en:"Senior design and verification engineer"},{vi:"Trưởng nhóm kiểm chứng hoặc ký duyệt định thời",en:"Verification or timing sign-off lead"},{vi:"Kiến trúc sư hoặc giám đốc kỹ thuật vi mạch",en:"Chip architect or silicon engineering director"}],glossary:[{term:"Hold slack",vi:"Phần dư giữa thời điểm dữ liệu đổi và thời điểm phải giữ ổn định sau sườn đồng hồ; âm là vi phạm.",en:"Margin between data change and the required stable time after the clock edge; negative means violation."},{term:"CTS",vi:"Tổng hợp cây đồng hồ, chèn bộ đệm để phân phối đồng hồ với độ lệch kiểm soát được.",en:"Clock tree synthesis, inserting buffers to distribute the clock with controlled skew."},{term:"Corner",vi:"Tổ hợp điều kiện quy trình, điện áp, nhiệt độ dùng để phân tích trường hợp xấu nhất.",en:"A process, voltage and temperature combination used for worst-case analysis."},{term:"ECO",vi:"Thay đổi kỹ thuật muộn trên netlist hoặc layout để sửa lỗi mà không làm lại toàn bộ luồng.",en:"Late engineering change on the netlist or layout to fix issues without rerunning the full flow."},{term:"False path",vi:"Ràng buộc khai báo một đường không bao giờ hoạt động về chức năng nên không cần kiểm tra định thời.",en:"A constraint declaring a path functionally inactive so it is excluded from timing checks."}],quiz:[{q:{vi:"Đồng hồ phát 100 ps, clk-to-q 70 ps, tổ hợp 40 ps, đồng hồ thu 250 ps, hold 20 ps. Slack hold bằng bao nhiêu?",en:"Launch clock 100 ps, clk-to-q 70 ps, logic 40 ps, capture clock 250 ps, hold 20 ps. What is the hold slack?"},options:{vi:["+90 ps","-40 ps","-60 ps","+40 ps"],en:["+90 ps","-40 ps","-60 ps","+40 ps"]},answer:2,explain:{vi:"Slack = (100 + 70 + 40) - (250 + 20) = 210 - 270 = -60 ps; bỏ qua đồng hồ sẽ ra +90 ps sai.",en:"Slack = (100 + 70 + 40) - (250 + 20) = 210 - 270 = -60 ps; ignoring clocks gives the wrong +90 ps."}},{q:{vi:"Vi phạm hold thường được ký duyệt tại corner nào?",en:"At which corner is hold usually signed off?"},options:{vi:["Corner nhanh, điện áp cao","Corner chậm, nhiệt độ cao","Corner điển hình","Bất kỳ corner nào"],en:["Fast corner, high voltage","Slow corner, high temperature","Typical corner","Any corner"]},answer:0,explain:{vi:"Hold xấu nhất khi đường dữ liệu nhanh nhất, nên ký tại corner nhanh trong bảng corner.",en:"Hold is worst when the data path is fastest, so it is signed off at the fast corner."}},{q:{vi:"Vì sao giảm tần số đồng hồ không sửa được vi phạm hold?",en:"Why does lowering the clock frequency not fix a hold violation?"},options:{vi:["Vì hold phụ thuộc điện áp","Vì hold chỉ có ở bộ nhớ","Vì giảm tần số làm tăng skew","Vì kiểm tra hold không phụ thuộc chu kỳ đồng hồ"],en:["Because hold depends on voltage","Because hold exists only in memories","Because lower frequency raises skew","Because the hold check does not depend on the clock period"]},answer:3,explain:{vi:"Hold so sánh trên cùng một sườn đồng hồ nên chu kỳ không xuất hiện trong phép tính.",en:"Hold compares against the same clock edge, so the period does not appear in the calculation."}},{q:{vi:"Quản lý yêu cầu thêm false path để báo cáo sạch trước tape-out. Bạn làm gì?",en:"A manager asks you to add a false path to clean the report before tape-out. What do you do?"},options:{vi:["Thêm vì tiến độ quan trọng hơn","Từ chối, báo trưởng nhóm và sửa bằng ECO trước khi ký","Thêm và ghi chú trong email riêng","Xóa đường đó khỏi báo cáo"],en:["Add it, schedule matters more","Refuse, inform the lead and fix with an ECO before sign-off","Add it and note it in a private email","Delete the path from the report"]},answer:1,explain:{vi:"Che vi phạm thật có thể khiến chip lỗi trên silicon; chỉ sửa thật hoặc miễn trừ qua xem xét chính thức.",en:"Masking a real violation can break the silicon; fix it or waive only through formal review."}}]}},"KK-584":{scenario:{company:"Đông Hải Steel Rolling",supervisor:{name:"Hoàng Văn Thịnh",role:{vi:"Trưởng phòng Cơ điện",en:"Electrical Engineering Manager"}},ref_code:"PFC-2209",title:{vi:"Bù đúng công suất. Chống cộng hưởng. Không đóng điện vội.",en:"Right compensation. No resonance. No rushed energising."},brief:{vi:"Thanh cái MSB-2 (400 V) cấp cho dây chuyền cán có nhiều biến tần 6 xung. Công suất tác dụng lớn nhất 1500 kW, hệ số công suất 0.80, mục tiêu thiết kế 0.95. Hồ sơ thiết kế tụ bù nháp PFC-2209 chọn sai kiểu tủ bù và dung lượng. Đối chiếu với kết quả đo sóng hài và cơ sở thiết kế đã duyệt, sửa kiểu tủ bù và dung lượng bù yêu cầu (kvar, làm tròn số nguyên), rồi lập báo cáo có căn cứ.",en:"Busbar MSB-2 (400 V) feeds a rolling line with many 6-pulse drives. Peak active power is 1500 kW at power factor 0.80, design target 0.95. Draft capacitor bank design PFC-2209 picks the wrong bank type and rating. Check it against the approved harmonic survey and design basis, correct the bank type and the required compensation (kvar, nearest integer), then write an evidence-based report."},reference_title:{vi:"Cơ sở thiết kế bù công suất phản kháng đã duyệt · PFC-2209",en:"Approved reactive power compensation design basis · PFC-2209"},fields:[{id:"PFC_TYPE",label:{vi:"Kiểu tủ tụ bù",en:"Capacitor bank type"},initial:"STANDARD",expected:"DETUNED-7%",choices:["STANDARD","DETUNED-7%","DETUNED-14%"],reference:"Biên bản đo sóng hài MSB-2",hint:{vi:"Lưới nhiều hài bậc 5, 7 dễ cộng hưởng với tụ thường; chọn mức kháng theo bậc hài thấp nhất đáng kể.",en:"A grid rich in 5th and 7th harmonics can resonate with plain capacitors; pick the reactor tuning by the lowest significant harmonic."}},{id:"QC_KVAR",label:{vi:"Dung lượng bù yêu cầu (kvar)",en:"Required compensation (kvar)"},initial:"790",expected:"632",reference:"Cơ sở thiết kế MSB-2",ref_value:{vi:"P lớn nhất 1500 kW; cos φ1 0.80 (tan φ1 = 0.7500); cos φ2 mục tiêu 0.95 (tan φ2 = 0.3287)",en:"Peak P 1500 kW; PF1 0.80 (tan φ1 = 0.7500); target PF2 0.95 (tan φ2 = 0.3287)"},hint:{vi:"Công thức bù dùng công suất tác dụng kW, không dùng công suất biểu kiến kVA.",en:"The compensation formula uses active power in kW, not apparent power in kVA."}}],sop32:{vi:"Qc = P x (tan φ1 - tan φ2), với P là công suất tác dụng (kW), φ1, φ2 ứng với hệ số công suất hiện tại và mục tiêu; làm tròn số nguyên kvar. Tủ kháng 7% (khoảng 189 Hz) khi hài bậc 5 trội và không có hài bậc 3 đáng kể.",en:"Qc = P x (tan φ1 - tan φ2), with P the active power (kW) and φ1, φ2 for present and target power factor; round to whole kvar. Use a 7% detuned bank (about 189 Hz) when the 5th harmonic dominates and the 3rd is insignificant."},context:{label:"POWER QUALITY / PFC-2209",metrics:[{label:{vi:"Công suất tác dụng",en:"Active power"},value:"1500 kW"},{label:{vi:"Hệ số công suất",en:"Power factor"},value:"0.80 / 0.95"},{label:{vi:"Méo điện áp THDv",en:"Voltage THDv"},value:"6.8%"}]},terminal:{system:"pq-analyzer",settable:["PFC_TYPE","QC_KVAR"],commands:[{cmd:"status",out:{vi:"MSB-2 400 V: P = 1500 kW, S = 1875 kVA, cos φ = 0.80; hồ sơ nháp PFC_TYPE=STANDARD, QC_KVAR=790",en:"MSB-2 400 V: P = 1500 kW, S = 1875 kVA, power factor 0.80; draft PFC_TYPE=STANDARD, QC_KVAR=790"}},{cmd:"harmonics msb2",out:{vi:"THDv 6.8%; H5 5.1%, H7 3.4%, H11 1.6%, H3 0.4%; nguồn hài chủ yếu là biến tần chỉnh lưu 6 xung",en:"THDv 6.8%; H5 5.1%, H7 3.4%, H11 1.6%, H3 0.4%; harmonics mainly from 6-pulse rectifier drives"}},{cmd:"cat design_basis.txt",out:{vi:"Mục tiêu cos φ 0.95 tại tải lớn nhất 1500 kW; ngưỡng hợp đồng mua bán điện mô phỏng 0.90",en:"Target power factor 0.95 at peak load 1500 kW; training power purchase contract threshold 0.90"}},{cmd:"cat bank_catalog.txt",out:{vi:"Tủ thường: không kháng; tủ kháng 7%: cộng hưởng khoảng 189 Hz, dùng khi hài bậc 5 trội; tủ kháng 14%: khoảng 134 Hz, dùng khi có hài bậc 3 đáng kể",en:"Standard bank: no reactor; 7% detuned: resonance about 189 Hz, for dominant 5th harmonic; 14% detuned: about 134 Hz, for significant 3rd harmonic"}},{cmd:"cat draft_pfc.txt",out:{vi:"Bản nháp: Qc = 1875 x (0.7500 - 0.3287), chọn tủ thường không kháng để tiết kiệm chi phí",en:"Draft: Qc = 1875 x (0.7500 - 0.3287), standard unreactored bank chosen to save cost"}}]},crisis:{vi:"Nhà thầu lắp đặt nhắn: “Tủ bù lắp xong rồi, đóng điện thử luôn tối nay cho kịp nghiệm thu. Biên bản thí nghiệm và phiếu thao tác bọn em ký bổ sung sau.”",en:"The installation contractor messages: “The bank is installed, let us energise it tonight to make acceptance. We will sign the test reports and switching order afterwards.”"},options:{safe:{vi:"Từ chối đóng điện khi chưa có biên bản thí nghiệm đạt, phiếu thao tác và người giám sát; báo trưởng phòng cơ điện, sửa thiết kế sang tủ kháng 7% trước nghiệm thu.",en:"Refuse to energise without passed test reports, a switching order and a supervisor; inform the electrical manager and revise the design to a 7% detuned bank before acceptance."},shortcut:{vi:"Cho đóng điện thử tối nay, giấy tờ thí nghiệm hoàn thiện sau.",en:"Allow energising tonight and complete the test paperwork later."},wait:{vi:"Không trả lời và để nhà thầu tự quyết định thời điểm đóng điện.",en:"Do not reply and let the contractor decide when to energise."}},questions:{vi:["Vì sao dung lượng bù đúng là 632 kvar và cần tủ kháng 7%? Nếu dùng tụ thường trên lưới này điều gì có thể xảy ra?","Những điều kiện nào phải có trước khi đóng điện một tủ tụ bù mới, và bạn xử lý áp lực của nhà thầu ra sao?"],en:["Why is the correct compensation 632 kvar with a 7% detuned bank? What could happen with plain capacitors on this grid?","Which conditions must be met before energising a new capacitor bank, and how do you handle the contractor's pressure?"]},hints:{vi:["Đặt hồ sơ nháp cạnh biên bản đo sóng hài và đọc bậc hài nào trội.","Áp dụng SOP mục 3.2: tính tan φ từ cos φ và nhân với công suất tác dụng, không phải công suất biểu kiến.","Đọc lại SOP mục 4.2: không đóng điện khi chưa có kết quả thí nghiệm và phiếu thao tác được duyệt."],en:["Place the draft next to the harmonic survey and read which harmonic dominates.","Apply SOP 3.2: derive tan φ from the power factor and multiply by active power, not apparent power.","Re-read SOP 4.2: never energise before test results and an approved switching order exist."]}},learning:{summary:{vi:"Kỹ sư Hệ thống Điện Công nghiệp và Trạm biến áp thiết kế, vận hành và bảo vệ hệ thống cung cấp điện của nhà máy: trạm biến áp trung thế, tủ phân phối hạ thế, bảo vệ rơ le, nối đất, bù công suất phản kháng và chất lượng điện năng. Mục tiêu là cấp điện liên tục, an toàn cho người và thiết bị với chi phí năng lượng hợp lý. Công việc đòi hỏi vững tính toán ngắn mạch, phối hợp bảo vệ và kỷ luật an toàn điện tuyệt đối.",en:"An Electrical Power Systems Engineer designs, operates and protects a plant's power supply: medium-voltage substations, low-voltage switchboards, relay protection, earthing, reactive power compensation and power quality. The goal is continuous, safe power for people and equipment at a reasonable energy cost. The role requires solid short-circuit and protection coordination skills and absolute electrical safety discipline."},responsibilities:{vi:["Tính toán phụ tải, ngắn mạch và chọn máy biến áp, cáp, thiết bị đóng cắt.","Lập và kiểm tra trị số chỉnh định rơ le, phối hợp bảo vệ giữa các cấp.","Đo và cải thiện chất lượng điện năng: hệ số công suất, sóng hài, sụt áp.","Lập phiếu thao tác, giám sát thí nghiệm, nghiệm thu và đóng điện thiết bị mới.","Lập kế hoạch bảo trì trạm biến áp, đo nhiệt hồng ngoại và phân tích sự cố mất điện."],en:["Calculate loads and short circuits and size transformers, cables and switchgear.","Prepare and check relay settings and coordinate protection between levels.","Measure and improve power quality: power factor, harmonics and voltage drop.","Issue switching orders and supervise testing, acceptance and energising of new equipment.","Plan substation maintenance, run infrared surveys and analyse outages."]},competencies:[{name:{vi:"Tính toán hệ thống điện",en:"Power system calculation"},desc:{vi:"Tính dòng ngắn mạch, sụt áp, trào lưu công suất và chọn thiết bị đúng khả năng cắt.",en:"Compute short-circuit currents, voltage drop and load flow and size equipment by breaking capacity."}},{name:{vi:"Bảo vệ rơ le",en:"Protection relaying"},desc:{vi:"Chỉnh định quá dòng, chạm đất, so lệch và lập đồ thị phối hợp chọn lọc.",en:"Set overcurrent, earth fault and differential protection and build selectivity curves."}},{name:{vi:"Chất lượng điện năng",en:"Power quality"},desc:{vi:"Đo, phân tích sóng hài, thiết kế bù có kháng và lọc sóng hài.",en:"Measure and analyse harmonics and design detuned compensation and filters."}},{name:{vi:"Vận hành và thao tác",en:"Operation and switching"},desc:{vi:"Lập phiếu thao tác, cô lập, nối đất an toàn và giám sát đóng điện.",en:"Write switching orders, isolate, earth safely and supervise energising."}},{name:{vi:"Kỷ luật an toàn điện",en:"Electrical safety discipline"},desc:{vi:"Không đóng điện khi thiếu thí nghiệm, phiếu thao tác, và dám dừng việc khi nguy hiểm.",en:"Never energise without tests and switching orders, and stop work when it is dangerous."}}],knowledge:{vi:["IEC 60909 về tính toán dòng ngắn mạch trong hệ thống điện xoay chiều ba pha.","IEC 60255 về rơ le bảo vệ, gồm các đặc tính thời gian phụ thuộc.","IEC 61850 về truyền thông trong trạm biến áp tự động hóa.","IEEE 519 về giới hạn sóng hài trong hệ thống điện.","IEC 61439 về tủ điện hạ thế và quy chuẩn kỹ thuật quốc gia hiện hành về kỹ thuật điện, an toàn điện."],en:["IEC 60909 on short-circuit current calculation in three-phase AC systems.","IEC 60255 on protection relays, including inverse-time characteristics.","IEC 61850 on communication in substation automation.","IEEE 519 on harmonic limits in electric power systems.","IEC 61439 on low-voltage switchgear assemblies and current national technical regulations on electrical engineering and safety."]},tools:["Phần mềm tính toán hệ thống điện","Máy phân tích chất lượng điện năng","Bộ thí nghiệm rơ le nhất thứ, nhị thứ","Camera nhiệt hồng ngoại","Máy đo điện trở nối đất"],kpis:{vi:["Số giờ mất điện ngoài kế hoạch trên năm.","Hệ số công suất trung bình tháng so với mục tiêu.","Tỷ lệ sự cố được rơ le cắt chọn lọc đúng cấp.","Số vi phạm quy trình thao tác (mục tiêu bằng 0)."],en:["Unplanned outage hours per year.","Monthly average power factor versus target.","Share of faults cleared selectively at the right level.","Switching procedure violations (target zero)."]},day:[{time:"07:30",vi:"Đọc nhật ký vận hành trạm, kiểm tra các lần rơ le tác động trong đêm.",en:"Read the substation log and check overnight relay operations."},{time:"09:00",vi:"Đo sóng hài và hệ số công suất tại các thanh cái cấp cho biến tần.",en:"Measure harmonics and power factor on busbars feeding drives."},{time:"11:00",vi:"Kiểm tra trị số chỉnh định rơ le xuất tuyến mới và đồ thị phối hợp.",en:"Check relay settings for a new feeder and the coordination curves."},{time:"14:00",vi:"Giám sát thí nghiệm tủ tụ bù, ký biên bản khi các hạng mục đạt.",en:"Supervise capacitor bank tests and sign reports when all items pass."},{time:"16:30",vi:"Lập phiếu thao tác cho đợt cắt điện bảo trì cuối tuần và họp an toàn.",en:"Write switching orders for the weekend maintenance outage and hold a safety briefing."}],mistakes:{vi:["Tính dung lượng bù theo kVA thay vì kW, dẫn tới bù thừa và quá áp khi non tải.","Lắp tụ bù thường trên lưới nhiều sóng hài, gây cộng hưởng, nổ tụ, nhảy áp tô mát.","Đóng điện thiết bị mới khi chưa có biên bản thí nghiệm và phiếu thao tác."],en:["Sizing compensation on kVA instead of kW, causing overcompensation and light-load overvoltage.","Installing plain capacitors on a harmonic-rich grid, causing resonance, capacitor failures and breaker trips.","Energising new equipment without test reports and a switching order."]},career:[{vi:"Kỹ thuật viên vận hành trạm",en:"Substation operator"},{vi:"Kỹ sư hệ thống điện nhà máy",en:"Plant power systems engineer"},{vi:"Kỹ sư trưởng bảo vệ và chất lượng điện",en:"Lead protection and power quality engineer"},{vi:"Trưởng phòng năng lượng và cơ điện",en:"Head of energy and electrical engineering"}],glossary:[{term:"Detuned reactor",vi:"Cuộn kháng nối tiếp với tụ để dời tần số cộng hưởng xuống dưới bậc hài thấp nhất đáng kể.",en:"Series reactor with a capacitor that moves resonance below the lowest significant harmonic."},{term:"THD",vi:"Tổng độ méo sóng hài, tỷ lệ giữa tổng các thành phần hài và thành phần cơ bản.",en:"Total harmonic distortion, the ratio of combined harmonic content to the fundamental."},{term:"Power factor",vi:"Hệ số công suất, tỷ số giữa công suất tác dụng và công suất biểu kiến.",en:"The ratio of active power to apparent power."},{term:"Selectivity",vi:"Tính chọn lọc, chỉ thiết bị bảo vệ gần điểm sự cố nhất được cắt.",en:"Only the protective device closest to the fault trips."},{term:"Switching order",vi:"Phiếu thao tác, trình tự đóng cắt được duyệt trước để vận hành an toàn.",en:"Pre-approved switching sequence for safe operation."}],quiz:[{q:{vi:"P = 1000 kW, cos φ từ 0.80 (tan 0.75) lên mức có tan φ = 0.33. Cần bù bao nhiêu kvar?",en:"P = 1000 kW, power factor from 0.80 (tan 0.75) to a level with tan φ = 0.33. How much kvar is needed?"},options:{vi:["420 kvar","525 kvar","750 kvar","330 kvar"],en:["420 kvar","525 kvar","750 kvar","330 kvar"]},answer:0,explain:{vi:"Qc = 1000 x (0.75 - 0.33) = 420 kvar; tính theo kVA 1250 sẽ ra sai 525 kvar.",en:"Qc = 1000 x (0.75 - 0.33) = 420 kvar; using 1250 kVA gives the wrong 525 kvar."}},{q:{vi:"Tủ tụ bù kháng 7% trên lưới 50 Hz có tần số cộng hưởng khoảng bao nhiêu?",en:"What is the approximate resonant frequency of a 7% detuned bank on a 50 Hz grid?"},options:{vi:["134 Hz","250 Hz","350 Hz","189 Hz"],en:["134 Hz","250 Hz","350 Hz","189 Hz"]},answer:3,explain:{vi:"f = 50 / căn bậc hai của 0.07, xấp xỉ 189 Hz, dưới hài bậc 5 (250 Hz).",en:"f = 50 / square root of 0.07, about 189 Hz, below the 5th harmonic (250 Hz)."}},{q:{vi:"Nhà thầu muốn đóng điện tủ mới trước, ký biên bản thí nghiệm sau. Bạn làm gì?",en:"A contractor wants to energise a new panel now and sign the test report later. What do you do?"},options:{vi:["Đồng ý vì đã lắp xong","Cho đóng điện nhưng đứng xa","Từ chối đến khi có biên bản đạt, phiếu thao tác và báo trưởng phòng","Để nhà thầu tự chịu trách nhiệm"],en:["Agree since installation is done","Allow it but stand back","Refuse until passed tests and a switching order exist and inform the manager","Let the contractor take responsibility"]},answer:2,explain:{vi:"Thiết bị chưa thí nghiệm có thể hỏng cách điện, gây hồ quang nguy hiểm tính mạng.",en:"Untested equipment may have insulation faults and cause life-threatening arc flash."}},{q:{vi:"Tiêu chuẩn nào hướng dẫn tính toán dòng ngắn mạch trong hệ thống xoay chiều ba pha?",en:"Which standard guides short-circuit calculation in three-phase AC systems?"},options:{vi:["IEC 61850","IEC 60909","IEC 61131-3","IEEE 519"],en:["IEC 61850","IEC 60909","IEC 61131-3","IEEE 519"]},answer:1,explain:{vi:"IEC 60909 là chuẩn quốc tế về tính toán dòng ngắn mạch trong lưới xoay chiều ba pha.",en:"IEC 60909 is the international standard for short-circuit calculation in three-phase AC networks."}}]}},"KK-585":{scenario:{company:"Ánh Dương Smart Assembly",supervisor:{name:"Lý Quốc Bảo",role:{vi:"Trưởng nhóm Robot & Thị giác máy",en:"Robotics & Machine Vision Lead"}},ref_code:"VIS-7304",title:{vi:"Đủ điểm ảnh. Đúng camera. Không tắt vùng an toàn.",en:"Enough pixels. Right camera. Never mute the safety zone."},brief:{vi:"Trạm VIS-7304 trong ô robot gắp vỏ nhôm cần phát hiện vết xước nhỏ nhất 0.2 mm. Trường nhìn ngang 160 mm (đã gồm dung sai vị trí ±5 mm), quy tắc đã duyệt: khuyết tật nhỏ nhất phủ tối thiểu 3 điểm ảnh. Bản thiết kế nháp tính sai số điểm ảnh và chọn camera chưa đạt. Đối chiếu với đặc tả kiểm tra, sửa số điểm ảnh ngang yêu cầu và camera, rồi lập báo cáo có căn cứ.",en:"Station VIS-7304 in an aluminium housing pick-and-place robot cell must detect scratches down to 0.2 mm. The horizontal field of view is 160 mm (including ±5 mm positioning tolerance), and the approved rule says the smallest defect must cover at least 3 pixels. The draft design miscalculates the pixel count and picks an inadequate camera. Check it against the inspection specification, correct the required horizontal pixels and the camera, then write an evidence-based report."},reference_title:{vi:"Đặc tả kiểm tra thị giác đã duyệt · VIS-7304",en:"Approved vision inspection specification · VIS-7304"},fields:[{id:"CAMERA",label:{vi:"Camera được chọn",en:"Selected camera"},initial:"CAM-2MP",expected:"CAM-5MP",choices:["CAM-2MP","CAM-5MP","CAM-12MP"],reference:"Danh mục camera đã thẩm định",hint:{vi:"Chọn camera nhỏ nhất có số điểm ảnh ngang không thấp hơn yêu cầu; quá dư làm tăng chi phí và thời gian xử lý.",en:"Choose the smallest camera whose horizontal pixels meet the requirement; oversizing adds cost and processing time."}},{id:"PX_REQ",label:{vi:"Số điểm ảnh ngang yêu cầu (px)",en:"Required horizontal pixels (px)"},initial:"800",expected:"2400",reference:"Bảng tính độ phân giải không gian",ref_value:{vi:"Trường nhìn ngang 160 mm; khuyết tật nhỏ nhất 0.2 mm; tối thiểu 3 điểm ảnh trên khuyết tật",en:"Horizontal FOV 160 mm; smallest defect 0.2 mm; at least 3 pixels across the defect"},hint:{vi:"Một điểm ảnh cho mỗi khuyết tật là không đủ để phát hiện tin cậy; áp đúng số điểm ảnh tối thiểu.",en:"One pixel per defect is not enough for reliable detection; apply the minimum pixel count."}}],sop32:{vi:"Số điểm ảnh ngang yêu cầu = trường nhìn / (kích thước khuyết tật nhỏ nhất / số điểm ảnh tối thiểu trên khuyết tật); chọn camera nhỏ nhất có số điểm ảnh ngang ≥ yêu cầu.",en:"Required horizontal pixels = field of view / (smallest defect size / minimum pixels per defect); choose the smallest camera with horizontal pixels ≥ the requirement."},context:{label:"VISION CONFIG / VIS-7304",metrics:[{label:{vi:"Trường nhìn ngang",en:"Horizontal FOV"},value:"160 mm"},{label:{vi:"Khuyết tật nhỏ nhất",en:"Smallest defect"},value:"0.2 mm"},{label:{vi:"Tỷ lệ phát hiện thử",en:"Trial detection rate"},value:"71%"}]},terminal:{system:"vision-cfg",settable:["CAMERA","PX_REQ"],commands:[{cmd:"status",out:{vi:"Trạm VIS-7304: robot 6 trục gắp vỏ nhôm, đèn vòm khuếch tán; cấu hình nháp CAMERA=CAM-2MP, PX_REQ=800",en:"Station VIS-7304: 6-axis robot picks aluminium housings, diffuse dome light; draft CAMERA=CAM-2MP, PX_REQ=800"}},{cmd:"cat inspection_spec.txt",out:{vi:"Vết xước nhỏ nhất 0.2 mm; quy tắc nhà máy: khuyết tật nhỏ nhất phải phủ tối thiểu 3 điểm ảnh",en:"Smallest scratch 0.2 mm; plant rule: smallest defect must cover at least 3 pixels"}},{cmd:"cat fov.txt",out:{vi:"Chiều dài chi tiết 150 mm, dung sai vị trí ±5 mm; trường nhìn ngang 160 mm",en:"Part length 150 mm, positioning tolerance ±5 mm; horizontal FOV 160 mm"}},{cmd:"cat camera_list.txt",out:{vi:"CAM-2MP 1600 x 1200; CAM-5MP 2448 x 2048; CAM-12MP 4096 x 3000; cùng ngàm ống kính và giao tiếp",en:"CAM-2MP 1600 x 1200; CAM-5MP 2448 x 2048; CAM-12MP 4096 x 3000; same lens mount and interface"}},{cmd:"grab test",out:{vi:"Ảnh thử với CAM-2MP: 0.1 mm/px, vết xước 0.2 mm chỉ phủ 2 điểm ảnh, tỷ lệ phát hiện 71%",en:"Test image with CAM-2MP: 0.1 mm/px, 0.2 mm scratch covers only 2 pixels, detection rate 71%"}}]},crisis:{vi:"Quản lý dự án nhắn: “Khách đến nghiệm thu chiều nay, robot chạy chậm vì cảm biến quét vùng an toàn cứ dừng máy. Tắt cảm biến đi cho robot chạy tốc độ đầy đủ khi demo.”",en:"The project manager messages: “The client comes for acceptance this afternoon and the robot is slow because the safety laser scanner keeps stopping it. Mute the scanner so the robot runs at full speed for the demo.”"},options:{safe:{vi:"Từ chối tắt cảm biến an toàn; kiểm tra lại cấu hình vùng quét theo đánh giá rủi ro, báo trưởng nhóm và đề nghị dời phần demo tốc độ cao nếu chưa đạt.",en:"Refuse to mute the safety scanner; recheck the zone configuration against the risk assessment, inform the lead and propose postponing the high-speed demo if it is not ready."},shortcut:{vi:"Tắt cảm biến quét trong buổi demo rồi bật lại khi khách về.",en:"Mute the scanner during the demo and turn it back on after the client leaves."},wait:{vi:"Không trả lời và để quản lý dự án tự xử lý với khách.",en:"Do not reply and let the project manager handle the client."}},questions:{vi:["Vì sao cần 2400 điểm ảnh ngang và camera CAM-5MP? Độ phân giải mm/px thực tế sau khi đổi camera là bao nhiêu?","Vì sao không được tắt cảm biến vùng an toàn dù chỉ để demo, và bạn xử lý dừng máy phiền toái thế nào cho đúng?"],en:["Why are 2400 horizontal pixels and the CAM-5MP needed? What is the actual mm/px resolution after the change?","Why must the safety scanner never be muted even for a demo, and how should nuisance stops be handled properly?"]},hints:{vi:["Đặt cấu hình nháp cạnh đặc tả kiểm tra và đọc lại quy tắc số điểm ảnh tối thiểu.","Áp dụng SOP mục 3.2: đổi kích thước khuyết tật ra kích thước mỗi điểm ảnh rồi chia trường nhìn.","Đọc lại SOP mục 4.2: thiết bị bảo vệ an toàn chỉ được thay đổi qua đánh giá rủi ro và phê duyệt."],en:["Place the draft configuration next to the inspection spec and re-read the minimum pixel rule.","Apply SOP 3.2: convert defect size into pixel size, then divide the field of view by it.","Re-read SOP 4.2: safeguards may only change through risk assessment and approval."]}},learning:{summary:{vi:"Kỹ sư Robot và Thị giác Máy thiết kế, lập trình và tích hợp robot công nghiệp với hệ thống camera để gắp đặt, lắp ráp, đo kiểm và kiểm tra khuyết tật tự động. Giá trị tạo ra là năng suất cao, chất lượng ổn định và giảm việc nặng nhọc cho con người. Công việc đòi hỏi hiểu động học robot, quang học, xử lý ảnh, hiệu chuẩn và tuân thủ nghiêm ngặt an toàn máy.",en:"A Robotics and Machine Vision Engineer designs, programs and integrates industrial robots with camera systems for automated pick-and-place, assembly, measurement and defect inspection. The value is high throughput, stable quality and less strenuous work for people. The role requires knowledge of robot kinematics, optics, image processing, calibration and strict machine safety compliance."},responsibilities:{vi:["Thiết kế ô robot, chọn robot, tay gắp, camera, ống kính và chiếu sáng phù hợp.","Lập trình quỹ đạo robot, tối ưu chu kỳ và tránh va chạm.","Xây dựng thuật toán xử lý ảnh, hiệu chuẩn camera và hiệu chuẩn tay - mắt.","Đánh giá rủi ro an toàn, cấu hình vùng bảo vệ, cửa khóa liên động và dừng khẩn.","Chạy thử, đo năng lực hệ thống kiểm tra và bàn giao tài liệu vận hành."],en:["Design robot cells and select the robot, gripper, camera, lens and lighting.","Program robot paths, optimise cycle time and avoid collisions.","Build image processing algorithms and calibrate cameras and hand-eye relationships.","Assess safety risks and configure protective zones, interlocked guards and emergency stops.","Commission, measure inspection system capability and hand over operating documents."]},competencies:[{name:{vi:"Lập trình robot",en:"Robot programming"},desc:{vi:"Dạy điểm, lập trình ngoại tuyến, quản lý hệ tọa độ công cụ và phôi.",en:"Teach points, program offline and manage tool and work object frames."}},{name:{vi:"Quang học và chiếu sáng",en:"Optics and lighting"},desc:{vi:"Tính trường nhìn, độ phân giải, độ sâu trường ảnh và chọn kỹ thuật chiếu sáng.",en:"Compute field of view, resolution and depth of field and choose lighting techniques."}},{name:{vi:"Xử lý ảnh",en:"Image processing"},desc:{vi:"Dùng lọc, phân ngưỡng, tìm cạnh, đối sánh mẫu và mô hình học sâu khi cần.",en:"Apply filtering, thresholding, edge finding, pattern matching and deep learning where needed."}},{name:{vi:"An toàn máy",en:"Machine safety"},desc:{vi:"Đánh giá rủi ro, tính khoảng cách an toàn và chọn mức hiệu năng PL cho mạch an toàn.",en:"Assess risk, calculate safety distances and set performance levels for safety circuits."}},{name:{vi:"Tích hợp hệ thống",en:"System integration"},desc:{vi:"Kết nối robot, camera, PLC qua giao tiếp công nghiệp và đồng bộ tín hiệu kích hoạt.",en:"Connect robots, cameras and PLCs over industrial protocols and synchronise triggers."}}],knowledge:{vi:["ISO 10218-1 và ISO 10218-2 về an toàn robot công nghiệp và hệ thống robot.","ISO/TS 15066 về robot cộng tác và giới hạn lực, áp suất tiếp xúc.","ISO 13849-1 về bộ phận liên quan an toàn của hệ thống điều khiển và mức PL.","ISO 13855 về bố trí thiết bị bảo vệ theo tốc độ tiếp cận của cơ thể người.","EMVA 1288 về đặc tính camera và cảm biến ảnh; nguyên lý lấy mẫu và độ phân giải không gian."],en:["ISO 10218-1 and ISO 10218-2 on safety of industrial robots and robot systems.","ISO/TS 15066 on collaborative robots and contact force and pressure limits.","ISO 13849-1 on safety-related parts of control systems and performance levels.","ISO 13855 on positioning safeguards based on human body approach speeds.","EMVA 1288 on camera and image sensor characterisation; sampling and spatial resolution principles."]},tools:["Phần mềm lập trình robot ngoại tuyến","Thư viện xử lý ảnh công nghiệp","Camera công nghiệp và ống kính telecentric","Bộ chiếu sáng vòm, thanh, nền sau","Bảng hiệu chuẩn dạng lưới"],kpis:{vi:["Thời gian chu kỳ trạm so với mục tiêu thiết kế.","Tỷ lệ bỏ sót khuyết tật và tỷ lệ báo lỗi giả của hệ thống thị giác.","Độ sẵn sàng của ô robot.","Số sự cố an toàn hoặc vô hiệu hóa thiết bị bảo vệ (mục tiêu bằng 0)."],en:["Station cycle time versus design target.","Vision system escape rate and false reject rate.","Robot cell availability.","Safety incidents or defeated safeguards (target zero)."]},day:[{time:"08:00",vi:"Xem thống kê lỗi giả và bỏ sót của trạm thị giác ca trước.",en:"Review false rejects and escapes from the vision stations last shift."},{time:"09:30",vi:"Hiệu chuẩn lại camera và tay - mắt sau khi thay ống kính.",en:"Recalibrate the camera and hand-eye relationship after a lens change."},{time:"11:00",vi:"Tối ưu quỹ đạo robot, giảm 0.4 giây chu kỳ mà không vượt giới hạn tốc độ an toàn.",en:"Optimise robot paths to cut 0.4 s of cycle time within safe speed limits."},{time:"14:00",vi:"Kiểm tra vùng quét an toàn, cửa liên động và nút dừng khẩn theo danh mục.",en:"Check safety scanner zones, interlocked doors and emergency stops against the checklist."},{time:"16:30",vi:"Ghi nhận thay đổi thuật toán, sao lưu chương trình robot và cấu hình camera.",en:"Log algorithm changes and back up robot programs and camera configurations."}],mistakes:{vi:["Chọn camera theo nguyên tắc 1 điểm ảnh cho mỗi khuyết tật, dẫn tới bỏ sót lỗi.","Bỏ qua dung sai vị trí khi tính trường nhìn khiến chi tiết lọt ra ngoài ảnh.","Tắt hoặc thu nhỏ vùng an toàn để tăng tốc độ mà không đánh giá rủi ro lại."],en:["Sizing the camera at 1 pixel per defect, causing missed defects.","Ignoring positioning tolerance in the FOV so parts fall outside the image.","Muting or shrinking safety zones for speed without a new risk assessment."]},career:[{vi:"Kỹ thuật viên robot",en:"Robot technician"},{vi:"Kỹ sư robot và thị giác máy",en:"Robotics and machine vision engineer"},{vi:"Kỹ sư trưởng tích hợp hệ thống tự động",en:"Lead automation integration engineer"},{vi:"Trưởng phòng tự động hóa thông minh",en:"Head of smart automation"}],glossary:[{term:"FOV",vi:"Trường nhìn, vùng không gian camera thu được trong một ảnh.",en:"Field of view, the area a camera captures in one image."},{term:"Spatial resolution",vi:"Độ phân giải không gian, kích thước thực tế mà mỗi điểm ảnh biểu diễn (mm/px).",en:"The real-world size each pixel represents (mm/px)."},{term:"Hand-eye calibration",vi:"Hiệu chuẩn quan hệ tọa độ giữa camera và robot để robot gắp đúng vị trí ảnh.",en:"Calibrating the camera-to-robot coordinate relationship so the robot picks where the image shows."},{term:"Telecentric lens",vi:"Ống kính giữ độ phóng đại không đổi theo khoảng cách, phù hợp đo kích thước.",en:"A lens with constant magnification over distance, suited to dimensional measurement."},{term:"Muting",vi:"Tạm vô hiệu hóa chức năng bảo vệ theo điều kiện thiết kế trước; không được dùng tùy tiện.",en:"Temporarily suspending a protective function under pre-designed conditions; never used ad hoc."}],quiz:[{q:{vi:"Trường nhìn 120 mm, khuyết tật nhỏ nhất 0.1 mm, cần 3 điểm ảnh trên khuyết tật. Cần bao nhiêu điểm ảnh ngang?",en:"FOV 120 mm, smallest defect 0.1 mm, 3 pixels needed per defect. How many horizontal pixels?"},options:{vi:["1200","2400","4800","3600"],en:["1200","2400","4800","3600"]},answer:3,explain:{vi:"Mỗi điểm ảnh 0.1 / 3 mm, số điểm ảnh = 120 / (0.1 / 3) = 3600.",en:"Each pixel is 0.1 / 3 mm, so pixels = 120 / (0.1 / 3) = 3600."}},{q:{vi:"Để đo kích thước biên dạng chi tiết chính xác bằng hình bóng, kỹ thuật chiếu sáng nào phù hợp nhất?",en:"Which lighting best suits precise silhouette measurement of a part outline?"},options:{vi:["Chiếu sáng nền sau","Chiếu sáng góc thấp","Đèn vòm khuếch tán","Đèn đồng trục"],en:["Backlight","Low-angle dark-field light","Diffuse dome light","Coaxial light"]},answer:0,explain:{vi:"Nền sau tạo hình bóng tương phản cao, biên chi tiết sắc nét để đo.",en:"A backlight creates a high-contrast silhouette with sharp edges for measurement."}},{q:{vi:"Quản lý yêu cầu tắt cảm biến quét an toàn để robot chạy nhanh khi demo. Bạn làm gì?",en:"A manager asks you to mute the safety scanner so the robot runs fast in a demo. What do you do?"},options:{vi:["Tắt trong lúc demo","Thu nhỏ vùng quét tối đa","Từ chối, kiểm tra cấu hình vùng theo đánh giá rủi ro và báo trưởng nhóm","Dán băng che cảm biến"],en:["Mute it during the demo","Shrink the zone as much as possible","Refuse, check zone settings against the risk assessment and inform the lead","Tape over the sensor"]},answer:2,explain:{vi:"Vô hiệu hóa thiết bị bảo vệ có thể gây chấn thương nghiêm trọng; mọi thay đổi phải qua đánh giá rủi ro.",en:"Defeating safeguards can cause serious injury; any change must go through risk assessment."}},{q:{vi:"Tiêu chuẩn nào quy định giới hạn lực và áp suất tiếp xúc cho robot cộng tác?",en:"Which document sets contact force and pressure limits for collaborative robots?"},options:{vi:["ISO 13855","ISO/TS 15066","ISO 9001","EMVA 1288"],en:["ISO 13855","ISO/TS 15066","ISO 9001","EMVA 1288"]},answer:1,explain:{vi:"ISO/TS 15066 hướng dẫn vận hành cộng tác, gồm giới hạn sinh cơ học khi tiếp xúc.",en:"ISO/TS 15066 guides collaborative operation, including biomechanical contact limits."}}]}},"KK-586":{scenario:{company:"Trường Sơn Electronics Design",supervisor:{name:"Bùi Ngọc Diệp",role:{vi:"Trưởng phòng Thiết kế Phần cứng",en:"Hardware Design Manager"}},ref_code:"PCB-3518",title:{vi:"Tính đúng tổn hao. Chọn đúng bộ nguồn. Báo cáo đúng nhiệt độ.",en:"Right losses. Right regulator. True temperatures."},brief:{vi:"Bo mạch PCB-3518 cấp nguồn 12 V, rail 3.3 V tải liên tục 0.35 A. Bản xét duyệt thiết kế nháp chọn LDO vỏ SOT-223 và tính sai công suất tiêu tán. Nhiệt độ môi trường trong vỏ máy tối đa 50°C, giới hạn nhiệt độ mối nối 125°C, θJA mô phỏng: SOT-223 62°C/W, DPAK 30°C/W. Đối chiếu với quy tắc thiết kế nguồn đã duyệt, sửa kiểu bộ ổn áp và công suất tiêu tán của LDO (W), rồi lập báo cáo có căn cứ.",en:"Board PCB-3518 runs from 12 V and its 3.3 V rail draws a continuous 0.35 A. The draft design review picks an SOT-223 LDO and miscalculates its dissipation. Maximum ambient inside the enclosure is 50°C, junction limit 125°C, training θJA: SOT-223 62°C/W, DPAK 30°C/W. Check it against the approved power design rules, correct the regulator type and the LDO power dissipation (W), then write an evidence-based report."},reference_title:{vi:"Quy tắc thiết kế nguồn và ngân sách công suất đã duyệt · PCB-3518",en:"Approved power design rules and power budget · PCB-3518"},fields:[{id:"REG_TYPE",label:{vi:"Kiểu bộ ổn áp rail 3.3 V",en:"3.3 V rail regulator type"},initial:"LDO-SOT223",expected:"BUCK-SYNC",choices:["LDO-SOT223","LDO-DPAK","BUCK-SYNC"],reference:"Quy tắc chọn bộ ổn áp",hint:{vi:"Kiểm tra nhiệt độ mối nối của từng phương án LDO; nếu cả hai vượt giới hạn thì phải đổi kiến trúc.",en:"Check the junction temperature of each LDO option; if both exceed the limit, change the architecture."}},{id:"P_LDO",label:{vi:"Công suất tiêu tán của LDO (W)",en:"LDO power dissipation (W)"},initial:"1.155",expected:"3.045",reference:"Bảng ngân sách công suất rail 3.3 V",ref_value:{vi:"Vin 12 V; Vout 3.3 V; dòng tải liên tục 0.35 A; bỏ qua dòng tĩnh",en:"Vin 12 V; Vout 3.3 V; continuous load 0.35 A; quiescent current ignored"},hint:{vi:"LDO tiêu tán phần điện áp chênh lệch nhân dòng tải, không phải công suất ra tải.",en:"An LDO dissipates the voltage drop times load current, not the output power."}}],sop32:{vi:"P_LDO = (Vin - Vout) x Iout (bỏ qua dòng tĩnh); Tj = Ta + P_LDO x θJA phải ≤ 125°C. Nếu không phương án LDO nào đạt thì dùng bộ hạ áp đồng bộ BUCK-SYNC.",en:"P_LDO = (Vin - Vout) x Iout (quiescent current ignored); Tj = Ta + P_LDO x θJA must be ≤ 125°C. If no LDO option passes, use the synchronous buck BUCK-SYNC."},context:{label:"EDA DESIGN REVIEW / PCB-3518",metrics:[{label:{vi:"Điện áp vào / ra",en:"Input / output voltage"},value:"12 V / 3.3 V"},{label:{vi:"Dòng tải liên tục",en:"Continuous load"},value:"0.35 A"},{label:{vi:"Nhiệt độ môi trường tối đa",en:"Maximum ambient"},value:"50°C"}]},terminal:{system:"eda-shell",settable:["REG_TYPE","P_LDO"],commands:[{cmd:"status",out:{vi:"PCB-3518 rev A, 4 lớp; U5 ổn áp rail 3.3 V; bản xét duyệt nháp REG_TYPE=LDO-SOT223, P_LDO=1.155",en:"PCB-3518 rev A, 4 layers; U5 regulates the 3.3 V rail; draft review REG_TYPE=LDO-SOT223, P_LDO=1.155"}},{cmd:"cat power_budget.txt",out:{vi:"Rail 3.3 V: vi điều khiển 120 mA, mô-đun vô tuyến 180 mA, cảm biến và đèn báo 50 mA; tổng 0.35 A liên tục; nguồn vào 12 V",en:"3.3 V rail: MCU 120 mA, radio module 180 mA, sensors and LEDs 50 mA; total 0.35 A continuous; 12 V input"}},{cmd:"cat u5_options.txt",out:{vi:"LDO-SOT223 θJA 62°C/W; LDO-DPAK θJA 30°C/W; BUCK-SYNC hiệu suất khoảng 90% ở 0.35 A (số liệu mô phỏng)",en:"LDO-SOT223 θJA 62°C/W; LDO-DPAK θJA 30°C/W; BUCK-SYNC about 90% efficient at 0.35 A (training data)"}},{cmd:"cat enclosure.txt",out:{vi:"Vỏ kín IP54, nhiệt độ môi trường bên trong tối đa 50°C; giới hạn mối nối linh kiện 125°C",en:"Sealed IP54 enclosure, internal ambient up to 50°C; component junction limit 125°C"}},{cmd:"thermal-scan proto",out:{vi:"Mẫu thử sau 10 phút: bề mặt U5 trên 118°C, rail 3.3 V sụt định kỳ do bảo vệ quá nhiệt tác động",en:"Prototype after 10 minutes: U5 surface above 118°C, 3.3 V rail drops periodically as thermal shutdown cycles"}}]},crisis:{vi:"Giám đốc dự án nhắn: “Khách cần hồ sơ phát hành sản xuất ngày mai. Cứ ghi mục thử nhiệt là PASS, đổi thiết kế sau ở rev B, khách không đo lại đâu.”",en:"The project director messages: “The client needs the production release file tomorrow. Just mark the thermal test PASS, we will change the design in rev B, the client will not retest.”"},options:{safe:{vi:"Từ chối ghi PASS; ghi đúng kết quả thử nhiệt, báo trưởng phòng và khách về rủi ro, đề xuất đổi U5 sang BUCK-SYNC và thử lại trước khi phát hành.",en:"Refuse to mark PASS; record the true thermal result, inform the manager and client of the risk, propose changing U5 to BUCK-SYNC and retest before release."},shortcut:{vi:"Ghi PASS để kịp phát hành, sửa thiết kế ở bản rev B.",en:"Mark PASS to meet the release and fix the design in rev B."},wait:{vi:"Để trống mục thử nhiệt và chờ giám đốc dự án tự điền.",en:"Leave the thermal test blank and wait for the project director to fill it in."}},questions:{vi:["Vì sao công suất tiêu tán đúng là 3.045 W và cả hai phương án LDO đều không đạt? Tính Tj cho từng phương án.","Ghi PASS sai cho mục thử nhiệt gây rủi ro gì cho người dùng, khách hàng và công ty? Bạn xử lý áp lực tiến độ ra sao?"],en:["Why is the correct dissipation 3.045 W and why do both LDO options fail? Compute Tj for each option.","What risks does a false thermal PASS create for users, the client and the company? How do you handle the schedule pressure?"]},hints:{vi:["Đặt bản xét duyệt nháp cạnh bảng ngân sách công suất và kiểm tra công thức tổn hao.","Áp dụng SOP mục 3.2: tính tổn hao rồi nhân với θJA của từng vỏ, cộng nhiệt độ môi trường.","Đọc lại SOP mục 4.2: kết quả thử nghiệm phải ghi đúng như đo, không được điền trước."],en:["Place the draft review next to the power budget and check the loss formula.","Apply SOP 3.2: compute the loss, multiply by each package θJA and add ambient.","Re-read SOP 4.2: test results must be recorded as measured, never filled in beforehand."]}},learning:{summary:{vi:"Kỹ sư Điện tử và Thiết kế Mạch in thiết kế sơ đồ nguyên lý, chọn linh kiện, bố trí và đi dây bo mạch nhiều lớp, tính nguồn, nhiệt, tín hiệu tốc độ cao và chuẩn bị hồ sơ sản xuất. Mục tiêu là bo mạch chạy ổn định, đạt tương thích điện từ, an toàn, dễ sản xuất và giá thành hợp lý. Công việc đòi hỏi vững mạch tương tự, số, nguồn, đọc kỹ datasheet và trung thực với kết quả thử nghiệm.",en:"An Electronics and PCB Design Engineer creates schematics, selects components, places and routes multilayer boards, analyses power, thermal and high-speed signals and prepares manufacturing files. The goal is a board that runs reliably, passes EMC and safety, is easy to build and is cost-effective. The role requires solid analogue, digital and power skills, careful datasheet reading and honesty about test results."},responsibilities:{vi:["Thiết kế sơ đồ nguyên lý, chọn linh kiện theo thông số, tuổi thọ và nguồn cung.","Bố trí linh kiện, xếp lớp, đi dây trở kháng kiểm soát và mặt phẳng nguồn, đất.","Tính ngân sách công suất, nhiệt, độ rộng đường mạch và kiểm tra DRC, ERC.","Chuẩn bị Gerber, danh mục linh kiện, tọa độ gắp đặt và hồ sơ lắp ráp.","Thử nghiệm mẫu: chức năng, nhiệt, EMC sơ bộ và sửa lỗi phần cứng."],en:["Draw schematics and select parts by ratings, lifetime and supply availability.","Place components, define stack-up and route controlled-impedance traces and power and ground planes.","Compute power, thermal and trace-width budgets and run DRC and ERC.","Prepare Gerbers, BOM, pick-and-place data and assembly drawings.","Test prototypes: function, thermal and EMC pre-scan, and debug hardware."]},competencies:[{name:{vi:"Thiết kế mạch nguồn",en:"Power circuit design"},desc:{vi:"Chọn LDO hay bộ chuyển mạch, tính tổn hao, gợn sóng, đáp ứng quá độ và nhiệt.",en:"Choose LDO or switching regulators and compute losses, ripple, transient response and thermal load."}},{name:{vi:"Bố trí mạch in",en:"PCB layout"},desc:{vi:"Đặt linh kiện tối ưu đường dòng, tách vùng nhiễu, giữ vòng dòng nhỏ.",en:"Place parts for clean current paths, separate noisy areas and keep loops small."}},{name:{vi:"Toàn vẹn tín hiệu",en:"Signal integrity"},desc:{vi:"Kiểm soát trở kháng, phản xạ, nhiễu xuyên kênh và đường hồi tiếp tín hiệu.",en:"Control impedance, reflections, crosstalk and signal return paths."}},{name:{vi:"Thiết kế cho sản xuất",en:"Design for manufacturing"},desc:{vi:"Áp dụng chuẩn chân hàn, khoảng cách, điểm thử để lắp ráp và kiểm tra hiệu quả.",en:"Apply land pattern, spacing and test point rules for efficient assembly and test."}},{name:{vi:"Trung thực trong thử nghiệm",en:"Test integrity"},desc:{vi:"Ghi đúng kết quả đo, báo sớm rủi ro và không phát hành khi thiết kế chưa đạt.",en:"Record results as measured, flag risks early and never release a failing design."}}],knowledge:{vi:["IPC-2221 về nguyên tắc chung thiết kế mạch in; IPC-2152 về khả năng mang dòng của đường mạch.","IPC-7351 về chân hàn linh kiện dán bề mặt; IPC-A-610 về tiêu chí chấp nhận cụm lắp ráp điện tử.","Nhiệt học linh kiện: θJA, θJC, công suất tiêu tán và giới hạn nhiệt độ mối nối.","CISPR 32 về phát xạ điện từ của thiết bị đa phương tiện; IEC 62368-1 về an toàn thiết bị ICT.","Chỉ thị RoHS 2011/65/EU về hạn chế chất nguy hại trong thiết bị điện, điện tử."],en:["IPC-2221 generic PCB design standard; IPC-2152 on trace current-carrying capacity.","IPC-7351 on surface-mount land patterns; IPC-A-610 on acceptability of electronic assemblies.","Component thermal behaviour: θJA, θJC, power dissipation and junction temperature limits.","CISPR 32 on emissions of multimedia equipment; IEC 62368-1 on ICT equipment safety.","RoHS Directive 2011/65/EU restricting hazardous substances in electrical and electronic equipment."]},tools:["Phần mềm thiết kế sơ đồ và mạch in","Phần mềm mô phỏng mạch SPICE","Máy hiện sóng và nguồn lập trình","Camera nhiệt","Máy phân tích phổ cho thử EMC sơ bộ"],kpis:{vi:["Số lần sửa bo (respin) trước khi phát hành sản xuất.","Tỷ lệ bo đạt thử EMC và an toàn ngay lần đầu.","Tỷ lệ lỗi lắp ráp liên quan thiết kế trên dây chuyền.","Độ chính xác của danh mục linh kiện và hồ sơ sản xuất."],en:["Board respins before production release.","Share of boards passing EMC and safety tests first time.","Design-related assembly defect rate on the line.","Accuracy of the BOM and manufacturing files."]},day:[{time:"08:30",vi:"Xem phản hồi lắp ráp mẫu và danh sách lỗi phần cứng mở.",en:"Review prototype assembly feedback and the open hardware bug list."},{time:"10:00",vi:"Tính ngân sách công suất rail mới, kiểm tra nhiệt từng bộ ổn áp.",en:"Compute the power budget for a new rail and check each regulator's thermal load."},{time:"13:30",vi:"Đi dây cặp vi sai tốc độ cao, kiểm tra trở kháng với nhà sản xuất bo.",en:"Route high-speed differential pairs and confirm impedance with the board fab."},{time:"15:30",vi:"Đo nhiệt và dạng sóng trên mẫu thử, ghi kết quả vào báo cáo thử nghiệm.",en:"Measure temperatures and waveforms on the prototype and log results in the test report."},{time:"17:00",vi:"Chạy DRC, ERC, cập nhật danh mục linh kiện và lưu phiên bản thiết kế.",en:"Run DRC and ERC, update the BOM and archive the design revision."}],mistakes:{vi:["Tính tổn hao LDO bằng công suất ra tải thay vì chênh lệch điện áp nhân dòng.","Bỏ qua nhiệt độ môi trường trong vỏ kín khi kiểm tra nhiệt độ mối nối.","Ghi kết quả thử nghiệm trước khi đo hoặc sửa số cho đạt để kịp phát hành."],en:["Computing LDO loss as output power instead of voltage drop times current.","Ignoring the sealed-enclosure ambient when checking junction temperature.","Writing test results before measuring or adjusting numbers to pass for release."]},career:[{vi:"Kỹ thuật viên điện tử",en:"Electronics technician"},{vi:"Kỹ sư thiết kế phần cứng và mạch in",en:"Hardware and PCB design engineer"},{vi:"Kỹ sư phần cứng cấp cao",en:"Senior hardware engineer"},{vi:"Trưởng phòng thiết kế phần cứng",en:"Hardware engineering manager"}],glossary:[{term:"LDO",vi:"Bộ ổn áp tuyến tính sụt áp thấp, tiêu tán phần điện áp chênh lệch thành nhiệt.",en:"Low-dropout linear regulator that turns the voltage drop into heat."},{term:"Buck converter",vi:"Bộ chuyển đổi hạ áp dùng chuyển mạch, hiệu suất cao hơn LDO khi chênh áp lớn.",en:"Switching step-down converter, more efficient than an LDO at large voltage drops."},{term:"θJA",vi:"Nhiệt trở từ mối nối tới môi trường, cho biết nhiệt độ tăng trên mỗi watt tiêu tán.",en:"Junction-to-ambient thermal resistance, the temperature rise per watt dissipated."},{term:"DRC",vi:"Kiểm tra quy tắc thiết kế như khoảng cách, độ rộng đường mạch, lỗ khoan.",en:"Design rule check covering clearance, trace width and drill rules."},{term:"Stack-up",vi:"Cấu trúc xếp lớp đồng và điện môi của bo mạch, quyết định trở kháng và EMC.",en:"Copper and dielectric layer structure of a board that sets impedance and EMC."}],quiz:[{q:{vi:"LDO hạ 5 V xuống 1.8 V cho tải 0.5 A. Công suất tiêu tán là bao nhiêu?",en:"An LDO drops 5 V to 1.8 V at 0.5 A. What is its dissipation?"},options:{vi:["0.9 W","2.5 W","1.6 W","3.2 W"],en:["0.9 W","2.5 W","1.6 W","3.2 W"]},answer:2,explain:{vi:"P = (5 - 1.8) x 0.5 = 1.6 W; lấy 1.8 x 0.5 = 0.9 W là công suất ra tải, không phải tổn hao.",en:"P = (5 - 1.8) x 0.5 = 1.6 W; 1.8 x 0.5 = 0.9 W is the output power, not the loss."}},{q:{vi:"Linh kiện tiêu tán 2 W, θJA 40°C/W, môi trường 45°C. Nhiệt độ mối nối là bao nhiêu?",en:"A part dissipates 2 W with θJA 40°C/W at 45°C ambient. What is the junction temperature?"},options:{vi:["125°C","85°C","80°C","165°C"],en:["125°C","85°C","80°C","165°C"]},answer:0,explain:{vi:"Tj = 45 + 2 x 40 = 125°C, chạm giới hạn thường gặp, không còn dự trữ.",en:"Tj = 45 + 2 x 40 = 125°C, right at a common limit with no margin."}},{q:{vi:"Giám đốc yêu cầu ghi PASS cho thử nhiệt chưa đạt để kịp phát hành. Bạn làm gì?",en:"The director asks you to mark a failed thermal test PASS to meet the release. What do you do?"},options:{vi:["Ghi PASS vì sẽ sửa ở bản sau","Để trống cho người khác điền","Ghi PASS kèm chú thích nhỏ","Ghi đúng kết quả, báo rủi ro và đề xuất sửa thiết kế trước khi phát hành"],en:["Mark PASS since rev B will fix it","Leave it blank for someone else","Mark PASS with a small footnote","Record the true result, flag the risk and propose a fix before release"]},answer:3,explain:{vi:"Làm sai lệch kết quả thử nghiệm có thể gây cháy hỏng, mất an toàn và vi phạm cam kết với khách hàng.",en:"Falsifying test results can cause failures and fire hazards and breaks commitments to the client."}},{q:{vi:"Chuẩn nào hướng dẫn khả năng mang dòng của đường mạch in?",en:"Which standard guides the current-carrying capacity of PCB traces?"},options:{vi:["IPC-A-610","IPC-2152","CISPR 32","IPC-7351"],en:["IPC-A-610","IPC-2152","CISPR 32","IPC-7351"]},answer:1,explain:{vi:"IPC-2152 cung cấp dữ liệu và biểu đồ chọn độ rộng đường mạch theo dòng và độ tăng nhiệt.",en:"IPC-2152 provides data and charts for sizing traces by current and temperature rise."}}]}},"KK-587":{scenario:{company:"Thiên Phúc Industrial IoT",supervisor:{name:"Mai Xuân Trường",role:{vi:"Trưởng nhóm Phần mềm Nhúng",en:"Embedded Software Lead"}},ref_code:"FW-8826",title:{vi:"Cảnh báo không được mất. Pin phải đủ năm. Bảo mật không tắt.",en:"No lost alarms. Battery must last. Security stays on."},brief:{vi:"Nút cảm biến rung không dây FW-8826 gửi MQTT qua NB-IoT, chu kỳ 900 giây: thức 6 giây ở 60 mA, ngủ 894 giây ở 20 µA, dung lượng pin khả dụng 3000 mAh (mô phỏng). Nhật ký broker cho thấy mất bản tin cảnh báo khi sóng yếu. Đối chiếu cấu hình firmware nháp với đặc tả đã duyệt, sửa mức QoS cho bản tin cảnh báo và tuổi thọ pin dự kiến (ngày), rồi lập báo cáo có căn cứ.",en:"Wireless vibration sensor node FW-8826 publishes MQTT over NB-IoT on a 900-second cycle: awake 6 s at 60 mA, asleep 894 s at 20 µA, usable battery capacity 3000 mAh (training value). The broker log shows alarm messages lost on weak signal. Check the draft firmware configuration against the approved specification, correct the QoS level for alarm messages and the expected battery life (days), then write an evidence-based report."},reference_title:{vi:"Đặc tả firmware và ngân sách năng lượng đã duyệt · FW-8826",en:"Approved firmware specification and energy budget · FW-8826"},fields:[{id:"ALARM_QOS",label:{vi:"Mức QoS của bản tin cảnh báo",en:"QoS level for alarm messages"},initial:"QOS0",expected:"QOS1",choices:["QOS0","QOS1","QOS2"],reference:"Đặc tả truyền thông FW-8826",hint:{vi:"Bản tin phải tới ít nhất một lần, phía nhận đã chống trùng theo mã sự kiện và cần giảm số lượt bắt tay để tiết kiệm pin.",en:"Messages must arrive at least once, the receiver de-duplicates by event ID and handshakes must be minimised to save battery."}},{id:"BATT_DAYS",label:{vi:"Tuổi thọ pin dự kiến (ngày)",en:"Expected battery life (days)"},initial:"312",expected:"297",reference:"Bảng ngân sách năng lượng",ref_value:{vi:"Chu kỳ 900 s: thức 6 s ở 60 mA; ngủ 894 s ở 20 µA; pin khả dụng 3000 mAh",en:"900 s cycle: awake 6 s at 60 mA; asleep 894 s at 20 µA; usable battery 3000 mAh"},hint:{vi:"Dòng ngủ nhỏ nhưng chiếm gần hết thời gian chu kỳ; đừng bỏ qua khi tính dòng trung bình.",en:"Sleep current is tiny but fills almost the whole cycle; do not ignore it in the average current."}}],sop32:{vi:"Dòng trung bình = (I thức x t thức + I ngủ x t ngủ) / chu kỳ; tuổi thọ (ngày) = dung lượng khả dụng / dòng trung bình / 24, làm tròn xuống số ngày nguyên.",en:"Average current = (I awake x t awake + I sleep x t sleep) / cycle period; life (days) = usable capacity / average current / 24, rounded down to whole days."},context:{label:"FW CONSOLE / FW-8826",metrics:[{label:{vi:"Chu kỳ gửi",en:"Report cycle"},value:"900 s"},{label:{vi:"Dòng thức / ngủ",en:"Awake / sleep current"},value:"60 mA / 20 µA"},{label:{vi:"Pin khả dụng",en:"Usable battery"},value:"3000 mAh"},{label:{vi:"Cảnh báo bị mất tuần qua",en:"Alarms lost last week"},value:"3"}]},terminal:{system:"fw-console",settable:["ALARM_QOS","BATT_DAYS"],commands:[{cmd:"status",out:{vi:"Nút FW-8826, firmware 2.3.1; chủ đề cảnh báo đang ALARM_QOS=QOS0; tài liệu nháp ghi BATT_DAYS=312",en:"Node FW-8826, firmware 2.3.1; alarm topic set to ALARM_QOS=QOS0; draft document states BATT_DAYS=312"}},{cmd:"cat requirements.txt",out:{vi:"Cảnh báo phải tới broker ít nhất một lần; hệ thống nhận chống trùng theo event_id; hạn chế thời gian phát sóng để tiết kiệm pin",en:"Alarms must reach the broker at least once; receiver de-duplicates by event_id; minimise airtime to save battery"}},{cmd:"power-profile",out:{vi:"Đo bằng máy phân tích dòng: thức 6 s ở 60 mA (đo, kết nối, gửi), ngủ 894 s ở 20 µA; chu kỳ 900 s",en:"Current analyser: awake 6 s at 60 mA (measure, attach, send), asleep 894 s at 20 µA; 900 s cycle"}},{cmd:"cat battery.txt",out:{vi:"Pin lithium 3600 mAh danh định; dung lượng khả dụng sau suy giảm nhiệt độ và tự xả: 3000 mAh (mô phỏng)",en:"Lithium cell 3600 mAh nominal; usable capacity after temperature and self-discharge derating: 3000 mAh (training value)"}},{cmd:"cat broker.log",out:{vi:"3 bản tin cảnh báo không tới broker khi RSRP dưới -115 dBm; không có PUBACK vì gửi QoS 0",en:"3 alarm messages never reached the broker at RSRP below -115 dBm; no PUBACK because they were sent at QoS 0"}}]},crisis:{vi:"Giám đốc dự án nhắn: “Mai bàn giao 500 nút cho khách. Tắt kiểm tra chứng chỉ TLS và dùng chung một mật khẩu mặc định cho tất cả thiết bị cho nhanh, sau này tính.”",en:"The project director messages: “We hand over 500 nodes tomorrow. Turn off TLS certificate checks and use one shared default password on every device to save time, we will sort it later.”"},options:{safe:{vi:"Từ chối tắt TLS và dùng mật khẩu chung; giữ xác thực chứng chỉ, cấp thông tin xác thực riêng từng thiết bị bằng kịch bản nạp tự động, báo trưởng nhóm về tiến độ.",en:"Refuse to disable TLS or share a password; keep certificate validation, provision unique per-device credentials with an automated script and inform the lead about the schedule."},shortcut:{vi:"Tắt kiểm tra TLS, dùng mật khẩu chung để kịp bàn giao rồi cập nhật OTA sau.",en:"Disable TLS checks and use a shared password to deliver on time, then patch over the air later."},wait:{vi:"Không trả lời và để nhóm khác tự quyết cấu hình bảo mật.",en:"Do not reply and let another team decide the security settings."}},questions:{vi:["Vì sao chọn QoS 1 cho cảnh báo mà không phải QoS 0 hay QoS 2? Tuổi thọ pin 297 ngày được tính thế nào?","Tắt kiểm tra TLS và dùng mật khẩu chung gây rủi ro gì cho mạng OT của khách, và bạn đáp ứng tiến độ an toàn ra sao?"],en:["Why choose QoS 1 for alarms rather than QoS 0 or QoS 2? How is the 297-day battery life calculated?","What risks do disabled TLS checks and a shared password create for the client's OT network, and how do you meet the schedule securely?"]},hints:{vi:["Đặt cấu hình nháp cạnh đặc tả truyền thông và nhật ký broker để thấy vì sao mất cảnh báo.","Áp dụng SOP mục 3.2: tính điện tích thức và ngủ trong một chu kỳ, chia cho chu kỳ để ra dòng trung bình.","Đọc lại SOP mục 4.2: không hạ cấu hình bảo mật mặc định vì tiến độ, phải báo cáo và đề xuất phương án."],en:["Place the draft configuration next to the communication spec and broker log to see why alarms are lost.","Apply SOP 3.2: compute awake and sleep charge per cycle, then divide by the period for the average current.","Re-read SOP 4.2: never weaken default security for schedule reasons; escalate and propose an alternative."]}},learning:{summary:{vi:"Kỹ sư Hệ thống Nhúng và IoT Công nghiệp phát triển firmware cho vi điều khiển, thiết bị biên và nút cảm biến, kết nối máy móc với nền tảng dữ liệu qua giao thức công nghiệp và Internet vạn vật. Giá trị tạo ra là dữ liệu vận hành tin cậy, thời gian thực, giúp bảo trì dự đoán và tối ưu sản xuất. Công việc đòi hỏi hiểu phần cứng, lập trình C an toàn, quản lý năng lượng, giao thức truyền thông và an ninh thiết bị.",en:"An Embedded Systems and IIoT Engineer develops firmware for microcontrollers, edge devices and sensor nodes and connects machines to data platforms through industrial and IoT protocols. The value is reliable, real-time operating data for predictive maintenance and production optimisation. The role requires hardware understanding, safe C programming, power management, communication protocols and device security."},responsibilities:{vi:["Viết firmware C/C++ cho vi điều khiển, trình điều khiển ngoại vi và hệ điều hành thời gian thực.","Kết nối thiết bị qua Modbus, OPC UA, MQTT và mạng không dây công suất thấp.","Tối ưu năng lượng, chế độ ngủ và ngân sách pin cho nút cảm biến.","Thiết kế khởi động an toàn, cập nhật OTA có ký số và cấp thông tin xác thực riêng.","Kiểm thử đơn vị, kiểm thử tích hợp phần cứng và theo dõi lỗi thực địa."],en:["Write C/C++ firmware for microcontrollers, peripheral drivers and real-time operating systems.","Connect devices over Modbus, OPC UA, MQTT and low-power wireless networks.","Optimise power, sleep modes and battery budgets for sensor nodes.","Design secure boot, signed OTA updates and unique device credentials.","Run unit tests and hardware-in-the-loop tests and track field defects."]},competencies:[{name:{vi:"Lập trình nhúng",en:"Embedded programming"},desc:{vi:"Viết mã C an toàn, xử lý ngắt, bộ nhớ hạn chế và thời gian thực.",en:"Write safe C, handle interrupts, constrained memory and real-time deadlines."}},{name:{vi:"Giao thức công nghiệp",en:"Industrial protocols"},desc:{vi:"Hiểu Modbus, OPC UA, MQTT, mức QoS và đánh đổi độ tin cậy với năng lượng.",en:"Understand Modbus, OPC UA, MQTT, QoS levels and reliability versus energy trade-offs."}},{name:{vi:"Quản lý năng lượng",en:"Power management"},desc:{vi:"Đo hồ sơ dòng, tính ngân sách pin và tối ưu chu kỳ thức ngủ.",en:"Profile current, compute battery budgets and optimise wake and sleep cycles."}},{name:{vi:"An ninh thiết bị",en:"Device security"},desc:{vi:"Áp dụng TLS, khởi động an toàn, khóa riêng từng thiết bị và cập nhật có ký số.",en:"Apply TLS, secure boot, per-device keys and signed updates."}},{name:{vi:"Gỡ lỗi phần cứng",en:"Hardware debugging"},desc:{vi:"Dùng máy hiện sóng, máy phân tích logic và trình gỡ lỗi để khoanh vùng lỗi.",en:"Use oscilloscopes, logic analysers and debuggers to isolate faults."}}],knowledge:{vi:["Chuẩn MQTT 3.1.1 và MQTT 5.0 của OASIS, gồm ba mức QoS 0, 1, 2.","IEC 62541 (OPC UA) về trao đổi dữ liệu công nghiệp có mô hình thông tin và bảo mật.","ISA/IEC 62443 về an ninh mạng hệ thống tự động hóa công nghiệp, gồm yêu cầu cho thành phần thiết bị.","ETSI EN 303 645 về an ninh thiết bị IoT: không dùng mật khẩu mặc định chung, cập nhật phần mềm an toàn.","Bộ quy tắc MISRA C về lập trình C an toàn cho hệ thống nhúng."],en:["OASIS MQTT 3.1.1 and MQTT 5.0 standards, including QoS levels 0, 1 and 2.","IEC 62541 (OPC UA) for industrial data exchange with information models and security.","ISA/IEC 62443 on industrial automation cybersecurity, including device component requirements.","ETSI EN 303 645 on IoT security: no universal default passwords and secure software updates.","MISRA C guidelines for safe C programming in embedded systems."]},tools:["Môi trường phát triển và trình gỡ lỗi JTAG/SWD","Máy phân tích dòng tiêu thụ","Máy phân tích logic và máy hiện sóng","Broker MQTT thử nghiệm","Hệ thống tích hợp liên tục cho firmware"],kpis:{vi:["Tỷ lệ bản tin cảnh báo tới đích thành công.","Tuổi thọ pin thực tế so với ngân sách thiết kế.","Tỷ lệ cập nhật OTA thành công không phải thu hồi thiết bị.","Số lỗ hổng bảo mật mức cao còn mở (mục tiêu bằng 0)."],en:["Alarm message delivery success rate.","Field battery life versus design budget.","OTA update success rate without device recalls.","Open high-severity security vulnerabilities (target zero)."]},day:[{time:"08:30",vi:"Xem bảng điều khiển thiết bị thực địa: nút mất kết nối, pin yếu, bản tin lỗi.",en:"Check the field device dashboard: offline nodes, low batteries and error messages."},{time:"10:00",vi:"Đo hồ sơ dòng tiêu thụ của bản firmware mới, so với ngân sách năng lượng.",en:"Profile current on the new firmware build against the energy budget."},{time:"13:30",vi:"Sửa trình điều khiển cảm biến, viết kiểm thử đơn vị và chạy phân tích tĩnh.",en:"Fix a sensor driver, write unit tests and run static analysis."},{time:"15:30",vi:"Thử cập nhật OTA có ký số trên nhóm thiết bị thí điểm.",en:"Trial a signed OTA update on a pilot device group."},{time:"17:00",vi:"Đánh giá mã nguồn với đồng nghiệp, cập nhật nhật ký phát hành và tài liệu.",en:"Review code with a peer and update release notes and documentation."}],mistakes:{vi:["Bỏ qua dòng ngủ khi tính tuổi thọ pin nên hứa với khách con số quá lạc quan.","Gửi bản tin cảnh báo quan trọng bằng QoS 0 khiến mất dữ liệu khi sóng yếu.","Tắt kiểm tra TLS hoặc dùng mật khẩu mặc định chung cho cả lô thiết bị."],en:["Ignoring sleep current in battery life estimates and promising clients an optimistic figure.","Sending critical alarms at QoS 0 and losing data on weak signal.","Disabling TLS checks or using one default password across a device fleet."]},career:[{vi:"Kỹ sư firmware",en:"Firmware engineer"},{vi:"Kỹ sư hệ thống nhúng và IoT",en:"Embedded and IoT systems engineer"},{vi:"Kỹ sư trưởng nền tảng thiết bị",en:"Lead device platform engineer"},{vi:"Kiến trúc sư giải pháp IIoT",en:"IIoT solutions architect"}],glossary:[{term:"QoS 1",vi:"Mức chất lượng dịch vụ MQTT bảo đảm bản tin tới ít nhất một lần, có thể trùng.",en:"MQTT quality of service guaranteeing delivery at least once, possibly duplicated."},{term:"PUBACK",vi:"Gói xác nhận broker gửi lại khi nhận bản tin QoS 1.",en:"Acknowledgement packet the broker returns for a QoS 1 publish."},{term:"Duty cycle",vi:"Tỷ lệ thời gian thiết bị hoạt động trên toàn chu kỳ, quyết định dòng trung bình.",en:"Share of the cycle a device is active, which drives average current."},{term:"Secure boot",vi:"Cơ chế chỉ cho chạy firmware có chữ ký hợp lệ khi khởi động.",en:"Mechanism that only runs validly signed firmware at start-up."},{term:"OTA",vi:"Cập nhật phần mềm từ xa qua mạng không dây, cần ký số và khả năng quay lui.",en:"Over-the-air software update that needs signing and rollback."}],quiz:[{q:{vi:"Chu kỳ 600 s: thức 3 s ở 40 mA, ngủ 597 s ở 0.02 mA. Dòng trung bình xấp xỉ bao nhiêu?",en:"A 600 s cycle: awake 3 s at 40 mA, asleep 597 s at 0.02 mA. What is the approximate average current?"},options:{vi:["0.200 mA","0.020 mA","40.0 mA","0.220 mA"],en:["0.200 mA","0.020 mA","40.0 mA","0.220 mA"]},answer:3,explain:{vi:"Dòng trung bình = (3 x 40 + 597 x 0.02) / 600 = 131.94 / 600, xấp xỉ 0.220 mA.",en:"Average = (3 x 40 + 597 x 0.02) / 600 = 131.94 / 600, about 0.220 mA."}},{q:{vi:"Mức QoS MQTT nào bảo đảm bản tin tới đúng một lần nhưng tốn bắt tay nhiều nhất?",en:"Which MQTT QoS level ensures exactly-once delivery but costs the most handshakes?"},options:{vi:["QoS 0","QoS 2","QoS 1","Bản tin giữ lại"],en:["QoS 0","QoS 2","QoS 1","Retained message"]},answer:1,explain:{vi:"QoS 2 dùng bắt tay bốn bước để bảo đảm đúng một lần, tốn năng lượng hơn QoS 1.",en:"QoS 2 uses a four-step handshake for exactly-once delivery and costs more energy than QoS 1."}},{q:{vi:"Giám đốc yêu cầu tắt TLS và dùng mật khẩu chung cho 500 thiết bị để kịp bàn giao. Bạn làm gì?",en:"The director asks you to disable TLS and use one password on 500 devices to meet the handover. What do you do?"},options:{vi:["Từ chối, giữ TLS, cấp thông tin xác thực riêng bằng kịch bản tự động và báo trưởng nhóm","Làm theo rồi cập nhật OTA sau","Chỉ tắt TLS, giữ mật khẩu riêng","Ghi mật khẩu chung lên nhãn thiết bị"],en:["Refuse, keep TLS, provision unique credentials by script and inform the lead","Comply and patch over the air later","Disable TLS only and keep unique passwords","Print the shared password on the device label"]},answer:0,explain:{vi:"Mật khẩu chung và TLS tắt mở đường cho tấn công hàng loạt vào mạng OT của khách.",en:"Shared passwords and disabled TLS open the door to fleet-wide attacks on the client's OT network."}},{q:{vi:"Dòng trung bình 0.5 mA, pin khả dụng 2400 mAh. Tuổi thọ pin là bao nhiêu ngày?",en:"Average current 0.5 mA and usable battery 2400 mAh. How many days does it last?"},options:{vi:["4800 ngày","100 ngày","200 ngày","48 ngày"],en:["4800 days","100 days","200 days","48 days"]},answer:2,explain:{vi:"Tuổi thọ = 2400 / 0.5 = 4800 giờ, chia 24 được 200 ngày.",en:"Life = 2400 / 0.5 = 4800 hours, divided by 24 gives 200 days."}}]}},"KK-588":{scenario:{company:"Tân Phong Calibration Lab",supervisor:{name:"Đỗ Minh Khoa",role:{vi:"Trưởng phòng thí nghiệm hiệu chuẩn",en:"Calibration Laboratory Manager"}},ref_code:"CAL-5521",title:{vi:"Đo đúng. Tính đủ. Kết luận trung thực.",en:"Measure right. Count every uncertainty. Report honestly."},brief:{vi:"Bạn soát xét giấy chứng nhận hiệu chuẩn nháp CAL-5521 cho đồng hồ áp suất 0-16 bar, cấp chính xác 1.0 (MPE ±0,16 bar). Tại điểm 10 bar, sai số đo được là +0,14 bar. Ngân sách độ không đảm bảo chuẩn gồm: chuẩn 0,012 bar, độ phân giải 0,009 bar, độ lặp lại 0,008 bar. Hợp đồng áp dụng quy tắc quyết định có băng bảo vệ w = U. Hãy sửa U và kết luận phù hợp, rồi lập báo cáo có căn cứ.",en:"You are reviewing draft calibration certificate CAL-5521 for a 0-16 bar pressure gauge, accuracy class 1.0 (MPE ±0.16 bar). At the 10 bar point the measured error is +0.14 bar. The standard uncertainty budget holds 0.012 bar (reference), 0.009 bar (resolution) and 0.008 bar (repeatability). The contract applies a guard-banded decision rule with w = U. Correct U and the conformity statement, then write an evidence-based report."},reference_title:{vi:"Ngân sách độ không đảm bảo đo & quy tắc quyết định đã duyệt",en:"Approved uncertainty budget & decision rule"},fields:[{id:"VERDICT",label:{vi:"Kết luận phù hợp tại 10 bar",en:"Conformity statement at 10 bar"},initial:"PASS",expected:"FAIL",choices:["PASS","FAIL","CONDITIONAL"],reference:"Quy tắc quyết định của hợp đồng",ref_value:{vi:"Băng bảo vệ w = U; giới hạn chấp nhận = MPE - U; MPE ±0,16 bar",en:"Guard band w = U; acceptance limit = MPE - U; MPE ±0.16 bar"},hint:{vi:"So sánh |sai số| với giới hạn chấp nhận đã trừ băng bảo vệ, không so trực tiếp với MPE.",en:"Compare |error| with the guard-banded acceptance limit, not directly with the MPE."}},{id:"U_EXP",label:{vi:"Độ không đảm bảo đo mở rộng U (bar)",en:"Expanded uncertainty U (bar)"},initial:"0.017",expected:"0.034",reference:"Bảng ngân sách độ không đảm bảo đo",ref_value:{vi:"u chuẩn 0,012; u phân giải 0,009; u lặp lại 0,008 bar; hệ số phủ k = 2",en:"u reference 0.012; u resolution 0.009; u repeatability 0.008 bar; coverage factor k = 2"},hint:{vi:"Bản nháp mới dừng ở độ không đảm bảo chuẩn tổng hợp u_c, còn thiếu một bước của SOP 3.2.",en:"The draft stops at the combined standard uncertainty u_c; one step of SOP 3.2 is missing."}}],sop32:{vi:"u_c = căn bậc hai của tổng bình phương các độ không đảm bảo chuẩn thành phần; U = k x u_c với k = 2 (mức tin cậy khoảng 95%); ghi U đến 0,001 bar.",en:"u_c = square root of the sum of squares of the standard uncertainty components; U = k x u_c with k = 2 (about 95% coverage); state U to 0.001 bar."},context:{label:"LIMS / CAL-5521",metrics:[{label:{vi:"Dải đo",en:"Range"},value:"0-16 bar"},{label:{vi:"MPE cấp 1.0",en:"Class 1.0 MPE"},value:"±0.16 bar"},{label:{vi:"Sai số tại 10 bar",en:"Error at 10 bar"},value:"+0.14 bar"}]},crisis:{vi:"Khách hàng gọi: “Mai đánh giá ISO 9001 rồi, sai số 0,14 vẫn nhỏ hơn 0,16 mà. Ghi PASS giúp anh, không thì anh chuyển sang phòng thí nghiệm khác.” Trưởng nhóm kinh doanh nhắn bạn phát hành ngay.",en:"The customer calls: “Our ISO 9001 audit is tomorrow and 0.14 is still below 0.16. Just mark it PASS or we move to another lab.” The sales lead texts you to issue the certificate now."},options:{safe:{vi:"Giữ kết luận FAIL theo quy tắc quyết định đã thỏa thuận, ghi rõ U, báo trưởng phòng; đề xuất hiệu chỉnh đồng hồ rồi hiệu chuẩn lại, ghi số liệu trước và sau hiệu chỉnh.",en:"Keep the FAIL statement under the agreed decision rule, state U and inform the lab manager; offer to adjust the gauge and recalibrate, reporting as-found and as-left data."},shortcut:{vi:"Ghi PASS theo yêu cầu khách hàng vì sai số vẫn nằm trong MPE, bỏ qua băng bảo vệ.",en:"Mark PASS as the customer asks because the error is within the MPE, ignoring the guard band."},wait:{vi:"Giữ chứng nhận ở trạng thái nháp và chờ kinh doanh tự thương lượng với khách hàng.",en:"Leave the certificate in draft and wait for Sales to negotiate with the customer."}},questions:{vi:["Trình bày cách bạn tính lại U và vì sao sai số +0,14 bar dẫn tới kết luận FAIL theo quy tắc w = U.","Khi khách hàng gây áp lực đổi kết luận, bạn bảo vệ tính khách quan của phòng thí nghiệm theo ISO/IEC 17025 như thế nào?"],en:["Explain how you recalculated U and why the +0.14 bar error leads to a FAIL statement under the w = U rule.","When the customer pressures you to change the statement, how do you protect laboratory impartiality under ISO/IEC 17025?"]},hints:{vi:["Đặt bản nháp cạnh ngân sách độ không đảm bảo đo và kiểm tra từng thành phần đã được tổ hợp đúng cách chưa.","Theo SOP mục 3.2, có u_c rồi vẫn phải nhân hệ số phủ trước khi tính giới hạn chấp nhận.","SOP mục 4.2: kết luận phù hợp không thay đổi theo yêu cầu thương mại; mọi áp lực phải báo trưởng phòng."],en:["Place the draft next to the uncertainty budget and check that every component is combined correctly.","Under SOP 3.2, once you have u_c you still apply the coverage factor before computing the acceptance limit.","SOP 4.2: a conformity statement never changes for commercial reasons; escalate any pressure to the lab manager."]}},learning:{summary:{vi:"Kỹ thuật viên đo lường và hiệu chuẩn so sánh phương tiện đo của doanh nghiệp với chuẩn có liên kết chuẩn đo lường, xác định sai số, ước lượng độ không đảm bảo đo và phát hành giấy chứng nhận hiệu chuẩn. Kết quả của họ quyết định thiết bị có tiếp tục được dùng trong sản xuất, kiểm tra chất lượng và an toàn hay không. Nghề đòi hỏi thao tác cẩn thận, kiểm soát môi trường đo, nắm vững thống kê đo lường và giữ tính khách quan tuyệt đối.",en:"A metrology and calibration technician compares a company's measuring instruments with traceable reference standards, determines errors, evaluates measurement uncertainty and issues calibration certificates. Their results decide whether equipment may remain in use for production, quality control and safety. The role requires careful handling, control of the measuring environment, solid measurement statistics and uncompromising impartiality."},responsibilities:{vi:["Hiệu chuẩn phương tiện đo áp suất, nhiệt độ, khối lượng, kích thước theo quy trình đã phê duyệt.","Kiểm soát điều kiện môi trường (nhiệt độ, độ ẩm, rung) và thời gian ổn định thiết bị trước khi đo.","Ước lượng độ không đảm bảo đo theo GUM và áp dụng quy tắc quyết định khi công bố sự phù hợp.","Lập, soát xét và lưu hồ sơ giấy chứng nhận, bảo đảm truy xuất nguồn gốc đến chuẩn quốc gia.","Quản lý lịch hiệu chuẩn, kiểm tra trung gian chuẩn làm việc và tham gia thử nghiệm thành thạo."],en:["Calibrate pressure, temperature, mass and dimensional instruments to approved procedures.","Control environmental conditions (temperature, humidity, vibration) and stabilization time before measuring.","Evaluate measurement uncertainty per the GUM and apply decision rules when stating conformity.","Prepare, review and archive certificates, ensuring traceability to national standards.","Manage the calibration schedule, run intermediate checks on working standards and join proficiency tests."]},competencies:[{name:{vi:"Thao tác đo chính xác",en:"Precise measurement practice"},desc:{vi:"Lắp đặt, ổn định và đọc số đúng cách; loại trừ sai số thị sai, sai số do nhiệt và do lắp đặt.",en:"Mount, stabilize and read instruments correctly; eliminate parallax, thermal and mounting errors."}},{name:{vi:"Ước lượng độ không đảm bảo đo",en:"Uncertainty evaluation"},desc:{vi:"Xây dựng ngân sách độ không đảm bảo loại A, loại B, tổ hợp và chọn hệ số phủ phù hợp.",en:"Build Type A and Type B uncertainty budgets, combine them and choose the right coverage factor."}},{name:{vi:"Quy tắc quyết định",en:"Decision rules"},desc:{vi:"Áp dụng chấp nhận đơn giản hoặc băng bảo vệ theo thỏa thuận với khách hàng và hướng dẫn ILAC-G8.",en:"Apply simple acceptance or guard bands as agreed with the customer and per ILAC-G8 guidance."}},{name:{vi:"Hệ thống chất lượng phòng thí nghiệm",en:"Laboratory quality system"},desc:{vi:"Tuân thủ ISO/IEC 17025: kiểm soát hồ sơ, xác nhận phương pháp, xử lý công việc không phù hợp.",en:"Follow ISO/IEC 17025: control records, validate methods and handle nonconforming work."}},{name:{vi:"Khách quan & chính trực",en:"Impartiality & integrity"},desc:{vi:"Không để áp lực thương mại chi phối kết quả; báo cáo trung thực cả khi thiết bị không đạt.",en:"Never let commercial pressure influence results; report honestly even when equipment fails."}}],knowledge:{vi:["ISO/IEC 17025:2017 - Yêu cầu chung về năng lực của phòng thử nghiệm và hiệu chuẩn.","Luật Đo lường số 04/2011/QH13 và các văn bản hướng dẫn về chuẩn đo lường, phương tiện đo.","JCGM 100:2008 (GUM) - Hướng dẫn biểu thị độ không đảm bảo đo.","JCGM 200:2012 (VIM) - Từ vựng quốc tế về đo lường học: sai số, độ chụm, liên kết chuẩn.","ILAC-G8:09/2019 - Hướng dẫn về quy tắc quyết định và công bố sự phù hợp.","ISO 10012:2003 - Hệ thống quản lý đo lường cho quá trình đo và thiết bị đo."],en:["ISO/IEC 17025:2017 - General requirements for the competence of testing and calibration laboratories.","Vietnam's Law on Metrology No. 04/2011/QH13 and its guidance on standards and measuring instruments.","JCGM 100:2008 (GUM) - Guide to the expression of uncertainty in measurement.","JCGM 200:2012 (VIM) - International vocabulary of metrology: error, precision, traceability.","ILAC-G8:09/2019 - Guidelines on decision rules and statements of conformity.","ISO 10012:2003 - Measurement management systems for measurement processes and equipment."]},tools:["Bộ hiệu chuẩn áp suất điện tử","Cân piston (dead-weight tester)","Lò hiệu chuẩn nhiệt độ khô","Bộ căn mẫu chuẩn (gauge block)","Phần mềm quản lý phòng thí nghiệm (LIMS)","Bảng tính ngân sách độ không đảm bảo đo"],kpis:{vi:["Tỷ lệ giấy chứng nhận phát hành đúng hạn cam kết.","Số giấy chứng nhận phải thu hồi hoặc sửa do lỗi (mục tiêu bằng 0).","Kết quả thử nghiệm thành thạo đạt |En| <= 1.","Tỷ lệ chuẩn làm việc được kiểm tra trung gian đúng kế hoạch."],en:["Share of certificates issued by the committed date.","Certificates recalled or corrected due to errors (target zero).","Proficiency test results with |En| <= 1.","Share of working standards given intermediate checks on schedule."]},day:[{time:"08:00",vi:"Ghi nhận nhiệt độ, độ ẩm phòng đo; khởi động và ổn định chuẩn làm việc.",en:"Log room temperature and humidity; power up and stabilize the working standards."},{time:"09:00",vi:"Hiệu chuẩn lô đồng hồ áp suất theo chu trình tăng và giảm áp, ghi số liệu thô.",en:"Calibrate a batch of pressure gauges on rising and falling cycles and record raw data."},{time:"11:00",vi:"Tính sai số, độ không đảm bảo đo và áp dụng quy tắc quyết định đã thỏa thuận.",en:"Compute errors and uncertainty and apply the agreed decision rule."},{time:"14:00",vi:"Kiểm tra trung gian chuẩn làm việc bằng chuẩn đối chứng, cập nhật biểu đồ kiểm soát.",en:"Run intermediate checks on working standards against a check standard and update control charts."},{time:"16:30",vi:"Soát xét chéo giấy chứng nhận, lưu hồ sơ trên LIMS và trả lời khách hàng.",en:"Peer-review certificates, archive records in the LIMS and answer customers."}],mistakes:{vi:["Báo cáo độ không đảm bảo chuẩn tổng hợp mà quên nhân hệ số phủ k.","Kết luận PASS chỉ vì sai số nhỏ hơn MPE, bỏ qua độ không đảm bảo và quy tắc quyết định.","Đo khi thiết bị chưa ổn định nhiệt hoặc không ghi điều kiện môi trường vào hồ sơ."],en:["Reporting the combined standard uncertainty without applying the coverage factor k.","Stating PASS only because the error is below the MPE, ignoring uncertainty and the decision rule.","Measuring before thermal stabilization or without recording environmental conditions."]},career:[{vi:"Kỹ thuật viên hiệu chuẩn tập sự",en:"Trainee calibration technician"},{vi:"Kỹ thuật viên đo lường & hiệu chuẩn",en:"Metrology & calibration technician"},{vi:"Kỹ sư đo lường, người ký giấy chứng nhận",en:"Metrology engineer and authorized signatory"},{vi:"Trưởng phòng thí nghiệm hiệu chuẩn",en:"Calibration laboratory manager"}],glossary:[{term:"Traceability",vi:"Tính chất của kết quả đo liên hệ được với chuẩn quốc gia hoặc quốc tế qua chuỗi hiệu chuẩn không đứt đoạn, mỗi bước có độ không đảm bảo xác định.",en:"Property of a result that relates to national or international standards through an unbroken calibration chain, each step with stated uncertainty."},{term:"MPE",vi:"Sai số lớn nhất cho phép của phương tiện đo theo cấp chính xác hoặc quy định kỹ thuật.",en:"Maximum permissible error of an instrument set by its accuracy class or specification."},{term:"Expanded uncertainty U",vi:"Độ không đảm bảo chuẩn tổng hợp nhân hệ số phủ k, cho khoảng chứa giá trị đo với xác suất phủ đã nêu.",en:"Combined standard uncertainty multiplied by a coverage factor k, giving an interval with a stated coverage probability."},{term:"Guard band",vi:"Khoảng trừ vào giới hạn dung sai để giảm rủi ro chấp nhận nhầm thiết bị không đạt.",en:"Margin subtracted from a tolerance limit to reduce the risk of falsely accepting a nonconforming item."},{term:"TUR",vi:"Tỷ số giữa dung sai của phương tiện được hiệu chuẩn và độ không đảm bảo của phép hiệu chuẩn; thường yêu cầu tối thiểu 4:1.",en:"Ratio of the tolerance of the unit under test to the calibration uncertainty; at least 4:1 is commonly required."}],quiz:[{q:{vi:"Độ không đảm bảo chuẩn tổng hợp u_c = 0,015 bar, hệ số phủ k = 2. Độ không đảm bảo mở rộng U là bao nhiêu?",en:"The combined standard uncertainty is u_c = 0.015 bar and the coverage factor k = 2. What is the expanded uncertainty U?"},options:{vi:["0,015 bar","0,030 bar","0,0075 bar","0,225 bar"],en:["0.015 bar","0.030 bar","0.0075 bar","0.225 bar"]},answer:1,explain:{vi:"U = k x u_c = 2 x 0,015 = 0,030 bar, tương ứng mức tin cậy khoảng 95%.",en:"U = k x u_c = 2 x 0.015 = 0.030 bar, corresponding to about 95% coverage."}},{q:{vi:"Theo ISO/IEC 17025:2017, khi công bố sự phù hợp với quy định kỹ thuật, phòng thí nghiệm phải làm gì?",en:"Under ISO/IEC 17025:2017, what must a laboratory do when it issues a statement of conformity to a specification?"},options:{vi:["Chỉ cần ghi sai số đo được","Không cần nêu thêm thông tin nào","Dùng quy tắc khách hàng đề nghị qua điện thoại","Lập văn bản quy tắc quyết định đã áp dụng, có tính đến mức rủi ro"],en:["Only record the measured error","Add no further information","Use whatever rule the customer suggests by phone","Document the decision rule applied, taking the level of risk into account"]},answer:3,explain:{vi:"Chuẩn mực yêu cầu quy tắc quyết định được thỏa thuận, lập thành văn bản và tính đến rủi ro chấp nhận hoặc loại bỏ sai.",en:"The standard requires an agreed, documented decision rule that accounts for the risk of false acceptance or rejection."}},{q:{vi:"Khách hàng đề nghị ghi PASS dù thiết bị không đạt theo quy tắc quyết định. Bạn làm gì?",en:"A customer asks you to state PASS although the instrument fails under the decision rule. What do you do?"},options:{vi:["Giữ kết luận đúng, báo trưởng phòng và đề xuất hiệu chỉnh rồi hiệu chuẩn lại","Ghi PASS kèm chú thích nhỏ cuối trang","Xóa điểm đo không đạt khỏi chứng nhận","Trả thiết bị không có chứng nhận và không giải thích"],en:["Keep the correct statement, inform the manager and offer adjustment and recalibration","Write PASS with a small footnote","Delete the failing point from the certificate","Return the instrument with no certificate or explanation"]},answer:0,explain:{vi:"Tính khách quan là yêu cầu bắt buộc; phương án hợp lệ là hiệu chỉnh thiết bị và ghi cả số liệu trước, sau hiệu chỉnh.",en:"Impartiality is mandatory; the valid path is to adjust the instrument and report both as-found and as-left data."}},{q:{vi:"Dung sai của đồng hồ là ±0,16 bar, độ không đảm bảo mở rộng của phép hiệu chuẩn là 0,04 bar. TUR là bao nhiêu?",en:"The gauge tolerance is ±0.16 bar and the calibration expanded uncertainty is 0.04 bar. What is the TUR?"},options:{vi:["2:1","8:1","4:1","16:1"],en:["2:1","8:1","4:1","16:1"]},answer:2,explain:{vi:"TUR = 0,16 / 0,04 = 4:1, vừa đạt mức tối thiểu thường được yêu cầu.",en:"TUR = 0.16 / 0.04 = 4:1, just meeting the commonly required minimum."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(7)})(window.KKR);
